window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0061", [{"word":"progressive","ipa_uk":"/prəˈɡresɪv/","ipa_us":"/prəˈɡresɪv/","definition_zh":"逐步的；渐进的；进步的；主张改革的；（语法）进行体的；（税）累进的；改革派人士","definition_en":"moving forward in stages, favouring social reform, or naming a verb form that shows an action still in progress","core_image":"沿着台阶一级一级向上走，每一脚都踩在上一级上","scene":"Public health officials described the outbreak as a progressive disease that worsens over months rather than days.","sceneCN":"这里 progressive 是「逐阶段加重的」（第 3 个义项：病情按阶段持续恶化）；句意：公共卫生官员称这次暴发是一种在数月而非数日里逐步加重的疾病。图中可辨识物件：一张张翻过的日历、由浅入深的病情曲线。","pos":[{"tag":"adj.","zh":"渐进的；进步的；主张改革的；进行体的；累进的"},{"tag":"n.","zh":"改革派人士；（语法）进行体形式"}],"collocations":[{"phrase":"progressive change","zh":"渐进式变化"},{"phrase":"progressive disease","zh":"进行性疾病"},{"phrase":"progressive tax","zh":"累进税"},{"phrase":"progressive education","zh":"进步主义教育"},{"phrase":"progressive party","zh":"进步党"},{"phrase":"present progressive","zh":"现在进行时"}],"forms":[{"label":"原级","form":"progressive"},{"label":"比较级","form":"more progressive"},{"label":"最高级","form":"most progressive"},{"label":"复数（作名词）","form":"progressives"},{"label":"副词","form":"progressively"}],"derivatives":[{"word":"progress","pos":"n./v.","zh":"进步；前进；推进"},{"word":"progression","pos":"n.","zh":"渐进；一系列步骤；序列"},{"word":"progressively","pos":"adv.","zh":"逐渐地；越来越多地"},{"word":"regressive","pos":"adj.","zh":"后退的；退步的；逆向的"}],"senses":[{"no":"01","title":"Moving ahead in stages","titleCN":"分阶段向前推进","definition":"describing change that takes place step by step rather than all at once","definitionCN":"指变化不是一次性完成，而是分阶段一步一步发生的","example":"The textbook offers a progressive introduction to statistics, one chapter at a time.","exampleCN":"这本教材一章一节地逐步介绍统计学。","why":"Pro- means 'forward' and gradi means 'to step', so progredi was 'to walk forward'. The suffix -ive turns that walk into an adjective for anything that keeps stepping ahead.","whyCN":"pro- 意为“向前”，gradi 意为“迈步”，因此 progredi 就是“向前走”。后缀 -ive 把这次行走变成形容词，用来形容任何不断向前迈步的事物。"},{"no":"02","title":"Favouring social reform","titleCN":"主张社会改革的","definition":"supporting changes in law, education or the economy in order to improve society","definitionCN":"支持在法律、教育或经济方面作出改变，以求改善社会","example":"The mayor ran on a progressive platform of housing and transit reform.","exampleCN":"这位市长以住房与交通改革的进步纲领参加竞选。","why":"Around 1900 the forward-step image was applied to politics: people who wanted society to move ahead began to call themselves progressive.","whyCN":"大约在 1900 年，向前迈步的意象被用到政治上：希望社会向前走的人开始自称 progressive。"},{"no":"03","title":"Growing worse stage by stage","titleCN":"逐阶段变得更严重","definition":"of an illness: continuing to develop and worsen over time in stages","definitionCN":"指疾病随时间分阶段持续发展、逐渐加重","example":"Doctors warned that the progressive loss of hearing could not be reversed.","exampleCN":"医生警告说，这种逐步加重的听力丧失无法逆转。","why":"Medical usage keeps only the stepping part of the image. The illness keeps advancing step after step, and the direction happens to be bad.","whyCN":"医学用法只保留了意象中“迈步”的部分：疾病一步一步向前推进，只是方向恰好是不好的那一边。"},{"no":"04","title":"Grammar: action still running","titleCN":"语法上的进行体","definition":"the verb form that presents an action as ongoing at a stated moment","definitionCN":"指把动作呈现为在某一时刻仍在持续进行的动词形式","example":"English marks ongoing action with the progressive form, as in 'he is reading'.","exampleCN":"英语用进行体标记正在持续的动作，例如“他正在阅读”。","why":"The action is pictured mid-stride, caught while it is still walking. Grammarians named the be + -ing form after that unfinished step.","whyCN":"动作被画在半路上，正是在它还在走的时候被抓住。语法学家就用这个未完成的步子来命名 be + -ing 形式。"},{"no":"05","title":"Tax rates that climb with income","titleCN":"随收入递增的税率","definition":"of a tax: taking a larger share from higher bands of income","definitionCN":"指对更高收入档次征收更大比例的税","example":"Under a progressive income tax, higher earners pay a larger share of their income.","exampleCN":"在累进所得税制下，收入更高的人按其收入缴纳更大比例。","why":"Each income band steps up to a higher rate, so the tax ladder rises as the figure rises: the staircase image moved into numbers.","whyCN":"每一收入档次都向上迈到更高的税率，税级随收入上升而上升：台阶的意象被搬进了数字里。"},{"no":"06","title":"Ahead of current thinking","titleCN":"观念上走在前面的","definition":"modern in outlook, especially in education, art or social policy","definitionCN":"指在教育、艺术或社会政策上观念现代、走在前面","example":"Her progressive views on assessment upset the traditional examiners.","exampleCN":"她在评估方式上的进步观点让传统考官感到不安。","why":"Here the forward step measures ideas against the present: whatever stands ahead of current practice is called progressive.","whyCN":"这里向前的一步是用当下衡量观念：凡站在现行做法之前的，就被称为 progressive。"},{"no":"07","title":"A supporter of reform","titleCN":"主张改革的改革派","definition":"a person who belongs to or supports a reformist political group","definitionCN":"指属于或支持改革派政治团体的人","example":"The committee split between progressives and conservatives over the zoning plan.","exampleCN":"委员会在分区规划上分裂为改革派与保守派。","why":"The political adjective was turned into a countable noun in the early 20th century, first in American party language.","whyCN":"这个政治形容词在 20 世纪初被转为可数名词，最早出现在美国政党用语中。"},{"no":"08","title":"The progressive form itself","titleCN":"进行体形式本身","definition":"the grammatical form or construction that expresses ongoing action","definitionCN":"指表达持续动作的语法形式或结构","example":"'Is eating' is a progressive, while 'eats' is a simple present.","exampleCN":"“is eating”是进行体，而“eats”是一般现在时。","why":"In grammar books the adjective became a countable noun naming the form; the term is short for 'progressive tense' or 'progressive aspect'.","whyCN":"在语法书里，这个形容词变成可数名词来指形式；这个说法是“进行时态”或“进行体”的简称。"}],"etymology":{"intro":{"en":"Progressive joins pro-, 'forward', with gradi, 'to step', and then adds the adjective suffix -ive. The Latin verb progredi meant 'to walk forward', and its participle progressus gave the noun progress. The adjective simply describes whatever keeps stepping ahead, whether a disease, a tax scale, a verb form or a political programme.","cn":"progressive 由 pro-“向前”、gradi“迈步”与形容词后缀 -ive 组成。拉丁动词 progredi 意为“向前走”，其分词 progressus 产生了名词 progress。这个形容词只是描述任何不断向前迈步的事物——无论是一种疾病、一张税率表、一个动词形式，还是一套政治纲领。"},"items":[{"era":"PIE *ghredh- (reconstructed form)","en":"The root behind Latin gradi, 'to step', is reconstructed as *ghredh-. It is generally believed to be the source of the Latin words for step and grade.","cn":"拉丁 gradi“迈步”背后的词根被重构为 *ghredh-，一般认为它是拉丁语中表示“步、等级”的一组词的来源。"},{"era":"LATIN gradi / gradus","en":"Gradi was a deponent verb meaning 'to walk, to step'. Its noun partner gradus meant 'a step' and also 'a rank or degree', and both feed the modern word family.","cn":"gradi 是异态动词，意为“走、迈步”。其名词伙伴 gradus 表示“一步”，也表示“等级、程度”，两者都滋养了现代词族。"},{"era":"LATIN progredi / progressus","en":"The prefix added direction: progredi meant 'to step forward', and its past participle progressus became the noun for forward movement.","cn":"前缀赋予方向：progredi 意为“向前迈步”，其过去分词 progressus 成为表示“前进”的名词。"},{"era":"17C. FRENCH progressif","en":"French progressif and Medieval Latin progressivus gave English progressive. Early uses were physical: a progressive motion, a progressive disease.","cn":"法语 progressif 与中古拉丁 progressivus 给英语带来了 progressive。早期用法是物理性的：向前运动、进行性疾病。"},{"era":"19C. POLITICS AND TAX","en":"Reform politics borrowed the forward image: a progressive wanted society to move ahead. Progressive taxation, with rates rising band by band, uses the same staircase in numbers.","cn":"改革政治借用了向前的意象：progressive 想让社会向前走。累进税制让税率逐档上升，把同一座台阶搬进了数字里。"},{"era":"19C–20C. GRAMMAR","en":"Grammarians named the be + -ing form the progressive because it presents an action caught in the middle of happening, not finished.","cn":"语法学家把 be + -ing 形式命名为进行体，因为它呈现的是发生在半途、尚未结束的动作。"}]},"similar":{"note":{"en":"The look-alike group separates the noun progress, the abstract progression, the adverb and the opposite-prefix regressive. The meaning group contrasts kinds of forward movement and kinds of reform.","cn":"形近组区分名词 progress、抽象名词 progression、副词形式与反向前缀的 regressive；词义组比较不同类型的向前推进与不同类型的改革主张。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"progress","ipa":"/ˈprəʊɡres/","tag":"noun / verb","definition":"forward movement or improvement; to move forward. It names the movement itself, while progressive describes something that has that character.","definitionCN":"向前运动或改进；向前推进。它命名运动本身，而 progressive 描述具备这种性质的事物。"},{"word":"progression","ipa":"/prəˈɡreʃn/","tag":"noun","definition":"a series of steps or stages in order. It stresses sequence, while progressive stresses the direction of travel.","definitionCN":"按顺序排列的一系列步骤或阶段。它强调次序，而 progressive 强调行进方向。"},{"word":"progressively","ipa":"/prəˈɡresɪvli/","tag":"adverb","definition":"in stages, or increasingly. It turns the adjective into a statement about how something happens.","definitionCN":"分阶段地，或越来越……地。它把形容词转为对发生方式的陈述。"},{"word":"regressive","ipa":"/rɪˈɡresɪv/","tag":"adjective","definition":"moving backward, especially undoing reform. It is built on the same Latin step but with re- 'back' instead of pro- 'forward'.","definitionCN":"向后退的，尤指取消改革。它建立在同一个拉丁“步”词根上，只是用 re-“向后”取代了 pro-“向前”。"}]},{"heading":"NEAR MEANING","entries":[{"word":"advanced","ipa":"/əˈvɑːnst/","tag":"adjective","definition":"far along in development. It says where something stands, not that it moves in stages.","definitionCN":"发展程度高的。它说明某物所处的位置，而不表示它分阶段推进。"},{"word":"gradual","ipa":"/ˈɡrædʒuəl/","tag":"adjective","definition":"happening slowly by small degrees. It shares the step image but carries no political or grammatical sense.","definitionCN":"以微小程度缓慢发生的。它共享台阶意象，但不含政治或语法含义。"},{"word":"continuous","ipa":"/kənˈtɪnjuəs/","tag":"adjective","definition":"going on without a break. It stresses an unbroken span, while progressive stresses a series of advancing stages.","definitionCN":"不中断地持续。它强调连续不断，而 progressive 强调一连串前进的阶段。"},{"word":"reformist","ipa":"/rɪˈfɔːmɪst/","tag":"adjective / noun","definition":"favouring gradual change in institutions. It is close to senses 02 and 07 but names the doctrine rather than the forward image.","definitionCN":"主张对制度作渐进改革的。它接近第 2 与第 7 义项，但命名的是主张，而非向前的意象。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks build the word as pro + grad + ive, then let the staircase cover stages, illness, tax bands, grammar and politics.","cn":"这些记忆钩把词拆成 pro + grad + ive，再用台阶意象串起阶段、病情、税档、语法与政治。"},"normal":[{"en":"Split it into pro + gress + ive: forward, step, adjective. The word literally means 'stepping forward'.","cn":"拆成 pro + gress + ive：向前、迈步、形容词。这个词字面就是“向前迈步的”。"},{"en":"Picture a staircase: every step stands on the one below, so nothing jumps to the top.","cn":"想象一座楼梯：每一级都踩在下一级上，没有哪一步能跳到顶端。"},{"en":"A progressive disease climbs the same stairs, only downward in terms of health.","cn":"进行性疾病爬的是同一座楼梯，只是在健康上朝下走。"},{"en":"In a progressive tax, each income band sits one stair higher than the last.","cn":"在累进税中，每一收入档次都比上一档高一级台阶。"},{"en":"A progressive in politics is someone who wants the whole society to take the next step.","cn":"政治上的改革派，就是希望整个社会迈出下一步的人。"}],"abstract":[{"en":"Think of time as a ladder rather than a line: 'progressive' always implies rungs, never a smooth slope.","cn":"把时间想成梯子而不是直线：progressive 总暗示横档，而不是平滑斜坡。"},{"en":"Notice that the medical sense keeps the motion but drops the hope: stepping forward can also mean going further into illness.","cn":"注意医学义保留了运动却丢掉了希望：向前迈步也可能意味着更深地陷入疾病。"},{"en":"Hold present and progressive apart: one stands still at a point in time, the other is photographed mid-stride.","cn":"把“现在”与“进行”分开：一个静止在时间点上，另一个被拍在迈步的半途。"}]},"examples":[{"en":"The school adopted a progressive curriculum that adds one skill level at a time.","cn":"这所学校采用了逐级增加技能的渐进式课程。"},{"en":"Specialists tracked the progressive weakening of the patient's muscles.","cn":"专家追踪了病人肌肉逐步变弱的过程。"},{"en":"Economists debated whether a progressive tax on vacant land would cool the market.","cn":"经济学家争论对闲置土地征收累进税是否能给市场降温。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“扑罗格瑞斯”：一步一扑向前走，越走越进步。","word":"progressive"},"root":"拉丁 progredi“向前走”（pro- 向前 + gradi 迈步），过去分词 progressus，加 -ive 构成形容词；核心意象是“一级一级往前走”。","sensesIntro":{"en":"All eight senses keep someone or something walking forward. A course moves through levels, an illness moves through stages, a tax scale moves through bands, a verb form catches an action mid-stride, a reformer wants society to take the next step, and grammar turns the adjective into a noun.","cn":"八个义项都保留了“有人在向前走”：课程逐级推进，疾病逐段发展，税率逐档上升，动词形式把动作抓在半途，改革者希望社会迈出下一步，语法则把这个形容词变成名词。"},"semanticMap":{"core":{"en":"Stepping forward, one stage at a time, until the new position stands ahead of the old one.","cn":"一步一步向前，每迈一步都进入新阶段，直到新的位置站在旧位置之前。"},"chain":["STEP","FORWARD","STAGE","REFORM","ONGOING","RISE"],"branches":[{"senses":"01 · 03","en":"STAGES: change arrives one step at a time, whether it improves health or worsens it.","cn":"阶段：变化一步一步到来，无论它让健康变好还是变坏。"},{"senses":"02 · 07","en":"POLITICS: the forward step becomes a demand for reform and a name for its supporters.","cn":"政治：向前的一步变成改革诉求，也成为支持者的名称。"},{"senses":"04 · 08","en":"GRAMMAR: the action is shown mid-step, and the form itself takes the adjective as a name.","cn":"语法：动作被展示在半步之中，形式本身也借用了这个形容词作名称。"},{"senses":"05","en":"NUMBERS: the staircase becomes tax bands that climb with income.","cn":"数字：台阶变成随收入上升的税档。"},{"senses":"06","en":"OUTLOOK: ideas are ranked by how far ahead of present practice they stand.","cn":"观念：思想按它们领先当下做法的程度来排序。"}]},"affixes":{"intro":{"en":"Progressive stacks pro-, the verb gradi and the adjective suffix -ive. The items below show the same base with other endings, and the opposite prefix re- building the reverse idea.","cn":"progressive 叠加了 pro-、动词 gradi 与形容词后缀 -ive。下列条目展示同一词基配其他词尾，以及反向前缀 re- 构成的相反概念。"},"latinIntro":{"en":"The Latin entries give the verb, its noun and its participle. They explain why one word family covers walking, ranking, taxation and grammar.","cn":"拉丁语条目给出动词、名词与分词，解释了为什么同一词族能覆盖行走、等级、征税与语法。"},"items":[{"word":"progressive","structure":"pro- + gradi + -ive","meaning":"moving forward in stages; favouring reform","meaningCN":"分阶段向前的；主张改革的","example":"The reform was introduced in progressive stages.","exampleCN":"这项改革分阶段引入。"},{"word":"progress","structure":"pro- + gradi (noun from progressus)","meaning":"forward movement; improvement","meaningCN":"前进；进步","example":"The report noted steady progress in literacy.","exampleCN":"报告指出识字率稳步提高。"},{"word":"progression","structure":"progress + -ion (process noun)","meaning":"a series of ordered steps","meaningCN":"有序的一系列步骤","example":"The progression from trainee to supervisor takes years.","exampleCN":"从实习生到主管的晋升需要数年。"},{"word":"progressively","structure":"progressive + -ly (adverb)","meaning":"in stages; increasingly","meaningCN":"逐步地；越来越","example":"The light faded progressively after sunset.","exampleCN":"日落之后光线逐渐变暗。"},{"word":"progressiveness","structure":"progressive + -ness (abstract noun)","meaning":"the quality of favouring advance or reform","meaningCN":"进步性或改革倾向","example":"Critics questioned the progressiveness of the plan.","exampleCN":"批评者质疑该方案的进步性。"},{"word":"regressive","structure":"re- (back) + gradi + -ive","meaning":"moving backward; undoing reform","meaningCN":"后退的；取消改革的","example":"The new fee was criticized as a regressive measure.","exampleCN":"这项新收费被批评为倒退措施。"},{"word":"gradation","structure":"gradus + -ation (noun of process)","meaning":"arrangement in steps or degrees","meaningCN":"按等级或程度的排列","example":"The paint comes in fine gradations of grey.","exampleCN":"这种颜料有细致的灰色层次。"},{"word":"gradual","structure":"gradus + -al (adjective)","meaning":"happening slowly by small steps","meaningCN":"逐渐的；逐步的","example":"Recovery was gradual but complete.","exampleCN":"康复虽然缓慢，但很彻底。"}],"latinEntries":[{"word":"gradi","structure":"deponent verb, 3rd conjugation","meaning":"to step, to walk","meaningCN":"迈步；行走"},{"word":"gradus","structure":"noun, 4th declension","meaning":"a step; a rank or degree","meaningCN":"一步；等级；程度"},{"word":"progressus","structure":"past participle of progredi","meaning":"having stepped forward; forward movement","meaningCN":"已向前迈步的；前进"}]}},{"word":"projection","ipa_uk":"/prəˈdʒekʃn/","ipa_us":"/prəˈdʒekʃn/","definition_zh":"预测；推算；投掷；投影；突出物；投影图；（心理）投射；（嗓音）发送","definition_en":"a future figure calculated from present data, an image thrown onto a surface, a part that juts out, or the act of attributing one's own feelings to someone else","core_image":"把一块石子向前扔出去，它在墙上落成一个亮点","scene":"Analysts raised their sales projection for the fourth quarter after a strong summer.","sceneCN":"这里 projection 是「预测数字」（第 1 个义项：用现有数据向前推算）；句意：夏季业绩强劲之后，分析师上调了第四季度的销售预测。图中可辨识物件：向前伸出的折线箭头、标着数字的柱状图。","pos":[{"tag":"n.","zh":"预测；投影；突出物；投射；（嗓音）发送"}],"collocations":[{"phrase":"sales projection","zh":"销售预测"},{"phrase":"population projection","zh":"人口预测"},{"phrase":"projection screen","zh":"投影幕"},{"phrase":"map projection","zh":"地图投影"},{"phrase":"psychological projection","zh":"心理投射"},{"phrase":"vocal projection","zh":"嗓音投射"}],"forms":[{"label":"单数","form":"projection"},{"label":"复数","form":"projections"},{"label":"动词","form":"project"},{"label":"执行者名词","form":"projector"}],"derivatives":[{"word":"project","pos":"n./v.","zh":"项目；投射；预测；伸出"},{"word":"projector","pos":"n.","zh":"投影仪；放映机"},{"word":"projective","pos":"adj.","zh":"投影的；射影的"},{"word":"projectionist","pos":"n.","zh":"放映员"}],"senses":[{"no":"01","title":"A figure thrown into the future","titleCN":"向未来推算出的数字","definition":"a calculation of a future amount based on present trends and data","definitionCN":"根据当前趋势与数据推算出的未来数量","example":"The latest projection puts city population at nine million by 2040.","exampleCN":"最新预测认为到 2040 年该市人口将达九百万。","why":"A projection is literally something thrown forward: present figures are cast ahead onto a future date, and where they land is the forecast.","whyCN":"projection 字面上是被向前扔出的东西：把当下的数字抛向未来的某个日期，落点就是预测值。"},{"no":"02","title":"The act of throwing forward","titleCN":"向前投掷的动作","definition":"the physical act of casting something forward through the air","definitionCN":"把某物向前抛向空中的物理动作","example":"The machine measured the projection of the ball with compressed air.","exampleCN":"这台机器用压缩空气测量小球的抛射。","why":"The oldest sense is physical. Latin proicere meant 'to throw forth', and the noun named the throwing itself.","whyCN":"最古老的义项是物理性的。拉丁 proicere 意为“向前抛出”，这个名词命名的就是抛掷动作本身。"},{"no":"03","title":"An image thrown onto a surface","titleCN":"投射到平面上的影像","definition":"the picture that light throws onto a screen or wall","definitionCN":"光线投到屏幕或墙面上形成的图像","example":"The lecture began with a projection of the earliest known map.","exampleCN":"讲座从一张已知最早地图的投影开始。","why":"Light is thrown forward onto a screen, and the image that lands there is called a projection. The word moved from the throw to the result.","whyCN":"光被向前投到屏幕上，落在那里形成的图像就叫投影。这个词从“抛”转到了“抛出的结果”。"},{"no":"04","title":"A part that juts out","titleCN":"向外突出的部分","definition":"a part of a surface or structure that stands out beyond the rest","definitionCN":"表面或结构中超出其余部分、向外伸出的部位","example":"The climbers rested on a narrow projection of rock above the valley.","exampleCN":"攀登者在山谷上方一块狭窄的岩石突出部休息。","why":"A rock face that pushes itself out from the cliff is a projection in the literal spatial sense: it is thrown beyond the main surface.","whyCN":"从崖壁上向外顶出的岩面就是空间意义上的突出物：它被抛到了主表面之外。"},{"no":"05","title":"Mapping a curved world onto a plane","titleCN":"把曲面世界摊到平面上","definition":"a method or result of representing the curved surface of the earth on a flat map","definitionCN":"把地球曲面表示在平面地图上的方法或结果","example":"The Mercator projection makes high latitudes look far larger than they are.","exampleCN":"墨卡托投影让高纬度地区显得比实际大得多。","why":"Geometers throw the points of a sphere forward onto a flat surface. The resulting map is still called a projection, and every one distorts something.","whyCN":"几何学家把球面上的点向前投到平面上。得到的图仍叫投影，而每一种投影都会扭曲某些东西。"},{"no":"06","title":"Seeing your own feeling in someone else","titleCN":"把自身情绪归到别人身上","definition":"the unconscious act of attributing one's own emotions or faults to another person","definitionCN":"无意识地把自己的情绪或缺点归到他人身上的行为","example":"Her suspicion of the new colleague was pure projection of her own ambition.","exampleCN":"她对新同事的怀疑纯粹是自己野心的投射。","why":"Psychology borrowed the throwing image: an inner feeling is thrown outward and then appears to belong to someone else.","whyCN":"心理学借用了抛掷的意象：内心的情绪被抛向外部，然后看起来像是别人拥有的。"},{"no":"07","title":"Sending the voice to the back row","titleCN":"把嗓音送到最后一排","definition":"the technique of speaking or singing so that the voice carries to the far end of a space","definitionCN":"说话或歌唱时把声音送达空间远端的技巧","example":"The voice coach worked on projection rather than volume.","exampleCN":"嗓音教练练的是投射，而不是音量。","why":"An actor throws the voice forward to the back of the hall; the noun names that outward sending, not mere loudness.","whyCN":"演员把嗓音向前抛到大厅最后排；这个名词命名的是向外的投送，而不只是响度。"},{"no":"08","title":"A plan thrown ahead of time","titleCN":"提前抛出的设想方案","definition":"a planned shape for future activity, often less numerical than a forecast","definitionCN":"对未来活动的设想，通常比预测数字更偏计划性","example":"The studio's five-year projection included two new research wings.","exampleCN":"该工作室的五年规划包括两座新的研究楼。","why":"A plan is thrown ahead as a shape for the future. It sits close to sense 01, but here intention leads and arithmetic follows.","whyCN":"计划是被提前抛出、作为未来轮廓的东西。它靠近第 1 义项，但这里由意图主导，算术随后。"}],"etymology":{"intro":{"en":"Projection is pro- 'forth' plus iacere 'to throw', the same verb behind eject, inject and reject. Latin proicere threw something forward, and the noun proiectio named both the throw and the thing thrown out. English added forecasting, mapping and psychology to that single physical gesture.","cn":"projection 是 pro-“向前”加 iacere“抛”，与 eject、inject、reject 同出一个动词。拉丁 proicere 表示把东西向前抛出，名词 proiectio 既指抛掷，也指被抛出的东西。英语随后把预测、制图与心理学都加到这个单一的物理动作上。"},"items":[{"era":"PIE *yeh₁- (reconstructed form)","en":"The root behind Latin iacere, 'to throw', is reconstructed as *yeh₁-. The reconstruction is generally accepted, though the exact laryngeal shape remains debated.","cn":"拉丁 iacere“抛”背后的词根被重构为 *yeh₁-。这一重构一般被接受，但喉音的具体形态仍有争议。"},{"era":"LATIN iacere / iactus","en":"Iacere was a third-conjugation verb meaning 'to throw, cast, fling'. Its past participle iactus appears inside the whole family of -ject words.","cn":"iacere 是第三变位动词，意为“抛、投、扔”。其过去分词 iactus 出现在整个 -ject 词族之中。"},{"era":"LATIN proicere / proiectus","en":"Pro- added direction: proicere meant 'to throw forth'. The participle proiectus also described a part of a building that sticks out.","cn":"pro- 赋予方向：proicere 意为“向前抛出”。分词 proiectus 也用来描述建筑中向外伸出的部分。"},{"era":"LATE LATIN proiectio","en":"The noun proiectio covered both the act of throwing out and the object thrown forward, which is why English projection covers actions, images and bumps alike.","cn":"名词 proiectio 同时涵盖抛出动作与被抛出的物体，因此英语 projection 能同时指动作、影像与凸起。"},{"era":"17C. OPTICS AND MAPS","en":"The invention of the magic lantern and the rise of cartography gave the word its image and map senses. Geometers spoke of projecting the globe onto a plane.","cn":"幻灯机的发明与地图学的兴起赋予这个词影像义与地图义。几何学家谈论把地球投到平面上。"},{"era":"19C–20C. FORECAST AND PSYCHOLOGY","en":"Statistics extended projection to future figures, and Freud's German term for the defence mechanism was translated as projection in English.","cn":"统计学把 projection 扩展到未来数字，弗洛伊德用于防御机制的德语术语在英语中被译作 projection。"}]},"similar":{"note":{"en":"The look-alike group separates project, projector and the genuinely different prediction. The meaning group compares estimating, sticking out and throwing outward.","cn":"形近组区分 project、projector 与真正不同源的 prediction；词义组比较“估计”“外凸”与“向外抛出”三类近义表达。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"project","ipa":"/ˈprɒdʒekt/ (noun), /prəˈdʒekt/ (verb)","tag":"noun / verb","definition":"a planned piece of work, or to throw an image forward. The noun is the plan; the verb is the act behind every sense of projection.","definitionCN":"指有计划的工程，或向前投出影像。名词是计划，动词是 projection 各义项背后的动作。"},{"word":"projector","ipa":"/prəˈdʒektə/","tag":"noun","definition":"the machine that throws light and images onto a screen. It names the device, not the result on the screen.","definitionCN":"把光与影像投到屏幕上的机器。它命名设备，而不是屏幕上的结果。"},{"word":"prediction","ipa":"/prɪˈdɪkʃn/","tag":"noun","definition":"a statement about what will happen. It comes from prae + dicere 'say before', a completely different root from iacere 'throw'.","definitionCN":"关于将要发生之事的陈述。它来自 prae + dicere“事先说出”，与 iacere“抛”完全不同源。"},{"word":"projectionist","ipa":"/prəˈdʒekʃənɪst/","tag":"noun","definition":"the person who operates a projector. It is a person noun, not the image or the forecast.","definitionCN":"操作放映机的人。它是人称名词，不是影像或预测。"}]},{"heading":"NEAR MEANING","entries":[{"word":"forecast","ipa":"/ˈfɔːkɑːst/","tag":"noun / verb","definition":"a statement of what is expected, often about weather or economics. It is the everyday word for sense 01.","definitionCN":"对预期情况的陈述，常用于天气或经济。它是第 1 义项的日常说法。"},{"word":"estimate","ipa":"/ˈestɪmət/","tag":"noun","definition":"an approximate calculation of cost, size or amount. It may look backward as well as forward, while a projection always looks ahead.","definitionCN":"对费用、规模或数量的近似计算。它既可回望也可前瞻，而 projection 总是向前看。"},{"word":"protrusion","ipa":"/prəˈtruːʒn/","tag":"noun","definition":"something that bulges out from a surface. It is the plain descriptive word for sense 04, without the Latin throwing image.","definitionCN":"从表面凸出的东西。它是第 4 义项的平实描述词，不含拉丁“抛”的意象。"},{"word":"extrapolation","ipa":"/ˌekstrəˈpeɪʃn/","tag":"noun","definition":"the act of extending known data into unknown territory. It explains the arithmetic inside a projection.","definitionCN":"把已知数据延伸到未知领域的做法。它解释了预测数字内部的算术。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks hold on to the single gesture of throwing forward, then let it fan out into forecasts, screens, bumps, maps, feelings and voices.","cn":"这些记忆钩抓住“向前抛出”这一个动作，再让它分出预测、屏幕、凸起、地图、情绪与嗓音。"},"normal":[{"en":"Split it as pro + ject + ion: forward + thrown + noun. A projection is a forward-throw turned into a thing.","cn":"拆成 pro + ject + ion：向前、抛出、名词。projection 就是“向前抛”变成的东西。"},{"en":"Picture a stone leaving your hand and landing as a bright spot on a wall.","cn":"想象一块石子离开你的手，在墙上落成一个亮点。"},{"en":"A rock that juts from a cliff is the same stone, only frozen mid-flight.","cn":"从崖壁伸出的岩石就是同一块石子，只是凝固在半空。"},{"en":"Light thrown onto a screen makes a projection; a voice thrown to the back row does the same with sound.","cn":"光投到屏幕上形成投影；嗓音抛到最后一排则是声音上的同一件事。"},{"en":"A sales projection is a number thrown ahead of today onto next quarter.","cn":"销售预测就是把一个数字从今天抛到下一季度。"}],"abstract":[{"en":"Notice that the word never means receiving: projection is always outward, from a source to a surface or a person.","cn":"注意这个词从不表示“接收”：projection 永远是向外的，从源头到某个表面或某个人。"},{"en":"The psychological sense is the same geometry with feelings as the projectile.","cn":"心理义是同一套几何，只是把情绪当作抛射物。"},{"en":"Keep the direction in mind: what is thrown forward may land as a forecast, an image, a bulge or an accusation.","cn":"记住方向：被向前抛出的东西，可能落成预测、影像、凸起，或一句指责。"}]},"examples":[{"en":"The company cut its annual projection after two weak quarters.","cn":"两个季度表现疲弱之后，公司下调了年度预测。"},{"en":"A tall projection of granite marked the edge of the glacier.","cn":"一块高耸的花岗岩突出部标出了冰川的边缘。"},{"en":"Critics called the accusation against the reporter a case of projection.","cn":"批评者称对这名记者的指责是一种投射。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“扑若杰克神”：向前一扑，把影子投到墙上，像变戏法。","word":"projection"},"root":"拉丁 proicere“向前抛出”（pro- 向前 + iacere 抛），过去分词 proiectus，名词 proiectio；核心是“把东西抛到前方，落成影像或凸起”。","sensesIntro":{"en":"One Latin verb, 'throw forward', explains all eight senses. Numbers are thrown into next quarter, a ball into the air, light onto a screen, a cliff face beyond the wall, a globe onto paper, a feeling onto a colleague, a voice to the back row, and a plan into the future.","cn":"一个拉丁动词“向前抛出”解释了八个义项：数字被抛向下一季度，球被抛向空中，光被抛到屏幕，崖面被抛到墙外，地球被摊到纸上，情绪被抛给同事，嗓音被抛到最后一排，计划被抛向未来。"},"semanticMap":{"core":{"en":"Something is cast outward from its source and lands somewhere else, where it is read as an image, a shape or a figure.","cn":"某物从源头向外抛出，落在别处，并在那里被读成影像、形状或数字。"},"chain":["THROW","FORWARD","LAND","IMAGE","SHAPE","FIGURE"],"branches":[{"senses":"01 · 08","en":"FUTURE: present material is thrown ahead and lands as a forecast or a plan.","cn":"未来：当下材料被抛向前方，落成预测或计划。"},{"senses":"02 · 03","en":"LIGHT: the physical throw becomes an image on a screen.","cn":"光：物理抛掷变成屏幕上的影像。"},{"senses":"04","en":"SOLID: the thrown-out part freezes into a bump or a ledge.","cn":"固体：抛出的部分凝固为凸起或岩台。"},{"senses":"05","en":"MAP: points of a sphere are thrown onto a flat sheet.","cn":"地图：球面上的点被投到平面纸上。"},{"senses":"06 · 07","en":"SELF AND VOICE: feeling or sound is sent outward and received by others.","cn":"自我与声音：情绪或声音被向外送出，由他人接收。"}]},"affixes":{"intro":{"en":"Projection is built from pro-, the verb iacere and the noun suffix -io. The items below keep the same root and vary the prefix, which is how eject, inject and reject stay visibly related.","cn":"projection 由 pro-、动词 iacere 与名词后缀 -io 构成。下列条目保留同一词根而更换前缀，eject、inject、reject 正是因此看得出亲缘关系。"},"latinIntro":{"en":"The Latin entries give the throwing verb and its two derived forms. They show that the -ject family is a set of directions added to one throw.","cn":"拉丁语条目给出“抛”动词及其两个派生形式，说明 -ject 词族就是给同一次抛掷加上不同方向。"},"items":[{"word":"projection","structure":"proicere + -io (noun of act)","meaning":"a forecast, an image or a protruding part","meaningCN":"预测、影像或突出部分","example":"The projection showed a steady rise in enrolment.","exampleCN":"预测显示入学人数稳步上升。"},{"word":"project","structure":"proicere (pro- + iacere)","meaning":"to throw forward; a planned undertaking","meaningCN":"向前投出；有计划的工程","example":"The team will project the design onto the wall.","exampleCN":"团队会把设计投到墙上。"},{"word":"projector","structure":"project + -or (instrument noun)","meaning":"a device for throwing images","meaningCN":"投射影像的设备","example":"The projector lamp failed during the talk.","exampleCN":"讲座进行时投影仪灯泡坏了。"},{"word":"projectionist","structure":"projection + -ist (person noun)","meaning":"the person who runs a projector","meaningCN":"操作放映机的人","example":"The projectionist threaded the film by hand.","exampleCN":"放映员手工把胶片穿进机器。"},{"word":"projective","structure":"projection + -ive (adjective)","meaning":"relating to projection or projective geometry","meaningCN":"投影的；射影几何的","example":"The course covers projective transformations.","exampleCN":"这门课涵盖射影变换。"},{"word":"projecting","structure":"project + -ing (participle)","meaning":"sticking out beyond a surface","meaningCN":"向外伸出的","example":"A projecting beam held up the roof.","exampleCN":"一根外伸的横梁支撑着屋顶。"},{"word":"eject","structure":"e- (out) + iacere","meaning":"to throw out, often forcefully","meaningCN":"弹出；喷出；驱逐","example":"The machine ejects the finished part.","exampleCN":"机器把成品弹出。"},{"word":"inject","structure":"in- (into) + iacere","meaning":"to throw something into","meaningCN":"注入；注射","example":"The nurse injected the vaccine into his arm.","exampleCN":"护士把疫苗注射进他的手臂。"},{"word":"reject","structure":"re- (back) + iacere","meaning":"to throw back; to refuse","meaningCN":"拒绝；退回","example":"The editor rejected the draft within a week.","exampleCN":"编辑一周内退回了稿件。"}],"latinEntries":[{"word":"iacere","structure":"3rd conjugation verb","meaning":"to throw, to cast","meaningCN":"抛；投；扔"},{"word":"proicere","structure":"pro- + iacere","meaning":"to throw forward","meaningCN":"向前抛出"},{"word":"proiectus","structure":"past participle of proicere","meaning":"thrown forward; projecting","meaningCN":"向前抛出的；外凸的"}]}},{"word":"prominence","ipa_uk":"/ˈprɒmɪnəns/","ipa_us":"/ˈprɑːmɪnəns/","definition_zh":"显要地位；声望；突出物；隆起；（天文）日珥；（地质）高地；显著","definition_en":"the state of being important or well known, a part that bulges out, or a glowing arch of gas above the sun's surface","core_image":"平地上有一块石头明显高出周围，所有视线都被它吸过去","scene":"The young researcher rose to prominence after her study on coral bleaching was widely cited.","sceneCN":"这里 prominence 是「崭露头角后的显要地位」（第 1 个义项：从众人中突出、被广泛注意）；句意：她关于珊瑚白化的研究被广泛引用后，这位年轻研究者声名鹊起。图中可辨识物件：人群之上高出半头的身影、被引用的论文页。","pos":[{"tag":"n.","zh":"显要地位；声望；突出物；日珥；显著"}],"collocations":[{"phrase":"rise to prominence","zh":"崭露头角；声名鹊起"},{"phrase":"come to prominence","zh":"开始受到瞩目"},{"phrase":"a prominence on the surface","zh":"表面上的一处突起"},{"phrase":"solar prominence","zh":"日珥"},{"phrase":"bony prominence","zh":"骨性隆凸"},{"phrase":"give prominence to","zh":"突出；强调"}],"forms":[{"label":"单数","form":"prominence"},{"label":"复数（多指多个突起）","form":"prominences"},{"label":"形容词","form":"prominent"},{"label":"副词","form":"prominently"}],"derivatives":[{"word":"prominent","pos":"adj.","zh":"突出的；显要的；著名的"},{"word":"prominently","pos":"adv.","zh":"显眼地；显著地"},{"word":"eminence","pos":"n.","zh":"卓越；高地；显赫地位"},{"word":"imminent","pos":"adj.","zh":"即将发生的（同源前缀不同）"}],"senses":[{"no":"01","title":"Standing out among others","titleCN":"在众人中突出而显要","definition":"the state of being important, noticeable or well known in a field","definitionCN":"在某一领域中重要、惹人注意或广为人知的状态","example":"The discovery brought the small laboratory to international prominence.","exampleCN":"这一发现让这家小实验室在国际上声名显要。","why":"Prominere meant 'to stand out from a surface'. Move the image from rock to reputation and you get the social sense: a person who stands out from the crowd.","whyCN":"prominere 意为“从表面突出”。把意象从岩石移到名声，就得到社会义：一个从人群中凸显出来的人。"},{"no":"02","title":"A raised part of a surface","titleCN":"表面上凸起的部分","definition":"a part of a surface that rises above the surrounding level","definitionCN":"高出周围水平面的表面部位","example":"A small prominence on the handle helps the thumb grip it.","exampleCN":"手柄上一处小小的凸起帮助拇指抓握。","why":"The noun began with the body and the landscape: any bump that pushed itself forward from a flat surface was a prominence.","whyCN":"这个名词最初用于身体与地貌：任何从平面向前顶出的凸块都叫 prominence。"},{"no":"03","title":"Being impossible to miss","titleCN":"显眼、不易忽略","definition":"the quality of attracting attention because of position, size or contrast","definitionCN":"因位置、尺寸或对比而吸引注意的性质","example":"The warning label was placed with such prominence that no buyer could miss it.","exampleCN":"警示标签被放在如此显眼的位置，没有买家会看不到。","why":"A thing that sticks out is naturally seen first. The abstract noun keeps that visual fact and applies it to labels, errors and headlines.","whyCN":"突出的东西自然最先被看到。这个抽象名词保留了这个视觉事实，并把它用到标签、错误与标题上。"},{"no":"04","title":"A flame arch above the sun","titleCN":"太阳上方的气体拱焰","definition":"a large, glowing cloud of gas extending from the sun's surface into its atmosphere","definitionCN":"从太阳表面伸入大气层的巨大发光气体云","example":"During the eclipse, a huge prominence was visible at the moon's edge.","exampleCN":"日食期间，月球边缘可见一道巨大的日珥。","why":"Astronomers needed a word for a part of the sun that projects beyond its disc, and borrowed the Latin term for a projecting part.","whyCN":"天文学家需要一个词来指太阳圆盘之外伸出的部分，就借用了拉丁语里表示“突出部分”的词。"},{"no":"05","title":"A bony bump named by anatomists","titleCN":"解剖学命名的骨性隆起","definition":"a raised area of bone, especially one that can be felt through the skin","definitionCN":"骨头上凸起的区域，尤指能隔着皮肤摸到的部位","example":"The doctor pressed the prominence at the base of the wrist.","exampleCN":"医生按压腕部基底的骨性隆凸。","why":"Anatomy adopted the same descriptive noun for landmarks on bone, where a prominence is exactly what the fingers feel.","whyCN":"解剖学沿用同一个描述性名词来指骨性标志，因为在骨头上，突出物正是手指摸到的东西。"},{"no":"06","title":"High ground in a landscape","titleCN":"地貌上的高地","definition":"a hill, ridge or other raised feature standing above the surrounding land","definitionCN":"高出周围地面的山丘、山脊或其他隆起地形","example":"The village sits on a rocky prominence above the flood plain.","exampleCN":"村庄坐落在洪泛平原之上的一处岩石高地。","why":"Geographers use the word for terrain that rises above its surroundings, keeping the literal outward bulge at the scale of a landscape.","whyCN":"地理学家用这个词指高出周围的地形，把字面上的外凸保留到景观尺度。"},{"no":"07","title":"Drawing the eye to a feature","titleCN":"把视线引向某个显著特征","definition":"the degree to which a feature is emphasized or made to stand out visually","definitionCN":"某一特征被强调或在视觉上被突出的程度","example":"The designer increased the prominence of the search box on every page.","exampleCN":"设计师提高了搜索框在每个页面上的显著度。","why":"In design and typography, prominence measures how strongly an element pushes itself forward against its background.","whyCN":"在设计与排版中，prominence 衡量一个元素相对于背景把自己向前推的强度。"},{"no":"08","title":"A notable feature of a thing","titleCN":"事物中引人注目的特点","definition":"a salient or conspicuous feature that defines how something is noticed","definitionCN":"使某物被人注意的显著或突出特点","example":"The most striking prominence of the old hall is its carved stone doorway.","exampleCN":"这座旧厅最引人注目的特点，是它雕花的石门洞。","why":"The word can name the feature itself, not only the state: whatever makes an object noticeable is its prominence.","whyCN":"这个词也能指特征本身，而不只是状态：凡是使物体引人注意的东西，就是它的显著之处。"}],"etymology":{"intro":{"en":"Prominence comes from Latin prominentia, the noun of prominere, 'to stand out or jut forward'. Pro- supplied the forward direction and minere supplied the jutting. Everything the word names today - a bump, a hill, a solar flame, a famous name - is something that pushes out from its surroundings.","cn":"prominence 来自拉丁名词 prominentia，出自动词 prominere“突出、向前伸出”。pro- 提供向前方向，minere 提供“伸出”。今天这个词命名的一切——凸块、山丘、日珥、名人——都是从周围环境中顶出来的东西。"},"items":[{"era":"LATIN minere (uncertain)","en":"Minere meant 'to jut, to overhang'. Its deeper origin is uncertain; it is generally linked with eminere and imminere, and a connection with mons 'mountain' has been suggested but not proved.","cn":"minere 意为“伸出、悬突”，其更深来源不确定；一般认为它与 eminere、imminere 同族，也有人提出与 mons“山”相关，但未获证实。"},{"era":"LATIN prominere","en":"Pro- 'forward' plus minere 'jut' gave prominere, 'to stand out, to project'. The verb pictured anything pushing itself out from a surface.","cn":"pro-“向前”加 minere“伸出”构成 prominere“突出、外伸”。这个动词描画任何从表面向外顶出的东西。"},{"era":"LATIN prominentia","en":"The abstract noun named the state of jutting out. Late Latin used it for physical bulges before English borrowed it.","cn":"这个抽象名词表示“突出”的状态。在英语借入之前，晚期拉丁语已用它指身体上的隆起。"},{"era":"16C. BODY AND LANDSCAPE","en":"English first applied prominence to raised parts of the body and to hills, keeping the literal bulge.","cn":"英语最初把 prominence 用于身体的隆起部位与山丘，保留了字面上的“凸起”。"},{"era":"18C. REPUTATION","en":"The same outward-standing image moved from space to society: a person of prominence stands out from the crowd.","cn":"同一个“向外突出”的意象从空间移向社会：有 prominence 的人从人群中凸显。"},{"era":"19C–20C. ASTRONOMY AND ANATOMY","en":"Solar prominences were named during eclipse observations, and anatomists standardized the term for bony landmarks.","cn":"日珥在日食观测中得名，解剖学家则把这个词固定用于骨性标志。"}]},"similar":{"note":{"en":"The look-alike group separates the noun from its adjective and adverb and from the eminence family. The meaning group compares kinds of standing out, from fame to physical bumps.","cn":"形近组区分名词与它的形容词、副词形式，以及 eminence 词族；词义组比较不同类型的“突出”，从名声到物理凸起。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"prominent","ipa":"/ˈprɒmɪnənt/","tag":"adjective","definition":"standing out physically or socially. It describes the thing, while prominence names the quality or the bump.","definitionCN":"在物理上或社会上突出的。它描述事物，而 prominence 命名性质或凸起本身。"},{"word":"prominently","ipa":"/ˈprɒmɪnəntli/","tag":"adverb","definition":"in a noticeable position or manner. It modifies an action, as in 'prominently displayed'.","definitionCN":"以显眼的位置或方式。它修饰动作，如“显眼地展示”。"},{"word":"eminence","ipa":"/ˈemɪnəns/","tag":"noun","definition":"high rank, distinction, or literally a height. It comes from eminere 'stand out', a sibling of prominere with a different prefix.","definitionCN":"高位、卓越，或字面上的高地。它来自 eminere“突出”，是 prominere 的同胞词，只是前缀不同。"},{"word":"imminence","ipa":"/ɪˈmɪnəns/","tag":"noun","definition":"the state of being about to happen. It comes from imminere 'overhang', the same jutting verb with in- 'upon'.","definitionCN":"即将发生的状态。它来自 imminere“悬临”，是同一个“伸出”动词加上 in-“在上”。"}]},{"heading":"NEAR MEANING","entries":[{"word":"eminence","ipa":"/ˈemɪnəns/","tag":"noun","definition":"recognized superiority in a field. It is close to sense 01 but sounds more formal and more about rank.","definitionCN":"在某领域被公认的优越地位。它接近第 1 义项，但更正式、更强调等级。"},{"word":"distinction","ipa":"/dɪˈstɪŋkʃn/","tag":"noun","definition":"excellence or a quality that sets someone apart. It stresses difference in quality rather than visibility.","definitionCN":"卓越或使人出众的品质。它强调品质上的差异，而非可见度。"},{"word":"protrusion","ipa":"/prəˈtruːʒn/","tag":"noun","definition":"something that bulges out. It is the plain word for sense 02, without the reputation sense.","definitionCN":"凸出的东西。它是第 2 义项的平实说法，没有名声义。"},{"word":"salience","ipa":"/ˈsæliəns/","tag":"noun","definition":"the quality of standing out to attention. It is the technical term for senses 03 and 07.","definitionCN":"在注意中凸显的性质。它是第 3 与第 7 义项的技术说法。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks keep one picture: a bump that rises above a flat surface. Fame, hills, sun flames, bones and labels are all versions of that bump.","cn":"这些记忆钩只保留一个画面：从平面上升起的一块凸起。名声、山丘、日焰、骨头与标签都是这块凸起的变体。"},"normal":[{"en":"Split it as pro + min + ence: forward + jut + noun. A prominence is something that juts forward.","cn":"拆成 pro + min + ence：向前、伸出、名词。prominence 就是向前伸出的东西。"},{"en":"Picture a stone slab with one pebble glued on top: the pebble is a prominence.","cn":"想象一块石板上粘着一颗小石子：那颗石子就是 prominence。"},{"en":"Move the pebble to a village on a hill and you have the landscape sense.","cn":"把小石子换成一坐落在山丘上的村庄，就得到地貌义。"},{"en":"Move it to a crowd and the person whose head rises above the rest has prominence.","cn":"把它移到人群：高出众人一头的人就有了 prominence。"},{"en":"Move it to the sun's edge and the rising gas arch is a solar prominence.","cn":"把它移到太阳边缘，升起的气体拱就是日珥。"}],"abstract":[{"en":"The word always compares: without a surrounding level, nothing can be prominent.","cn":"这个词始终在比较：没有周围的水平面，就没有东西能算突出。"},{"en":"Keep the two halves apart: prominence is the bump or the fame, prominent is the adjective you use to describe it.","cn":"分清两半：prominence 是凸起或名声本身，prominent 是你用来描述它的形容词。"},{"en":"The solar sense shows how literal the word stays: astronomers still mean a part that projects beyond the disc.","cn":"日珥义说明这个词有多字面：天文学家指的仍是伸出圆盘之外的部分。"}]},"examples":[{"en":"Her early work on soil bacteria brought her sudden prominence in the field.","cn":"她早期关于土壤细菌的研究让她在该领域骤然成名。"},{"en":"A bony prominence behind the ear marks where the muscle attaches.","cn":"耳后的一处骨性隆凸标出了肌肉附着的位置。"},{"en":"The editor gave the climate report unusual prominence on page one.","cn":"编辑把气候报道放在了头版异常显眼的位置。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“扑罗米能斯”：一粒米能顶在平面上，就是一处凸起。","word":"prominence"},"root":"拉丁 prominere“突出、外伸”（pro- 向前 + minere 伸出），名词 prominentia；核心是“从周围平面顶出来的一块”。","sensesIntro":{"en":"Every sense describes something that rises above its surroundings: a reputation above the crowd, a bump above a surface, a label above other text, gas above the sun's disc, bone above the skin, a hill above the plain, an element above its background, a feature above the rest of an object.","cn":"每个义项都描述高出周围环境的东西：高于人群的名声、高出表面的凸起、压过其他文字的标签、伸出日面之外的气体、顶着皮肤的骨头、高出平原的山丘、压过背景的元素、盖过物件其余部分的特点。"},"semanticMap":{"core":{"en":"One surface, one part raised above it, and attention drawn to the raised part.","cn":"一个平面，一块高出它的部分，注意力被引向这块凸起。"},"chain":["SURFACE","RAISE","PROJECT","NOTICE","RANK","STAND OUT"],"branches":[{"senses":"02","en":"PHYSICAL: a part rises above the surface that carries it.","cn":"物理：一部分高出承载它的表面。"},{"senses":"03 · 07 · 08","en":"ATTENTION: the raised part is what the eye finds first.","cn":"注意：凸起部分是眼睛最先找到的东西。"},{"senses":"04","en":"SKY: gas rises above the sun's visible disc.","cn":"天空：气体高出于太阳可见的圆盘。"},{"senses":"05 · 06","en":"TERRAIN: bone and land repeat the same raised shape.","cn":"地形：骨头与土地重复同一种隆起形状。"},{"senses":"01","en":"REPUTATION: a person rises above the crowd and is widely known.","cn":"名声：一个人高出人群之上，被广泛知晓。"}]},"affixes":{"intro":{"en":"Prominence is pro- plus minere plus the noun suffix -entia. The items below follow the same jutting verb through its adjective, adverb and the sibling prefixes e- and in-.","cn":"prominence 由 pro-、minere 与名词后缀 -entia 构成。下列条目沿着同一个“伸出”动词，走过形容词、副词以及同胞前缀 e- 与 in-。"},"latinIntro":{"en":"The Latin entries give the jutting verb, its abstract noun and the bare root. They show why eminence, imminent and prominence look like cousins.","cn":"拉丁语条目给出“伸出”动词、抽象名词与裸露词根，说明为什么 eminence、imminent 与 prominence 看起来像表亲。"},"items":[{"word":"prominence","structure":"prominere + -entia (abstract noun)","meaning":"the state of standing out","meaningCN":"突出的状态；显要","example":"The bridge gained prominence after the flood.","exampleCN":"洪水过后这座桥变得重要起来。"},{"word":"prominent","structure":"prominens, present participle of prominere","meaning":"standing out; well known","meaningCN":"突出的；著名的","example":"A prominent oak stood at the gate.","exampleCN":"门口立着一棵显眼的橡树。"},{"word":"prominently","structure":"prominent + -ly (adverb)","meaning":"in a noticeable way","meaningCN":"显眼地；显著地","example":"Her name appeared prominently on the cover.","exampleCN":"她的名字显眼地出现在封面上。"},{"word":"eminence","structure":"e- (out) + minere + -entia","meaning":"high rank; a height","meaningCN":"卓越；高地","example":"The surgeon reached eminence in her thirties.","exampleCN":"这位外科医生三十多岁时便已卓越成名。"},{"word":"eminent","structure":"eminens, present participle of eminere","meaning":"distinguished; towering","meaningCN":"杰出的；高耸的","example":"An eminent historian opened the session.","exampleCN":"一位著名历史学家主持了会议。"},{"word":"imminent","structure":"in- (upon) + minere + -ent","meaning":"about to happen, as if hanging over","meaningCN":"迫在眉睫的","example":"Storm clouds warned of imminent rain.","exampleCN":"乌云预示着雨即将到来。"},{"word":"imminence","structure":"imminent + -ence (abstract noun)","meaning":"the state of being about to happen","meaningCN":"即将来临的状态","example":"The imminence of the deadline forced a decision.","exampleCN":"截止期限迫近，迫使人们作出决定。"},{"word":"preeminent","structure":"pre- (before) + eminere + -ent","meaning":"standing above all others","meaningCN":"出类拔萃的；首屈一指的","example":"She is the preeminent scholar of the period.","exampleCN":"她是该时期首屈一指的学者。"}],"latinEntries":[{"word":"minere","structure":"verb, 'to jut, overhang'","meaning":"to project, to hang forward","meaningCN":"伸出；悬突"},{"word":"prominere","structure":"pro- + minere","meaning":"to stand out, to project","meaningCN":"突出；外伸"},{"word":"prominentia","structure":"prominere + -entia","meaning":"a projecting; prominence","meaningCN":"突出；凸起"}]}},{"word":"prominent","ipa_uk":"/ˈprɒmɪnənt/","ipa_us":"/ˈprɑːmɪnənt/","definition_zh":"突出的；显眼的；著名的；显要的；重要的；（特征）显著的；（结构）外凸的","definition_en":"standing out from a surface or from other people, and therefore easy to notice or important","core_image":"一块石头从墙面上凸出来，走过的人都先看见它","scene":"A prominent sandstone arch frames the entrance to the old library.","sceneCN":"这里 prominent 是「向外突出的」（第 3 个义项：结构从墙面伸出、形成门框）；句意：一道突出的砂岩拱券框住了老图书馆的入口。图中可辨识物件：从墙面伸出的拱券、被框住的入口。","pos":[{"tag":"adj.","zh":"突出的；显眼的；著名的；显要的；显著的"}],"collocations":[{"phrase":"prominent role","zh":"重要角色"},{"phrase":"prominent figure","zh":"知名人物"},{"phrase":"prominent position","zh":"显眼的位置"},{"phrase":"prominent feature","zh":"显著特征"},{"phrase":"prominent teeth","zh":"突出的牙齿"},{"phrase":"socially prominent","zh":"社会地位显赫的"}],"forms":[{"label":"原级","form":"prominent"},{"label":"比较级","form":"more prominent"},{"label":"最高级","form":"most prominent"},{"label":"副词","form":"prominently"},{"label":"名词","form":"prominence"}],"derivatives":[{"word":"prominence","pos":"n.","zh":"显要；凸起；日珥"},{"word":"prominently","pos":"adv.","zh":"显眼地；显著地"},{"word":"eminence","pos":"n.","zh":"卓越；高地"},{"word":"imminent","pos":"adj.","zh":"迫近的"}],"senses":[{"no":"01","title":"Well known and respected","titleCN":"著名且受敬重的","definition":"widely known and respected in a particular field","definitionCN":"在某一领域广为人知并受敬重","example":"A prominent economist warned that the housing boom would end.","exampleCN":"一位著名经济学家警告说房地产繁荣将会结束。","why":"Prominens meant 'standing out'. Fame is social standing out: the person rises visibly above the ordinary level of the profession.","whyCN":"prominens 意为“突出的”。名声就是社会意义上的突出：这个人明显高出于行业的一般水平。"},{"no":"02","title":"Holding an important position","titleCN":"身居要职、有影响力","definition":"having an important or influential position in an organization or society","definitionCN":"在组织或社会中居于重要或有影响力的位置","example":"Several prominent families opposed the new tax.","exampleCN":"几个显赫家族反对这项新税。","why":"The word moves from visibility to power: a prominent family is one whose name stands out in public affairs and can therefore sway them.","whyCN":"这个词从可见度转到权力：显赫家族的名字在公共事务中突出，因此能左右事务。"},{"no":"03","title":"Sticking out from a surface","titleCN":"从表面向外突出","definition":"rising or projecting above the surrounding surface","definitionCN":"高出或伸出周围表面的","example":"The old house had prominent stone arches over every window.","exampleCN":"这座老房子每扇窗上都有突出的石拱。","why":"This is the literal core: the thing itself pushes forward beyond the plane it belongs to, so it catches the eye before anything else.","whyCN":"这是字面核心：事物本身顶出所属平面之外，所以比其他东西更早抓住视线。"},{"no":"04","title":"Impossible to overlook","titleCN":"一眼就能看到、难以忽略","definition":"placed or shaped so that it is noticed immediately","definitionCN":"放置或造型使其立刻被注意到","example":"The safety instructions were printed in a prominent band of red.","exampleCN":"安全说明被印在一条醒目的红色带子上。","why":"When designers call a label prominent, they mean it wins the competition for attention against everything around it.","whyCN":"当设计师说某个标签 prominent，意思是它在与周围一切争夺注意力时胜出。"},{"no":"05","title":"Clearly visible in a feature","titleCN":"特征明显、容易辨认","definition":"clearly marked or easily observed, as of a sign or symptom","definitionCN":"指迹象或症状明显、易于观察","example":"The first prominent symptom was a persistent dry cough.","exampleCN":"最先出现的明显症状是持续干咳。","why":"In medicine the word marks what a clinician cannot miss: a sign that presents itself plainly rather than hiding in the background.","whyCN":"在医学中，这个词标记临床医生不会漏掉的东西：一个直接呈现、不藏在背景里的征象。"},{"no":"06","title":"The leading element","titleCN":"居于主导地位的要素","definition":"the most important or noticeable element among several","definitionCN":"若干要素中最重要或最引人注意的一个","example":"Loss of trust is the most prominent theme in the interviews.","exampleCN":"失去信任是这些访谈中最突出的主题。","why":"Among competing elements, the prominent one is the one that stands above the rest of the set, much as a bump stands above a surface.","whyCN":"在相互竞争的要素中，突出的那一个是高出其余部分的，就像凸起高出表面。"},{"no":"07","title":"Socially conspicuous","titleCN":"社会地位显眼","definition":"attracting public notice because of wealth, rank or family name","definitionCN":"因财富、地位或家族名望而引人注目","example":"The wedding was attended by the town's most prominent citizens.","exampleCN":"镇上最显要的市民都出席了这场婚礼。","why":"The social sense specializes in public notice: not merely famous for work, but visible because of rank or wealth.","whyCN":"社会义专门指向公众注意：不仅因工作而出名，更因地位或财富而显眼。"},{"no":"08","title":"Standing out to the eye or ear","titleCN":"在视觉或听觉上突出","definition":"visually or acoustically strong enough to dominate the surrounding pattern","definitionCN":"在视觉或听觉上足够强，压过周围的图案或声音","example":"A prominent blue stripe runs through the whole fabric.","exampleCN":"一道醒目的蓝色条纹贯穿整块布料。","why":"Design and music use the word for the element that dominates the pattern, whether a colour or a beat.","whyCN":"设计与音乐用这个词指压过整体图案的元素，无论是一种颜色还是一个节拍。"}],"etymology":{"intro":{"en":"Prominent is the present participle of Latin prominere, 'to stand out, to project'. Pro- gives the forward push and minere gives the jutting. English borrowed it in the 17th century and let it spread from rocks and bones to reputations, symptoms and design.","cn":"prominent 是拉丁 prominere“突出、外伸”的现在分词。pro- 提供向前的推力，minere 提供“伸出”。英语在 17 世纪借入，并让它从岩石与骨骼扩展到名声、症状与设计。"},"items":[{"era":"LATIN minere (uncertain)","en":"Minere meant 'to jut or overhang'. Its deeper origin is uncertain; connections with eminere and imminere are generally accepted, while a link to mons 'mountain' remains unproved.","cn":"minere 意为“伸出、悬突”，更深来源不确定；与 eminere、imminere 的关联一般被接受，而与 mons“山”的联系尚未证实。"},{"era":"LATIN prominere","en":"Prominere combined pro- 'forward' with minere 'jut' and meant 'to stand out, to project'. Its participle prominens described whatever was doing the standing out.","cn":"prominere 由 pro-“向前”与 minere“伸出”组成，意为“突出、外伸”。其分词 prominens 描述正在突出的东西。"},{"era":"LATIN prominens","en":"The participle was already used for projecting parts of buildings and bodies, so the adjective carried a physical meaning from the start.","cn":"这个分词已用于建筑与身体的外凸部位，因此形容词从一开始就带有物理含义。"},{"era":"17C. ENGLISH BORROWING","en":"English adopted prominent for physical projections first, then extended it to anything that stood above its surroundings in importance.","cn":"英语先借 prominent 指物理凸起，再扩展到任何在重要性上高出周围环境的事物。"},{"era":"18C–19C. PUBLIC LIFE","en":"Newspapers made 'prominent citizens' a familiar phrase, and the adjective became the standard word for public standing.","cn":"报纸使“显要市民”成为常见说法，这个形容词也成为表示公共地位的标准词。"},{"era":"20C. MEDICINE AND DESIGN","en":"Clinical writing adopted prominent for signs that stand out, while design and music used it for elements that dominate a pattern.","cn":"临床写作采用 prominent 指明显的征象，设计与音乐则用它指压过整体图案的元素。"}]},"similar":{"note":{"en":"The look-alike group separates the adjective from its noun, adverb and the eminence family. The meaning group contrasts being famous, being obvious and being physically raised.","cn":"形近组区分形容词与它的名词、副词形式及 eminence 词族；词义组比较“有名”“明显”与“物理凸起”。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"prominence","ipa":"/ˈprɒmɪnəns/","tag":"noun","definition":"the quality of standing out, or the raised part itself. It names what prominent describes.","definitionCN":"突出的性质，或凸起本身。它命名 prominent 所描述的东西。"},{"word":"prominently","ipa":"/ˈprɒmɪnəntli/","tag":"adverb","definition":"in a way that is easy to notice. It tells how something is placed or shown.","definitionCN":"以容易注意的方式。它说明某物如何被放置或展示。"},{"word":"eminence","ipa":"/ˈemɪnəns/","tag":"noun","definition":"high rank or a height. It comes from eminere, the same jutting verb with e- 'out' instead of pro- 'forward'.","definitionCN":"高位或高地。它来自 eminere，同一个“伸出”动词，只是用 e-“向外”取代 pro-“向前”。"},{"word":"permanent","ipa":"/ˈpɜːmənənt/","tag":"adjective","definition":"lasting forever. It looks similar but comes from per- 'through' plus manere 'to remain', a completely different root.","definitionCN":"永久的。它看起来相似，却来自 per-“贯穿”加 manere“停留”，词根完全不同。"}]},{"heading":"NEAR MEANING","entries":[{"word":"eminent","ipa":"/ˈemɪnənt/","tag":"adjective","definition":"distinguished and highly respected. It is close to sense 01 but sounds more formal and more about rank.","definitionCN":"卓越且深受敬重的。它接近第 1 义项，但更正式、更强调等级。"},{"word":"conspicuous","ipa":"/kənˈspɪkjuəs/","tag":"adjective","definition":"clearly visible, often because of unusual appearance. It stresses being seen, while prominent stresses standing above a level.","definitionCN":"明显可见的，常因外形不寻常。它强调被看见，而 prominent 强调高出某一水平。"},{"word":"noticeable","ipa":"/ˈnəʊtɪsəbl/","tag":"adjective","definition":"easy to see or feel. It is the plain everyday word for sense 04.","definitionCN":"容易看到或感觉到的。它是第 4 义项的日常说法。"},{"word":"protruding","ipa":"/prəˈtruːdɪŋ/","tag":"adjective","definition":"sticking out physically. It is the narrow word for sense 03, with no fame or importance attached.","definitionCN":"物理上伸出的。它是第 3 义项的窄义说法，不附带名声或重要性。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks pin the word to one raised shape, then let it travel from walls to faces, from symptoms to fame.","cn":"这些记忆钩把词钉在一个隆起的形状上，再让它从墙面走到面孔、从症状走到名声。"},"normal":[{"en":"Split it as pro + min + ent: forward + jut + adjective. Anything that juts forward is prominent.","cn":"拆成 pro + min + ent：向前、伸出、形容词。凡是向前伸出的就是 prominent。"},{"en":"Picture a wall with one brick pushed out: your hand finds that brick first.","cn":"想象一面墙里有一块砖被顶了出来：你的手最先摸到那块砖。"},{"en":"Prominent teeth and a prominent nose are the same brick, moved to a face.","cn":"突出的牙齿与高鼻梁就是同一块砖，被移到了脸上。"},{"en":"A prominent symptom is the brick in a medical chart: the one the doctor circles.","cn":"明显症状就是病历里的那块砖：医生会把它圈出来。"},{"en":"A prominent scientist is the same brick in a crowd: the one the reporters call first.","cn":"著名科学家就是人群里的那块砖：记者最先打电话给他。"}],"abstract":[{"en":"The word always needs a background: a bump on a bump is not prominent, only a bump on a flat surface is.","cn":"这个词始终需要背景：凸起上的凸起并不突出，只有平面上的凸起才突出。"},{"en":"Keep fame and shape in one frame: the person stands out socially exactly as the brick stands out physically.","cn":"把名声与形状放在同一个框架里：人在社会上突出，正如砖头在物理上突出。"},{"en":"Watch the suffix: prominent describes, prominence names, prominently tells how.","cn":"留意后缀：prominent 描述，prominence 命名，prominently 说明方式。"}]},"examples":[{"en":"A prominent legal scholar argued that the ruling was too broad.","cn":"一位著名法学学者主张该判决范围过宽。"},{"en":"The bird's most prominent feature is the bright red crest on its head.","cn":"这种鸟最显著的特征是头顶鲜红的冠羽。"},{"en":"Warning signs were mounted in prominent positions along the cliff path.","cn":"警示牌被安装在悬崖步道的显眼位置。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“扑罗米能特”：一块米能特别突出，从平面上顶出来。","word":"prominent"},"root":"拉丁 prominere 的现在分词 prominens“突出的”（pro- 向前 + minere 伸出）；核心是“从平面顶出来、一眼看见”。","sensesIntro":{"en":"The eight senses all describe one thing standing above another: a scholar above peers, a family above society, a stone above a wall, a label above text, a symptom above silence, a theme above its rivals, a citizen above the town, a stripe above the fabric.","cn":"八个义项都在描述一物高出另一物：学者高出同行，家族高出社会，石头高出墙面，标签压过文字，症状压过沉默，主题压过其他主题，市民高出小镇，条纹压过布料。"},"semanticMap":{"core":{"en":"A part that rises above its background, so that attention lands on it before anything else.","cn":"一部分高出背景，因此注意力先落在它上面。"},"chain":["BACKGROUND","RISE","PROJECT","ATTENTION","STANDING","IMPORTANCE"],"branches":[{"senses":"01 · 02","en":"PEOPLE: a person rises above peers by reputation or position.","cn":"人：一个人凭名声或地位高出同侪。"},{"senses":"03 · 08","en":"SHAPE: a part pushes out of its surface and dominates the pattern.","cn":"形状：一部分顶出表面，压过整体图案。"},{"senses":"04 · 05","en":"VISIBILITY: what stands out is noticed at once, in a room or on a chart.","cn":"可见度：突出的东西立刻被注意到，无论在房间里还是在图表上。"},{"senses":"06","en":"COMPETITION: among rival elements, one stands above the rest of the set.","cn":"竞争：在相互竞争的要素中，有一个高出其余。"},{"senses":"07","en":"SOCIETY: rank and wealth make a family visible in public life.","cn":"社会：地位与财富让一个家族在公共生活中显眼。"}]},"affixes":{"intro":{"en":"Prominent is a Latin participle used as an adjective. The items below show the same jutting verb through noun, adverb and the sibling prefixes e- and in-.","cn":"prominent 是拉丁分词用作形容词。下列条目沿着同一个“伸出”动词，走过名词、副词与同胞前缀 e-、in-。"},"latinIntro":{"en":"The Latin entries give the verb and its participle. They explain why prominent, prominence and eminence keep the same core image.","cn":"拉丁语条目给出动词与分词，解释为什么 prominent、prominence 与 eminence 保持同一个核心意象。"},"items":[{"word":"prominent","structure":"prominens, participle of prominere","meaning":"standing out; well known","meaningCN":"突出的；著名的","example":"A prominent ridge hides the valley from view.","exampleCN":"一道突出的山脊挡住了山谷的视线。"},{"word":"prominence","structure":"prominere + -entia","meaning":"the state of standing out; a bump","meaningCN":"突出；显要；凸起","example":"The tower's prominence makes it a landmark.","exampleCN":"这座塔的突出使它成为地标。"},{"word":"prominently","structure":"prominent + -ly","meaning":"in a noticeable way","meaningCN":"显眼地；显著地","example":"The flag was prominently hung above the door.","exampleCN":"旗帜显眼地挂在门上方。"},{"word":"eminence","structure":"e- (out) + minere + -entia","meaning":"distinction; high ground","meaningCN":"卓越；高地","example":"The hill's eminence gives a view of the bay.","exampleCN":"这座山丘的高起让人能看到海湾。"},{"word":"eminent","structure":"eminens, participle of eminere","meaning":"distinguished; rising high","meaningCN":"杰出的；高耸的","example":"An eminent critic praised the first novel.","exampleCN":"一位著名评论家称赞了这部处女作。"},{"word":"imminent","structure":"in- (upon) + minere + -ent","meaning":"hanging over, about to happen","meaningCN":"迫在眉睫的","example":"The rust suggested imminent collapse.","exampleCN":"锈蚀表明随时可能坍塌。"},{"word":"supereminent","structure":"super- (above) + eminent","meaning":"standing above even the eminent","meaningCN":"超群出众的","example":"His reputation was supereminent in his lifetime.","exampleCN":"他在世时声誉超群。"},{"word":"eminently","structure":"eminere + -ent + -ly","meaning":"to a distinguished degree","meaningCN":"卓越地；非常","example":"The plan was eminently practical.","exampleCN":"这个计划非常切实可行。"}],"latinEntries":[{"word":"minere","structure":"verb, 'to jut'","meaning":"to project outward","meaningCN":"向外伸出"},{"word":"prominere","structure":"pro- + minere","meaning":"to stand out forward","meaningCN":"向前突出"},{"word":"prominens","structure":"present participle of prominere","meaning":"standing out","meaningCN":"突出的"}]}},{"word":"proportional","ipa_uk":"/prəˈpɔːʃənl/","ipa_us":"/prəˈpɔːrʃənl/","definition_zh":"成比例的；相称的；按比例分配的；（数学）比例的；（选举）比例代表制的；适度的","definition_en":"changing in step with something else, so that the relation between the two amounts stays the same","core_image":"两个水柱一起升降，刻度始终停在同一条斜线上","scene":"The fine was proportional to the damage the company had caused to the river.","sceneCN":"这里 proportional 是「与……相称的」（第 6 个义项：处罚与造成的损害成比例）；句意：罚款与该公司对河流造成的损害相称。图中可辨识物件：天平两端、按同一斜率升降的两根柱子。","pos":[{"tag":"adj.","zh":"成比例的；相称的；按比例分配的；比例代表制的"}],"collocations":[{"phrase":"proportional to","zh":"与……成比例"},{"phrase":"directly proportional","zh":"成正比的"},{"phrase":"proportional representation","zh":"比例代表制"},{"phrase":"proportional increase","zh":"按比例增长"},{"phrase":"proportional system","zh":"比例制"},{"phrase":"proportional share","zh":"按比例的份额"}],"forms":[{"label":"原级","form":"proportional"},{"label":"比较级","form":"more proportional"},{"label":"最高级","form":"most proportional"},{"label":"副词","form":"proportionally"},{"label":"近义形容词","form":"proportionate"}],"derivatives":[{"word":"proportion","pos":"n./v.","zh":"比例；部分；使成比例"},{"word":"proportionally","pos":"adv.","zh":"按比例地"},{"word":"proportionate","pos":"adj.","zh":"相称的；成比例的"},{"word":"disproportionate","pos":"adj.","zh":"不成比例的；过大或过小的"}],"senses":[{"no":"01","title":"Changing together at a fixed rate","titleCN":"按固定比率同步变化","definition":"increasing or decreasing at a rate that keeps a constant relation with another quantity","definitionCN":"以与另一数量保持恒定关系的速率增减","example":"Pressure is proportional to depth, so it doubles when the depth doubles.","exampleCN":"压力与深度成正比，因此深度加倍时压力也加倍。","why":"Pro portione meant 'according to the share'. When two quantities keep their shares aligned, each change in one is matched by a fixed change in the other.","whyCN":"pro portione 意为“按份额”。当两个数量保持份额对齐时，一个量的每次变化都由另一个量的固定变化来配平。"},{"no":"02","title":"In due balance","titleCN":"比例恰当的、均衡的","definition":"having parts of a size that suits one another and the whole","definitionCN":"各部分大小彼此相称、也与整体相称","example":"The architect chose a proportional height for the columns to keep the hall calm.","exampleCN":"建筑师为柱子选了相称的高度，让大厅显得沉稳。","why":"The same shares idea applies to parts of a design: a proportional building has no part that looks too big or too small for the rest.","whyCN":"同一个“份额”观念适用于设计的各部分：比例恰当的建筑，没有哪一部分相对其余显得过大或过小。"},{"no":"03","title":"Mathematical proportion","titleCN":"数学意义上的比例关系","definition":"describing quantities whose ratio is constant, or a term in that relation","definitionCN":"指比值恒定的量，或处于该关系中的项","example":"In the table, the two columns are proportional, with each entry twice the one beside it.","exampleCN":"表中两列成比例，每一条目都是旁边那一条的两倍。","why":"Mathematics fixed the word to the constant ratio. A proportional relation is one where doubling one side always doubles the other.","whyCN":"数学把词固定到恒定比值上：成比例的关系，就是一边加倍时另一边必然加倍。"},{"no":"04","title":"Seats shared by vote share","titleCN":"按得票份额分配席位","definition":"of an electoral system: allocating seats in rough proportion to the votes each party wins","definitionCN":"指按各党所得选票的比例分配议席的选举制度","example":"Under proportional representation, a party with a fifth of the vote gains about a fifth of the seats.","exampleCN":"在比例代表制下，得票五分之一的政党约获得五分之一的席位。","why":"Electoral reformers borrowed the arithmetic of shares: seats should follow votes as closely as the two columns in a proportional table.","whyCN":"选举改革者借用了份额的算术：席位应尽可能贴着选票走，就像比例表里的两列。"},{"no":"05","title":"Punishment that matches the harm","titleCN":"与损害相称的惩罚","definition":"of a penalty or response: of a size that fits the wrong done or the risk created","definitionCN":"指处罚或回应的大小与过错或造成的风险相称","example":"Judges aim for a sanction proportional to the seriousness of the offence.","exampleCN":"法官力求制裁与罪行的严重程度相称。","why":"Here proportion is moral rather than numerical: the response should weigh the same as the harm on some shared scale.","whyCN":"这里的比例是道德性的而非数字性的：回应应在某种共同标尺上与损害等重。"},{"no":"06","title":"Scaled to fit","titleCN":"按比例缩放以适配","definition":"enlarged or reduced so that every part keeps its original relation to the others","definitionCN":"放大或缩小后各部分仍保持原有相互关系","example":"The model is proportional to the bridge but only one fiftieth of its length.","exampleCN":"这个模型与那座桥成比例，但长度只有其五十分之一。","why":"Anything scaled proportionally keeps every ratio intact. Only one measurement changes; all the others follow it exactly.","whyCN":"任何等比缩放都保留全部比值，只改变一个尺寸，其余尺寸精确跟随。"},{"no":"07","title":"Shared out by shares","titleCN":"按份额分配","definition":"divided among people or groups according to an agreed share rather than equally","definitionCN":"按约定份额而非平均地分给人或群体","example":"The profits were proportional to each partner's investment.","exampleCN":"利润按每位合伙人的出资比例分配。","why":"Distribution is the oldest share sense: each claimant receives the fraction that belongs to them, no more and no less.","whyCN":"分配是最古老的份额义：每个索取者得到属于自己的那一份，不多也不少。"},{"no":"08","title":"Sampled at the same rate","titleCN":"按相同比率抽样","definition":"of a sample or statistics: drawn or weighted so that each subgroup appears in its true share","definitionCN":"指抽样或加权使各子群按其真实份额出现","example":"The survey used a proportional sample so that rural districts were not undercounted.","exampleCN":"这项调查采用按比例抽样，以免农村地区被少算。","why":"Statistics repeats the share logic: if a group is a third of the population, a proportional sample makes it a third of the respondents.","whyCN":"统计学重复份额逻辑：如果某群体占人口三分之一，按比例抽样就让它占受访者的三分之一。"}],"etymology":{"intro":{"en":"Proportional goes back to the Latin phrase pro portione, 'according to the share'. Portio meant a portion or allotted part, and the derived noun proportio named the relation between shares. Late Latin added the adjective proportionalis, which passed through French into English.","cn":"proportional 可回溯到拉丁短语 pro portione“按份额”。portio 意为一份或分得的部分，派生名词 proportio 命名各份之间的关系。晚期拉丁语再加形容词 proportionalis，经法语进入英语。"},"items":[{"era":"LATIN portio","en":"Portio meant 'a share, a part assigned'. It is the noun that carries the whole idea of dividing something into due parts.","cn":"portio 意为“份额、分得的部分”。正是这个名词承载了把某物分成应得各份的整个观念。"},{"era":"LATIN pro portione","en":"The phrase meant 'according to the share'. Cicero and later writers used it for relations in which each part receives its due amount.","cn":"这个短语意为“按份额”。西塞罗及后来的作者用它指每一部分各得其应有数量的关系。"},{"era":"LATIN proportio","en":"The phrase hardened into the noun proportio, 'comparative relation, analogy'. It covered both arithmetic ratios and fitting arrangement.","cn":"这个短语凝固成名词 proportio“比较关系、类比”，既涵盖算术比值，也涵盖恰当的排列。"},{"era":"LATE LATIN proportionalis","en":"Late Latin built the adjective proportionalis from proportio. French proportionnel then supplied the English form in the 16th century.","cn":"晚期拉丁语由 proportio 造出形容词 proportionalis，法语 proportionnel 随后在 16 世纪提供了英语形式。"},{"era":"17C–18C. MATHEMATICS","en":"The growth of algebra and geometry fixed proportional to the constant-ratio sense, giving the precise phrase directly proportional.","cn":"代数与几何的发展把 proportional 固定到恒定比值义，产生了精确说法“成正比的”。"},{"era":"19C–20C. POLITICS AND STATISTICS","en":"Proportional representation was debated from the mid-19th century, and sampling theory made proportional allocation a standard statistical tool.","cn":"比例代表制自 19 世纪中叶起被讨论，抽样理论则使按比例分配成为标准统计工具。"}]},"similar":{"note":{"en":"The look-alike group separates proportional from proportion, the adverb and the near-twin proportionate. The meaning group contrasts matching rates, matching sizes and matching shares.","cn":"形近组区分 proportional 与名词 proportion、副词及近似的 proportionate；词义组比较“比率相配”“大小相配”与“份额相配”。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"proportion","ipa":"/prəˈpɔːʃn/","tag":"noun / verb","definition":"a share or a relation between parts. It is the base noun, while proportional is the adjective built on it.","definitionCN":"份额或各部分之间的关系。它是基础名词，proportional 是由它构成的形容词。"},{"word":"proportionally","ipa":"/prəˈpɔːʃənəli/","tag":"adverb","definition":"in a way that follows a proportion. It tells how something changes or is divided.","definitionCN":"按比例地。它说明某物如何变化或如何分配。"},{"word":"proportionate","ipa":"/prəˈpɔːʃənət/","tag":"adjective","definition":"of a size that fits or is fair. It often shades toward suitability, while proportional leans toward arithmetic.","definitionCN":"大小合适或公平的。它常偏向“适宜”，而 proportional 偏向算术。"},{"word":"proposition","ipa":"/ˌprɒpəˈzɪʃn/","tag":"noun","definition":"a statement or an offer. It looks close but comes from pro- plus ponere 'to put', not from portio 'share'.","definitionCN":"陈述或提议。它看起来相近，却来自 pro- 加 ponere“放置”，而非 portio“份额”。"}]},{"heading":"NEAR MEANING","entries":[{"word":"proportionate","ipa":"/prəˈpɔːʃənət/","tag":"adjective","definition":"corresponding in size or degree, often with a note of fairness. It is the usual word for a fitting response.","definitionCN":"在大小或程度上相对应的，常含公平意味。它是“恰当回应”的常用词。"},{"word":"commensurate","ipa":"/kəˈmenʃərət/","tag":"adjective","definition":"equal in measure to something, as of pay and responsibility. It stresses matching a standard.","definitionCN":"在尺度上与某物相当，如薪酬与责任。它强调与某一标准相配。"},{"word":"relative","ipa":"/rəˈleɪtɪv/","tag":"adjective","definition":"considered in relation to something else. It says a comparison exists, not that the ratio is fixed.","definitionCN":"相对于某物来考虑的。它只说明存在比较，不说明比值固定。"},{"word":"corresponding","ipa":"/kəˈrɒspɒndɪŋ/","tag":"adjective","definition":"matching or analogous in position or function. It pairs items without implying a fixed ratio.","definitionCN":"在位置或功能上对应或类似的。它配对项目，但不暗示固定比值。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks tie the word to the Latin share, then let the same idea run through ratios, design, elections, penalties, models, profits and samples.","cn":"这些记忆钩把词系在拉丁“份额”上，再让同一观念贯穿比值、设计、选举、处罚、模型、利润与抽样。"},"normal":[{"en":"Split it as pro + portion + al: according to the share. Proportional means the shares stay aligned.","cn":"拆成 pro + portion + al：按份额。proportional 意为份额保持对齐。"},{"en":"Picture two water columns rising together: the line between their tops always has the same slope.","cn":"想象两根水柱一起上升：柱顶连线始终是同一条斜线。"},{"en":"A proportional model bridge fits in your hand because every length was cut by the same fraction.","cn":"比例模型桥能放进手心，因为每条长度都被同一个分数缩小了。"},{"en":"Proportional representation hands out seats in the same fractions as votes.","cn":"比例代表制按与选票相同的分数发放席位。"},{"en":"A proportional fine weighs the harm on one pan and the penalty on the other until they balance.","cn":"相称的罚款把损害放在天平一端、处罚放在另一端，直到平衡。"}],"abstract":[{"en":"Keep 'proportion' as the noun in mind: proportional is simply the adjective that says the shares agree.","cn":"心里记住 proportion 是名词：proportional 只是说各份额一致的那个形容词。"},{"en":"Notice the double life: in maths the ratio is exact, in law and design it is judged rather than measured.","cn":"注意它的双重生活：数学里比值是精确的，法律与设计里则是靠判断而非测量。"},{"en":"Ask 'proportional to what?' Every sense needs a second term: another quantity, a harm, a whole, a population.","cn":"随时问“与什么成比例？”每个义项都需要第二项：另一个数量、一项损害、一个整体、一个人口。"}]},"examples":[{"en":"The brightness of a lamp is inversely proportional to the square of the distance.","cn":"灯的亮度与距离的平方成反比。"},{"en":"The council adopted a proportional system for allocating seats on the new board.","cn":"议会通过了新理事会席位的比例分配制。"},{"en":"Analysts expect a proportional rise in shipping costs as fuel prices climb.","cn":"分析师预计运费将随燃料价格上升而成比例上涨。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“扑罗破身呢”：两样东西一起破、一起补，破口大小始终成比例。","word":"proportional"},"root":"拉丁 pro portione“按份额”，portio 意为“份额、分得的部分”，派生 proportio 与 proportionalis；核心是“两份按同一比率增减”。","sensesIntro":{"en":"All eight senses ask the same question: do the shares still line up? Quantities, columns, seats, penalties, models, profits and samples are proportional when each part keeps the fraction it is supposed to have.","cn":"八个义项问的都是同一个问题：各份还对得齐吗？数量、表格列、席位、处罚、模型、利润与样本之所以成比例，是因为每一份都保住了它应有的分数。"},"semanticMap":{"core":{"en":"Two or more parts keep a constant relation, so when one changes the others change by the same fraction.","cn":"两个或更多部分保持恒定关系，于是一个变化时其余按同一分数变化。"},"chain":["SHARE","RATIO","CHANGE","BALANCE","ALLOCATE","SCALE"],"branches":[{"senses":"01 · 03","en":"QUANTITIES: the ratio between two amounts never shifts.","cn":"数量：两个量之间的比值从不移动。"},{"senses":"02 · 06","en":"SHAPE: design and models keep every part in its original relation.","cn":"形状：设计与模型让每一部分保持原有关系。"},{"senses":"04 · 07","en":"ALLOCATION: votes, seats and profits follow the agreed fractions.","cn":"分配：选票、席位与利润遵循约定分数。"},{"senses":"05","en":"JUSTICE: the response is weighed against the harm.","cn":"公正：回应与损害放在同一杆秤上衡量。"},{"senses":"08","en":"SAMPLING: each subgroup appears in its true share.","cn":"抽样：每个子群按真实份额出现。"}]},"affixes":{"intro":{"en":"Proportional is pro + portio + -al. The items below follow the same share noun into adverb, verb, near-synonym and negation.","cn":"proportional 由 pro、portio 与 -al 构成。下列条目沿着同一个“份额”名词，走到副词、动词、近义词与否定形式。"},"latinIntro":{"en":"The Latin entries give the share noun and the phrase that became a noun. They explain why proportion, proportional and proportionate all point back to one allotment.","cn":"拉丁语条目给出“份额”名词与凝固成名词的短语，解释为什么 proportion、proportional 与 proportionate 都指向同一次分配。"},"items":[{"word":"proportional","structure":"pro portione + -al","meaning":"changing in a fixed relation to something else","meaningCN":"按固定关系变化的","example":"The tax is proportional to the value of the land.","exampleCN":"税额与土地价值成比例。"},{"word":"proportion","structure":"pro portione (phrase)","meaning":"a share; the relation between parts","meaningCN":"份额；各部分之间的关系","example":"The proportion of women in the field is rising.","exampleCN":"该领域中女性的比例正在上升。"},{"word":"proportionally","structure":"proportional + -ly","meaning":"according to a proportion","meaningCN":"按比例地","example":"Costs were shared proportionally among the members.","exampleCN":"费用由成员按比例分摊。"},{"word":"proportionate","structure":"pro + portio + -ate","meaning":"fitting in size or degree","meaningCN":"大小或程度相称的","example":"The reply was proportionate to the threat.","exampleCN":"这一回应与威胁程度相称。"},{"word":"proportionality","structure":"proportional + -ity","meaning":"the quality of being in due proportion","meaningCN":"比例性；相称性","example":"Lawyers debated the proportionality of the sentence.","exampleCN":"律师争论该判决是否相称。"},{"word":"disproportionate","structure":"dis- (not) + proportionate","meaning":"out of proportion; too large or too small","meaningCN":"不成比例的；过大或过小的","example":"The punishment was disproportionate to the error.","exampleCN":"这项处罚与过失不相称。"},{"word":"proportionated","structure":"proportionate used as a verb form","meaning":"adjusted to fit a proportion","meaningCN":"按比例调整过的","example":"Benefits were proportionated to working hours.","exampleCN":"福利按工时比例调整。"},{"word":"proportionable","structure":"proportion + -able","meaning":"able to be brought into proportion","meaningCN":"可与之相称的；可成比例的","example":"The two budgets are proportionable if the scope is cut.","exampleCN":"如果削减范围，两份预算可以相称。"}],"latinEntries":[{"word":"portio","structure":"noun, 3rd declension","meaning":"a share, a portion","meaningCN":"份额；一份"},{"word":"proportio","structure":"pro portione, 'according to the share'","meaning":"comparative relation, ratio","meaningCN":"比较关系；比例"},{"word":"proportionalis","structure":"Late Latin adjective of proportio","meaning":"relating to proportion","meaningCN":"与比例相关的"}]}},{"word":"proportionally","ipa_uk":"/prəˈpɔːʃənəli/","ipa_us":"/prəˈpɔːrʃənəli/","definition_zh":"按比例地；相称地；按份额地；等比例地；按比例代表制地；均衡地","definition_en":"in a way that keeps the same relation or share, so that each change or portion matches another","core_image":"两根柱子沿着同一条斜线一起升降，刻度始终对齐","scene":"The rooms were proportionally arranged, with the largest sitting room placed beside the largest bedroom.","sceneCN":"这里 proportionally 是「匀称地、按相称比例地」（第 8 个义项：布置的尺寸关系相互匹配）；句意：这些房间布置得比例相称，最大的客厅挨着最大的卧室。图中可辨识物件：由大到小排开的门、对齐的墙角线。","pos":[{"tag":"adv.","zh":"按比例地；相称地；按份额地；等比例地"}],"collocations":[{"phrase":"increase proportionally","zh":"按比例增长"},{"phrase":"divide proportionally","zh":"按比例划分"},{"phrase":"scale proportionally","zh":"等比例缩放"},{"phrase":"proportionally allocated","zh":"按比例分配的"},{"phrase":"proportionally representative","zh":"按比例代表的"},{"phrase":"develop proportionally","zh":"成比例地发展"}],"forms":[{"label":"原级","form":"proportionally"},{"label":"比较级","form":"more proportionally"},{"label":"最高级","form":"most proportionally"},{"label":"形容词","form":"proportional"},{"label":"名词","form":"proportion"}],"derivatives":[{"word":"proportional","pos":"adj.","zh":"成比例的；相称的"},{"word":"proportion","pos":"n./v.","zh":"比例；份额；使成比例"},{"word":"proportionate","pos":"adj.","zh":"相称的；成比例的"},{"word":"disproportionately","pos":"adv.","zh":"不成比例地"}],"senses":[{"no":"01","title":"Changing by the same fraction","titleCN":"按同一分数随之变化","definition":"so that a change in one amount produces a matching change in another at a fixed rate","definitionCN":"指一个量的变化使另一量按固定比率产生相配的变化","example":"Wages rose proportionally with the increase in output.","exampleCN":"工资随产量的增加而按比例上升。","why":"The adverb turns proportional into a statement about change: whatever happens to one quantity, the other is adjusted by the same fraction.","whyCN":"这个副词把 proportional 变成对变化的陈述：无论一个量怎样变，另一个量都按同一分数调整。"},{"no":"02","title":"In a fitting degree","titleCN":"以相称的程度","definition":"to a degree that fits the seriousness or size of something else","definitionCN":"达到与另一事物的严重程度或规模相配的程度","example":"The judge insisted that the penalty be proportionally severe to the harm caused.","exampleCN":"法官坚持处罚要与造成的损害程度相称。","why":"Here the share is moral rather than numerical: the response is weighed so that it does not overmatch or undermatch the wrong.","whyCN":"这里的份额是道德性的而非数字性的：回应经过权衡，既不超过也不低于过错。"},{"no":"03","title":"Shared out by shares","titleCN":"按份额分摊","definition":"divided among people or groups according to agreed shares","definitionCN":"按约定份额在人或者群体之间分配","example":"The estate was divided proportionally among the four heirs.","exampleCN":"遗产在四位继承人之间按比例分配。","why":"Distribution uses the oldest share sense: each person receives the fraction that belongs to them, and the adverb describes how the division was made.","whyCN":"分配用的是最古老的份额义：每人得到属于自己的那一份，副词描述划分的方式。"},{"no":"04","title":"Scaled without distortion","titleCN":"等比例缩放而不变形","definition":"enlarged or reduced so that every dimension keeps its relation to the others","definitionCN":"放大或缩小后每个尺寸都保持与其他尺寸的关系","example":"Enlarge the drawing proportionally so that the circles stay round.","exampleCN":"把图等比例放大，让圆仍然是圆的。","why":"Scaling proportionally means applying one multiplier to every measurement. Nothing stretches, because all the fractions between dimensions remain the same.","whyCN":"等比例缩放意味着对每个测量值施加同一个倍数。因为没有哪个尺寸被单独拉伸，所以尺寸之间的分数关系保持不变。"},{"no":"05","title":"Plotted as a true rate","titleCN":"以真实比率绘制","definition":"represented on a graph so that distances show the actual ratio rather than a distorted one","definitionCN":"在图上表示时使距离反映真实比值而非被扭曲的比值","example":"If you plot the two variables proportionally, the slope shows the true growth rate.","exampleCN":"如果把两个变量按比例作图，斜率就显示真实的增长率。","why":"Graphic display also depends on shares: a chart drawn proportionally gives every unit the same length, so slopes can be trusted.","whyCN":"图形展示同样依赖份额：按比例绘制的图表给每个单位相同长度，因此斜率可信。"},{"no":"06","title":"Seats matched to votes","titleCN":"席位与选票相配","definition":"by a system that gives each party seats in rough proportion to its votes","definitionCN":"按使各党席位大致与其选票成比例的制度","example":"In that assembly, seats are allocated proportionally rather than winner-take-all.","exampleCN":"在那个议会中，席位按比例分配，而不是赢者通吃。","why":"Electoral use applies the adverb to allocation: the seats are handed out proportionally, so a party's share of seats tracks its share of votes.","whyCN":"选举用法把这个副词用于分配：席位按比例发放，因此一个政党的席位份额追随其选票份额。"},{"no":"07","title":"Sampled at the true rate","titleCN":"按真实比率抽样","definition":"drawn or weighted so that each subgroup appears in its actual share of the whole","definitionCN":"抽取或加权使每个子群按其在整体中的实际份额出现","example":"The researchers sampled proportionally from each age group to avoid bias.","exampleCN":"研究者从每个年龄组按比例抽样，以避免偏差。","why":"Statistics uses the same logic: if one district holds a quarter of the households, it should supply a quarter of the sample, and the adverb says this was done.","whyCN":"统计学使用同一逻辑：如果一个区占四分之一的住户，它就应提供四分之一的样本，副词说明正是这样做的。"},{"no":"08","title":"With harmonious dimensions","titleCN":"尺寸关系匀称","definition":"in a way that keeps the parts of a design or space in pleasing relation","definitionCN":"指使设计或空间的各部分保持悦目的关系","example":"The furniture was proportionally sized so that the small room never felt crowded.","exampleCN":"家具尺寸比例得当，小房间从不显得拥挤。","why":"Design judges shares by the eye: parts arranged proportionally look calm, because no element crowds or dwarfs its neighbours.","whyCN":"设计用眼睛判断份额：各部分按比例安排看起来沉稳，因为没有元素挤压或压过邻居。"}],"etymology":{"intro":{"en":"Proportionally is proportional plus the adverb suffix -ly. The base goes back to the Latin phrase pro portione, 'according to the share', and the noun proportio. English took the adjective from French, then added its own -ly to make the adverb.","cn":"proportionally 是 proportional 加副词后缀 -ly。其根基可回溯到拉丁短语 pro portione“按份额”与名词 proportio。英语从法语借入形容词，再自己加 -ly 构成副词。"},"items":[{"era":"LATIN portio","en":"Portio meant 'a share, an allotted part'. Every sense of the adverb still assumes that something has been divided into shares.","cn":"portio 意为“份额、分得的部分”。副词的每个义项都仍假定某物已被分成若干份。"},{"era":"LATIN pro portione","en":"The phrase meant 'according to the share'. It described any arrangement in which each part received its due amount.","cn":"这个短语意为“按份额”，描述每一部分各得其应有数量的任何安排。"},{"era":"LATIN proportio / proportionalis","en":"Proportio named the relation between shares, and Late Latin proportionalis turned it into an adjective.","cn":"proportio 命名各份之间的关系，晚期拉丁语 proportionalis 把它变成形容词。"},{"era":"16C. FRENCH proportionnel","en":"French proportionnel supplied the English adjective proportional, first used for fitting arrangement and then for exact ratios.","cn":"法语 proportionnel 提供了英语形容词 proportional，最初用于恰当排列，后用于精确比值。"},{"era":"17C. ADVERB -LY","en":"The English suffix -ly, from Old English -lice, turned proportional into an adverb of manner: in a proportional way.","cn":"英语后缀 -ly 源自古英语 -lice，把 proportional 变成方式副词：以按比例的方式。"},{"era":"19C–20C. SCIENCE AND ELECTIONS","en":"Measurement, sampling and proportional representation all made the adverb common in technical writing.","cn":"计量、抽样与比例代表制都使这个副词在技术写作中变得常见。"}]},"similar":{"note":{"en":"The look-alike group separates the adverb from the adjective, the noun and the near-twin proportionately. The meaning group compares ways of corresponding.","cn":"形近组区分副词与形容词、名词及近似的 proportionately；词义组比较不同的“相对应”方式。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"proportional","ipa":"/prəˈpɔːʃənl/","tag":"adjective","definition":"having a fixed relation or fitting size. It describes the thing, while proportionally describes how something is done.","definitionCN":"具有固定关系或合适大小的。它描述事物，而 proportionally 描述做事的方式。"},{"word":"proportion","ipa":"/prəˈpɔːʃn/","tag":"noun / verb","definition":"a share or the relation between parts. It is the noun behind the whole family.","definitionCN":"份额或各部分之间的关系。它是整个词族背后的名词。"},{"word":"proportionately","ipa":"/prəˈpɔːʃənətli/","tag":"adverb","definition":"in a fitting or fair degree. It leans toward suitability, while proportionally leans toward exact ratio.","definitionCN":"以合适或公平的程度。它偏向“适宜”，而 proportionally 偏向精确比值。"},{"word":"disproportionally","ipa":"/ˌdɪsprəˈpɔːʃənəli/","tag":"adverb","definition":"in a way that is out of proportion. The negative prefix reverses the alignment the base word requires.","definitionCN":"以不成比例的方式。否定前缀反转了基础词所要求的对齐。"}]},{"heading":"NEAR MEANING","entries":[{"word":"correspondingly","ipa":"/kəˈrɒspɒndɪŋli/","tag":"adverb","definition":"in a matching way. It says two things move together without promising a fixed ratio.","definitionCN":"以相配的方式。它说两事物一起变化，但不保证固定比值。"},{"word":"commensurately","ipa":"/kəˈmenʃərətli/","tag":"adverb","definition":"to a degree equal to something else. It stresses equality of measure, often in pay or reward.","definitionCN":"达到与另一事物相等的程度。它强调尺度相等，常用于薪酬或报酬。"},{"word":"evenly","ipa":"/ˈiːvnli/","tag":"adverb","definition":"in equal amounts or without variation. It means equal shares, while proportionally means shares that match a ratio.","definitionCN":"以相等数量或不变化地。它指平均份额，而 proportionally 指符合某一比值的份额。"},{"word":"relatively","ipa":"/rəˈleɪtɪvli/","tag":"adverb","definition":"when compared with something else. It names a comparison but not a fixed proportion.","definitionCN":"与某物比较而言。它命名比较，但不含固定比例。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks keep the image of two columns moving on one slope, then let the adverb describe how shares are kept in changing, dividing, scaling and sampling.","cn":"这些记忆钩保留两根柱子沿同一斜线移动的画面，再让副词描述在变化、分配、缩放与抽样中如何守住份额。"},"normal":[{"en":"Hear the endings: proportional is the adjective, proportionally the adverb that answers 'how?'.","cn":"听清词尾：proportional 是形容词，proportionally 是回答“如何”的副词。"},{"en":"Two columns rise together on one slope: whatever one does, the other does by the same fraction.","cn":"两根柱子沿同一斜线上升：一根怎样，另一根就按同一分数怎样。"},{"en":"Cut a cake proportionally and the child with the bigger share gets the bigger slice, not the same slice.","cn":"按比例分蛋糕，份额大的孩子得到更大的那块，而不是一样大的块。"},{"en":"Resize a picture proportionally and faces stay faces; resize one side only and faces stretch.","cn":"等比例改图片尺寸，脸还是脸；只改一边，脸就被拉长。"},{"en":"Allocate seats proportionally and the seat chart becomes a smaller copy of the vote chart.","cn":"按比例分配席位，席位图就成了选票图的缩小复制。"}],"abstract":[{"en":"The adverb never stands alone: it always implies a second term hidden in the sentence, the thing it is proportional to.","cn":"这个副词从不孤立存在：它总暗含句子里藏着的第二项，也就是它所成比例的对象。"},{"en":"Keep the scale metaphor: proportionally means one ruler is used for every part, never a different ruler per part.","cn":"记住尺子的比喻：按比例意味着所有部分共用一把尺，而不是每部分各用一把。"},{"en":"Notice how the same word serves exact science and rough fairness: the ratio may be measured or judged.","cn":"注意同一个词既服务精确科学，也服务粗略公平：比值可以被测量，也可以被判断。"}]},"examples":[{"en":"The number of staff grew proportionally with the number of patients.","cn":"员工人数随病人数量按比例增长。"},{"en":"The map was scaled proportionally so that distances remained reliable.","cn":"地图按等比例缩放，因此距离仍然可靠。"},{"en":"Funds were distributed proportionally to the size of each department.","cn":"资金按各部门规模的比例分配。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“扑罗破身呢哩”：两份破口一起变大，边破边补，始终成比例。","word":"proportionally"},"root":"拉丁 pro portione“按份额”（portio 份额）派生 proportionalis，英语形容词 proportional 加 -ly 成副词；核心是“按同一分数对应变化”。","sensesIntro":{"en":"Each sense answers 'how?' with the same rule: keep the shares aligned. The adverb can describe quantities that move together, penalties that fit, estates that are divided, drawings that are scaled, graphs that are plotted, seats that follow votes, samples that mirror the population, and rooms that sit well together.","cn":"每个义项都用同一条规则回答“如何”：让各份保持对齐。这个副词可以描述一起变动的数量、相称的处罚、被分配的遗产、被缩放的图、被绘制的图表、追随选票的席位、映照总体的样本，以及相互协调的房间。"},"semanticMap":{"core":{"en":"An action is performed so that every share stays in its fixed relation to the others.","cn":"某动作被执行时，使每一份都保持与其他份的固定关系。"},"chain":["ACT","SHARE","RATIO","MATCH","ADJUST","BALANCE"],"branches":[{"senses":"01 · 05","en":"MEASURE: amounts and plotted distances change by one common fraction.","cn":"计量：数量与绘图距离按同一个分数变化。"},{"senses":"02 · 08","en":"FIT: penalties and rooms are judged to be in due relation.","cn":"相称：处罚与房间被判断为处于恰当关系。"},{"senses":"03 · 06","en":"ALLOCATE: money and seats are handed out by share.","cn":"分配：金钱与席位按份额发放。"},{"senses":"04","en":"SCALE: one multiplier is applied to every dimension.","cn":"缩放：对每个尺寸施加同一个倍数。"},{"senses":"07","en":"SAMPLE: each subgroup enters in its true share.","cn":"抽样：每个子群按真实份额进入。"}]},"affixes":{"intro":{"en":"Proportionally is a Latin share noun with an adjective suffix and an English adverb suffix. The items below show the same base in adjective, noun, near-synonym and negation.","cn":"proportionally 是拉丁“份额”名词加形容词后缀、再加英语副词后缀。下列条目展示同一词基的形容词、名词、近义词与否定形式。"},"latinIntro":{"en":"The Latin entries give the share noun and the derived relation noun. They explain why every form in this family refers back to an allotted portion.","cn":"拉丁语条目给出“份额”名词与派生的关系名词，解释为什么这一词族的每个形式都指回一份分配额。"},"items":[{"word":"proportionally","structure":"proportional + -ly (adverb)","meaning":"according to a proportion","meaningCN":"按比例地","example":"Costs rise proportionally with distance.","exampleCN":"成本随距离按比例上升。"},{"word":"proportional","structure":"pro portione + -al","meaning":"in a fixed relation","meaningCN":"成比例的；相称的","example":"The fee is proportional to income.","exampleCN":"费用与收入成比例。"},{"word":"proportion","structure":"pro portione (phrase)","meaning":"a share; relation between parts","meaningCN":"份额；比例","example":"The proportion of salt to water matters.","exampleCN":"盐与水的比例很关键。"},{"word":"proportionate","structure":"pro + portio + -ate","meaning":"fitting in size or degree","meaningCN":"相称的","example":"The answer was proportionate to the question.","exampleCN":"回答与问题的分量相称。"},{"word":"proportionality","structure":"proportional + -ity","meaning":"the state of being proportionate","meaningCN":"比例性；相称性","example":"The court reviewed the proportionality of the measure.","exampleCN":"法院审查该措施是否相称。"},{"word":"disproportionately","structure":"dis- (not) + proportionately","meaning":"out of proportion","meaningCN":"不成比例地","example":"Small firms were disproportionately affected.","exampleCN":"小企业受到不成比例的影响。"},{"word":"proportionately","structure":"proportionate + -ly","meaning":"in a fitting degree","meaningCN":"相称地；相应地","example":"Punishments should be applied proportionately.","exampleCN":"处罚应当相称地施行。"},{"word":"proportioning","structure":"proportion used as a verb","meaning":"adjusting shares to a fixed relation","meaningCN":"按比例调配","example":"The mixer handles the proportioning of sand and cement.","exampleCN":"搅拌机负责砂与水泥的配比。"}],"latinEntries":[{"word":"portio","structure":"noun, 3rd declension","meaning":"a share, a portion","meaningCN":"份额；一份"},{"word":"proportio","structure":"pro portione, 'according to the share'","meaning":"ratio, comparative relation","meaningCN":"比例；比较关系"},{"word":"proportionalis","structure":"Late Latin adjective","meaning":"relating to proportion","meaningCN":"与比例相关的"}]}},{"word":"proposition","ipa_uk":"/ˌprɒpəˈzɪʃn/","ipa_us":"/ˌprɑːpəˈzɪʃn/","definition_zh":"主张；观点；（逻辑）命题；提议；议案；（商业）交易提议；要处理的事","definition_en":"a statement that something is true, an offer or plan put forward, or a matter that has to be dealt with","core_image":"把一块写着主张的木牌推到桌子中央，让大家看着它表态","scene":"The city placed a housing proposition on the ballot for the November election.","sceneCN":"这里 proposition 是「付诸表决的议案」（第 8 个义项：提交选民投票的提案）；句意：市里把一项住房议案列入十一月选举的选票。图中可辨识物件：选票上的方形选项、桌面中央的木牌。","pos":[{"tag":"n.","zh":"主张；命题；提议；议案；交易提议；待处理的事"}],"collocations":[{"phrase":"a business proposition","zh":"商业提议"},{"phrase":"a value proposition","zh":"价值主张"},{"phrase":"a mathematical proposition","zh":"数学命题"},{"phrase":"ballot proposition","zh":"选票上的议案"},{"phrase":"a tough proposition","zh":"难办的事"},{"phrase":"put forward a proposition","zh":"提出主张"}],"forms":[{"label":"单数","form":"proposition"},{"label":"复数","form":"propositions"},{"label":"动词","form":"propose"},{"label":"名词（提议）","form":"proposal"}],"derivatives":[{"word":"propose","pos":"v.","zh":"提议；提出；求婚"},{"word":"proposal","pos":"n.","zh":"提议；建议；求婚"},{"word":"propositional","pos":"adj.","zh":"命题的"},{"word":"proponent","pos":"n.","zh":"支持者；提议者"}],"senses":[{"no":"01","title":"A statement put forward as true","titleCN":"提出并主张为真的陈述","definition":"a statement that is offered as true and is open to agreement or dispute","definitionCN":"被提出为真、可以被人同意或反驳的陈述","example":"The proposition that cities grow faster than their services is widely tested.","exampleCN":"“城市增长快于其服务能力”这一主张被广泛检验。","why":"Propositio meant 'a setting forth'. A proposition is literally something placed in front of an audience for acceptance or rejection.","whyCN":"propositio 意为“摆出、陈述”。命题字面上就是摆到听众面前、等待接受或拒绝的东西。"},{"no":"02","title":"Logic: true or false","titleCN":"逻辑上非真即假的命题","definition":"in logic, a statement that can be judged true or false","definitionCN":"逻辑中可以判定为真或为假的陈述","example":"In classical logic, 'it is raining' is a proposition because it is either true or false.","exampleCN":"'it is raining' 在经典逻辑中是命题，因为它非真即假。","why":"Logic tightened the everyday statement into a unit of truth value: whatever can be marked true or false counts as a proposition.","whyCN":"逻辑学把日常陈述收紧为真值单位：凡能标记为真或为假的就算命题。"},{"no":"03","title":"An offer or plan","titleCN":"提议、计划","definition":"a plan or suggestion offered to someone for acceptance","definitionCN":"向某人提出、等待其接受的计划或建议","example":"She listened to his proposition and asked for a week to decide.","exampleCN":"她听了他的提议，并要求给她一周时间决定。","why":"The word steps from saying to offering: a proposition is placed before you not just to be believed but to be accepted.","whyCN":"这个词从“说”跨到“提供”：提议摆在你面前，不只是要你相信，更要你接受。"},{"no":"04","title":"A deal on the table","titleCN":"摆在桌面上的交易","definition":"a commercial offer describing what each side would give and get","definitionCN":"描述双方各付出与各获得的商业提议","example":"The merger looked attractive as a business proposition.","exampleCN":"从商业交易的角度看，这次合并颇具吸引力。","why":"Business English uses the noun for deals: the statement placed before a partner promises gains and costs in the same sentence.","whyCN":"商务英语用这个名词指交易：摆在伙伴面前的陈述在同一句话里承诺收益与成本。"},{"no":"05","title":"A statement to be proved","titleCN":"待证明的数学命题","definition":"a mathematical or logical statement that is asserted and then proved","definitionCN":"先被断言、随后被证明的数学或逻辑陈述","example":"Euclid's first proposition constructs an equilateral triangle on a given line.","exampleCN":"欧几里得的第一个命题在给定线段上作等边三角形。","why":"Mathematics keeps the classical sense: a proposition is laid out first, then a proof is built to secure it.","whyCN":"数学保留了古典义：命题先被摆出来，然后通过证明把它落实。"},{"no":"06","title":"A hard thing to handle","titleCN":"棘手的难题","definition":"a person, task or situation that is difficult to deal with","definitionCN":"难以应付的人、任务或局面","example":"Repairing a clock this old is a difficult proposition.","exampleCN":"修这么老的钟是件难办的事。","why":"Informal English extends the offer image to tasks: a proposition is whatever is put in front of you and demands a response, easy or not.","whyCN":"非正式英语把“摆在面前”的意象扩展到任务：proposition 就是摆到你面前、需要你回应的事，无论难易。"},{"no":"07","title":"What a sentence says","titleCN":"语句所表达的内容","definition":"the content that a declarative sentence expresses, as studied in philosophy of language","definitionCN":"陈述句所表达的内容，为语言哲学所研究","example":"Two different sentences can express the same proposition.","exampleCN":"两个不同的句子可以表达同一个命题。","why":"Philosophy separates the sentence from its content: the proposition is what is said, not the particular words used to say it.","whyCN":"哲学把句子与内容分开：命题是被说出的东西，而不是用来说的那些具体词语。"},{"no":"08","title":"A measure put to voters","titleCN":"提交选民表决的议案","definition":"a proposed law or policy placed on a ballot for direct vote","definitionCN":"列入选票、由选民直接表决的法律或政策提案","example":"Voters rejected the tax proposition by a narrow margin.","exampleCN":"选民以微弱差距否决了这项税收议案。","why":"American state politics borrowed the word for measures placed before the electorate, matching the literal 'put before' image.","whyCN":"美国州级政治借这个词指摆到选民面前的措施，正对应字面上“摆在前面”的意象。"}],"etymology":{"intro":{"en":"Proposition descends from Latin propositio, 'a setting forth', and propositum, 'that which is put forward', both from proposere, pro- 'before' plus ponere 'to put'. The same verb gives compose, dispose, impose, oppose, expose, postpone and position, so the whole family is about placing something somewhere.","cn":"proposition 源自拉丁 propositio“陈述、摆出”与 propositum“被摆到前面之物”，两者都出自 proposere（pro-“在前”加 ponere“放置”）。同一个动词还给出 compose、dispose、impose、oppose、expose、postpone 与 position，整个词族都与“把东西放到某处”有关。"},"items":[{"era":"LATIN ponere (source generally considered to be *posinere)","en":"Ponere meant 'to put, place'. It is generally believed to come from *posinere, po- 'away' plus sinere 'to leave or let', though the details are debated.","cn":"ponere 意为“放置”。一般认为它来自 *posinere，即 po-“离开”加 sinere“留置”，但细节仍有争议。"},{"era":"LATIN proposere / propositum","en":"Pro- 'before' plus ponere 'put' made proposere, 'to put before'. Its participle propositum named the thing placed before someone.","cn":"pro-“在前”加 ponere“放置”构成 proposere“摆到前面”。其分词 propositum 命名摆到某人面前的东西。"},{"era":"LATIN propositio","en":"The noun propositio was used in rhetoric for a statement set out for discussion, and in logic for a premise or assertion.","cn":"名词 propositio 在修辞学中指摆出来讨论的陈述，在逻辑学中指前提或断言。"},{"era":"14C. FRENCH proposition","en":"French borrowed the Latin noun as proposition, and English took it over in the 14th century as a term of logic and debate.","cn":"法语借入拉丁名词作 proposition，英语在 14 世纪把它作为逻辑与辩论术语接受过来。"},{"era":"17C. MATHEMATICS","en":"Geometry textbooks called each proved statement a proposition, fixing the sense used in Euclid down to the present.","cn":"几何教科书把每条被证明的陈述称为命题，固定了从欧几里得到今天的用法。"},{"era":"19C–20C. BUSINESS AND BALLOTS","en":"Commercial English added 'a business proposition', and American state politics added the ballot proposition, both keeping the idea of something placed before someone.","cn":"商业英语增加了“商业提议”，美国州级政治增加了“选票议案”，两者都保留把东西摆到某人面前的意思。"}]},"similar":{"note":{"en":"The look-alike group separates proposition from propose, proposal and the share word proportion, which has a different root. The meaning group compares statements, offers and formal claims.","cn":"形近组区分 proposition 与 propose、proposal，以及词根不同的 proportion；词义组比较陈述、提议与正式主张。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"propose","ipa":"/prəˈpəʊz/","tag":"verb","definition":"to put forward a plan or suggestion. It is the action, while proposition is often the thing put forward.","definitionCN":"提出计划或建议。它是动作，而 proposition 常指被提出的东西。"},{"word":"proposal","ipa":"/prəˈpəʊzl/","tag":"noun","definition":"an offer or plan, usually formal. It is the everyday noun from propose, while proposition keeps more of the Latin logic sense.","definitionCN":"提议或计划，通常较正式。它是 propose 的日常名词，而 proposition 保留更多拉丁逻辑义。"},{"word":"preposition","ipa":"/prɪˈpəzɪʃn/","tag":"noun","definition":"a word such as 'in' or 'of'. It shares the root ponere but means 'placed before', not 'set forth as a claim'.","definitionCN":"如 in 或 of 这样的词。它共享 ponere 词根，但意为“放在前面”，而非“作为主张摆出”。"},{"word":"proportion","ipa":"/prəˈpɔːʃn/","tag":"noun","definition":"a share or ratio. It looks similar but comes from portio 'share', a different root, and has nothing to do with placing.","definitionCN":"份额或比值。它看起来相近，却来自 portio“份额”，词根不同，与“放置”无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"proposal","ipa":"/prəˈpəʊzl/","tag":"noun","definition":"a suggestion offered for acceptance, especially in business or marriage. It is the closest everyday word for senses 03 and 04.","definitionCN":"为获得接受而提出的建议，尤用于商务或求婚。它是第 3 与第 4 义项最接近的日常词。"},{"word":"assertion","ipa":"/əˈsɜːʃn/","tag":"noun","definition":"a confident statement that something is true. It stresses the speaker's force rather than the content's truth value.","definitionCN":"自信地断言某事为真。它强调说话者的力度，而非内容的真值。"},{"word":"thesis","ipa":"/ˈθiːsɪs/","tag":"noun","definition":"a claim to be defended in an argument or essay. It is a proposition chosen as the spine of an argument.","definitionCN":"在论证或论文中要辩护的主张。它是被选作论证骨架的命题。"},{"word":"offer","ipa":"/ˈɒfə/","tag":"noun / verb","definition":"something put forward for acceptance, often a price. It covers senses 03 and 04 without the logical weight.","definitionCN":"为获得接受而提出的东西，常指报价。它涵盖第 3 与第 4 义项，但没有逻辑分量。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks hold the literal picture of something placed in front of you, then let it become a claim, a proof, a deal, a task and a ballot measure.","cn":"这些记忆钩抓住“摆到你面前”的字面画面，再让它变成主张、证明、交易、任务与选票议案。"},"normal":[{"en":"Split it as pro + posit + ion: before + placed + noun. A proposition is something placed before you.","cn":"拆成 pro + posit + ion：在前、放置、名词。proposition 就是摆在你面前的东西。"},{"en":"Picture a wooden board with a sentence painted on it, pushed to the middle of a table.","cn":"想象一块木牌上写着一句话，被推到桌子中央。"},{"en":"If the board asks for agreement, it is a claim; if it carries a price, it is a deal.","cn":"如果木牌请求同意，它是主张；如果它标着价格，它就是交易。"},{"en":"If the board is a geometry task, it is a proposition waiting for a proof.","cn":"如果木牌是一道几何任务，它就是等待证明的命题。"},{"en":"If voters must mark it yes or no, it is a ballot proposition.","cn":"如果选民必须勾选赞成或反对，它就是选票上的议案。"}],"abstract":[{"en":"Notice the shared root with position: every proposition is a position that someone has taken.","cn":"注意它与 position 共享词根：每个命题都是某人采取的立场。"},{"en":"Keep saying and offering in one word: the same board can ask 'believe me' or 'accept my terms'.","cn":"把“说”与“提供”放在一个词里：同一块木牌既可以要求“相信我”，也可以要求“接受我的条件”。"},{"en":"Distinguish it from proportional: one is about shares and numbers, the other about something put in front of a mind.","cn":"把它与 proportional 区分：一个讲份额与数字，一个讲摆到心智面前的东西。"}]},"examples":[{"en":"The proposition that memory improves with sleep has been tested repeatedly.","cn":"“记忆随睡眠改善”这一主张已被反复检验。"},{"en":"They treated the franchise offer as an attractive business proposition.","cn":"他们把这份特许经营提议视为有吸引力的商业交易。"},{"en":"Three propositions on housing will appear on the November ballot.","cn":"三项住房议案将出现在十一月选票上。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“扑罗破季身”：把主张写在牌子上，扑到桌子中间，等大家表态。","word":"proposition"},"root":"拉丁 propositio“摆出、陈述”，出自 proposere（pro- 在前 + ponere 放置），分词 propositum；核心是“把某物摆到别人面前”。","sensesIntro":{"en":"Every sense places something before someone: a claim before a listener, a logical unit before a truth test, an offer before a partner, a deal before a buyer, a theorem before a proof, a task before a worker, a content before a philosopher, a measure before voters.","cn":"每个义项都把某物摆到某人面前：主张摆给听者，逻辑单位摆给真值检验，提议摆给伙伴，交易摆给买家，定理摆给证明，任务摆给工作者，内容摆给哲学家，议案摆给选民。"},"semanticMap":{"core":{"en":"Something is set down in front of another person, to be believed, accepted or decided.","cn":"某物被摆到另一个人面前，等待被相信、接受或决定。"},"chain":["PUT","BEFORE","CLAIM","OFFER","PROOF","VOTE"],"branches":[{"senses":"01 · 02 · 07","en":"TRUTH: a statement is laid out to be judged true or false.","cn":"真值：陈述被摆出来，等待判定真假。"},{"senses":"03 · 04","en":"OFFER: the statement becomes terms that another side may accept.","cn":"提供：陈述变成另一方可以接受的条件。"},{"senses":"05","en":"PROOF: a mathematical claim is set out first and secured afterwards.","cn":"证明：数学主张先被摆出，随后被证明。"},{"senses":"06","en":"TASK: whatever is put before you and demands a response, easy or hard.","cn":"任务：摆到你面前、要求回应的事，无论难易。"},{"senses":"08","en":"BALLOT: a measure is placed before the electorate for a direct vote.","cn":"选票：措施被摆到选民面前直接表决。"}]},"affixes":{"intro":{"en":"Proposition is pro- plus positum, the participle of ponere, plus the noun suffix -io. The items below walk the same placing verb through other prefixes, which is why oppose and compose feel related.","cn":"proposition 由 pro-、ponere 的分词 positum 与名词后缀 -io 构成。下列条目让同一个“放置”动词走过其他前缀，oppose 与 compose 之所以显得亲缘正是因此。"},"latinIntro":{"en":"The Latin entries give the placing verb, its participle and its derived noun. They show that the -pose family is one verb with many directions.","cn":"拉丁语条目给出“放置”动词、分词与派生名词，说明 -pose 词族就是同一个动词加多种方向。"},"items":[{"word":"proposition","structure":"propositio, from propositum","meaning":"a statement, offer or measure put forward","meaningCN":"提出的主张、提议或议案","example":"The proposition needs a clear proof.","exampleCN":"这个命题需要清楚的证明。"},{"word":"propose","structure":"pro- + ponere","meaning":"to put forward for consideration","meaningCN":"提出以供考虑","example":"She proposed a new timetable.","exampleCN":"她提出了新的时间表。"},{"word":"proposal","structure":"propose + -al (noun)","meaning":"an offer or plan put forward","meaningCN":"提议；计划","example":"The proposal was accepted without changes.","exampleCN":"该提议未经改动即获通过。"},{"word":"propositional","structure":"proposition + -al","meaning":"relating to propositions","meaningCN":"命题的","example":"The logic course begins with propositional calculus.","exampleCN":"逻辑课从命题演算开始。"},{"word":"oppose","structure":"ob- (against) + ponere","meaning":"to place oneself against","meaningCN":"反对；对抗","example":"Two councillors opposed the plan.","exampleCN":"两名议员反对该计划。"},{"word":"compose","structure":"com- (together) + ponere","meaning":"to place together, to put in order","meaningCN":"组成；创作；使镇定","example":"She composed the letter in one sitting.","exampleCN":"她一口气写成了这封信。"},{"word":"expose","structure":"ex- (out) + ponere","meaning":"to place outside, to leave uncovered","meaningCN":"暴露；揭露","example":"The report exposed serious failures.","exampleCN":"报告揭露了严重失误。"},{"word":"impose","structure":"in- (upon) + ponere","meaning":"to place upon, to force on someone","meaningCN":"强加；征收","example":"The court imposed a heavy fine.","exampleCN":"法院处以重罚。"},{"word":"postpone","structure":"post- (after) + ponere","meaning":"to place after, to delay","meaningCN":"推迟","example":"They postponed the vote until spring.","exampleCN":"他们把表决推迟到春天。"}],"latinEntries":[{"word":"ponere","structure":"3rd conjugation verb","meaning":"to put, to place","meaningCN":"放置"},{"word":"propositum","structure":"past participle used as noun","meaning":"that which is put before","meaningCN":"被摆到前面之物"},{"word":"propositio","structure":"noun of action from propositum","meaning":"a setting forth, a statement","meaningCN":"陈述；命题"}]}},{"word":"psychological","ipa_uk":"/ˌsaɪkəˈlɒdʒɪkl/","ipa_us":"/ˌsaɪkəˈlɑːdʒɪkl/","definition_zh":"心理的；心理学的；心理层面的；（小说）心理描写的；（优势、战争）心理上的；心理上合适的","definition_en":"relating to the mind, to the study of the mind, or to effects that work through feelings rather than physical force","core_image":"打开一个人的头盖，里面不是齿轮而是流动的情绪与念头","scene":"The study found that long periods of noise produced measurable psychological stress even when hearing was unaffected.","sceneCN":"这里 psychological 是「心理层面的」（第 3 个义项：作用于情绪与精神，而非听觉器官）；句意：研究发现在长时间噪声下，即使听力未受影响，也会产生可测量的心理压力。图中可辨识物件：分贝计、被噪声包围的人形轮廓、下沉的情绪曲线。","pos":[{"tag":"adj.","zh":"心理的；心理学的；心理层面的；心理描写的"}],"collocations":[{"phrase":"psychological stress","zh":"心理压力"},{"phrase":"psychological research","zh":"心理学研究"},{"phrase":"psychological effect","zh":"心理影响"},{"phrase":"psychological warfare","zh":"心理战"},{"phrase":"psychological novel","zh":"心理小说"},{"phrase":"the psychological moment","zh":"最恰当的心理时机"}],"forms":[{"label":"原级","form":"psychological"},{"label":"比较级","form":"more psychological"},{"label":"最高级","form":"most psychological"},{"label":"副词","form":"psychologically"},{"label":"名词","form":"psychology"}],"derivatives":[{"word":"psychology","pos":"n.","zh":"心理学；心理"},{"word":"psychologist","pos":"n.","zh":"心理学家"},{"word":"psychologically","pos":"adv.","zh":"心理上地"},{"word":"psych","pos":"n.","zh":"心理（口语）；心理学（口语）"}],"senses":[{"no":"01","title":"Belonging to the mind","titleCN":"属于心智的","definition":"relating to the mind and its processes of thought, feeling and perception","definitionCN":"与心智及其思维、情感与知觉过程相关","example":"Sleep loss has both physical and psychological consequences.","exampleCN":"睡眠不足既有生理后果，也有心理后果。","why":"Psyche meant 'breath, soul, mind'. Psychological marks whatever belongs to that inner life rather than to the body's machinery.","whyCN":"psychē 意为“气息、灵魂、心智”。psychological 标记属于这种内在生活、而非身体机制的东西。"},{"no":"02","title":"Of the discipline","titleCN":"心理学学科的","definition":"belonging to psychology as an academic or clinical field","definitionCN":"属于作为学术或临床领域的心理学","example":"The paper appeared in a leading psychological journal.","exampleCN":"这篇论文发表在一份顶尖心理学期刊上。","why":"Once psychology became a laboratory science in the 19th century, psychological came to mean 'of the discipline', covering experiments, journals and clinics.","whyCN":"19 世纪心理学成为实验室科学之后，psychological 开始指“属于该学科的”，涵盖实验、期刊与诊所。"},{"no":"03","title":"Working through feeling","titleCN":"经由情绪起作用的","definition":"affecting a person through emotions and mental state rather than physical force","definitionCN":"通过情绪与心理状态而非物理力量影响人","example":"The threat of redundancy caused psychological harm long before any job was lost.","exampleCN":"裁员的威胁在任何岗位真正消失之前就已造成心理伤害。","why":"The word names effects that travel through the mind: fear, shame or anxiety can do damage even when no physical injury occurs.","whyCN":"这个词命名经由心智传导的影响：恐惧、羞耻或焦虑即使没有身体伤害，也能造成损伤。"},{"no":"04","title":"Based on mental measurement","titleCN":"以心理测量为依据的","definition":"measured or assessed through mental tests and reported feelings rather than physical instruments","definitionCN":"通过心理测试与自述感受而非物理仪器来测量或评估","example":"The trial used psychological scales to rate anxiety before and after treatment.","exampleCN":"试验用心理量表评定治疗前后的焦虑程度。","why":"Research needed a word for data that comes from questionnaires and scales, so psychological marks the measuring method as well as the subject.","whyCN":"研究需要为来自问卷与量表的数据找个词，于是 psychological 既标记研究对象，也标记测量方法。"},{"no":"05","title":"An edge in the mind","titleCN":"心理上的优势","definition":"giving an advantage by affecting confidence, fear or motivation rather than resources","definitionCN":"通过影响信心、恐惧或动机而非资源来取得优势","example":"Winning the first set gave the team a psychological advantage.","exampleCN":"赢下第一盘给这支队伍带来了心理优势。","why":"Competition uses the adjective for edges that exist only in the mind: the score is level, but one side already feels beaten or emboldened.","whyCN":"竞争用这个形容词指只存在于心里的优势：比分持平，但一方已感到被击败或受到鼓舞。"},{"no":"06","title":"Written from the inside","titleCN":"写出人物内心的","definition":"of a novel or film: focused on inner motives and feelings rather than external action","definitionCN":"指小说或电影聚焦内心动机与感受，而非外部动作","example":"Critics praised the novel as a psychological study of grief.","exampleCN":"评论家称赞这部小说是对悲伤的心理研究。","why":"Literary criticism borrowed the term for works that stay inside a character's mind, where plot matters less than motive.","whyCN":"文学批评借这个词指留在人物内心的作品，在这类作品中情节不如动机重要。"},{"no":"07","title":"The right moment for the mind","titleCN":"心理上最合适的时机","definition":"of a moment: judged to be the point when people are most ready to accept something","definitionCN":"指被人判断为最易接受某事的时刻","example":"He waited for the psychological moment to raise the question of funding.","exampleCN":"他等待心理上最合适的时机提出经费问题。","why":"The fixed phrase 'the psychological moment' treats timing as a mental condition: the instant when resistance is lowest and attention highest.","whyCN":"固定说法“心理上的时机”把时机当作一种心理状态：阻力最低、注意最高的那一刻。"},{"no":"08","title":"Fought through the mind","titleCN":"通过心智进行的","definition":"of warfare or tactics: aimed at beliefs, morale and fear instead of physical targets","definitionCN":"指针对信念、士气与恐惧而非物理目标的战争或战术","example":"Leaflets and broadcasts were part of a psychological campaign against the garrison.","exampleCN":"传单与广播构成了针对守军的心理战的一部分。","why":"Military language uses the adjective when the target is morale: nothing is destroyed, yet the will to fight is attacked directly.","whyCN":"军事语言在目标是士气时用这个形容词：没有东西被摧毁，但战斗意志被直接攻击。"}],"etymology":{"intro":{"en":"Psychological joins Greek psychē, 'breath, soul, mind', with logos, 'word, account, reason', through the Latin-formed psychologia. The -ical ending comes from Latin -icalis and Greek -ikos. The word began as a label for the study of the soul and ended up covering stress, novels, morale and warfare.","cn":"psychological 把希腊语 psychē“气息、灵魂、心智”与 logos“言说、道理、理性”结合，经由拉丁形式的 psychologia 而来。-ical 词尾来自拉丁 -icalis 与希腊 -ikos。这个词最初是“研究灵魂”的标签，后来覆盖压力、小说、士气与战争。"},"items":[{"era":"GREEK ψυχή (source uncertain)","en":"Psyche meant 'breath, life, soul'. Its deeper origin is uncertain; it is generally connected with the idea of breathing, though no root is proved.","cn":"psychē 意为“气息、生命、灵魂”。其更深来源不确定，一般认为与“呼吸”的观念有关，但没有被证实的词根。"},{"era":"GREEK λόγος","en":"Logos meant 'word, account, reason'. Combined with other stems, -logia named a field of study or a body of discourse.","cn":"logos 意为“言说、记述、理性”。与其他词干结合时，-logia 命名一个研究领域或一套论述。"},{"era":"16C. LATIN psychologia","en":"The compound psychologia was coined in Latin by 16th-century scholars for the study of the soul, before any laboratory existed.","cn":"复合词 psychologia 由 16 世纪学者在拉丁语中造出，指对灵魂的研究，当时还没有任何实验室。"},{"era":"17C. ENGLISH psychological","en":"English formed psychological from psychology with the adjective suffix -ical, at first meaning 'of the soul or mind'.","cn":"英语用形容词后缀 -ical 从 psychology 造出 psychological，最初意为“属于灵魂或心智的”。"},{"era":"19C. LABORATORY SCIENCE","en":"Wundt and others turned psychology into an experimental discipline, and psychological came to cover measurement, tests and clinical practice.","cn":"冯特等人把心理学变成实验学科，psychological 随之覆盖测量、测验与临床实践。"},{"era":"20C. WAR, FICTION AND EVERYDAY LIFE","en":"Psychological warfare was named in the two world wars, psychological novels flourished earlier in the century, and the adjective spread to stress, advantage and timing.","cn":"心理战在两次世界大战中得名，心理小说在 20 世纪初兴盛，这个形容词又扩散到压力、优势与时机。"}]},"similar":{"note":{"en":"The look-alike group separates the adjective from psychology, the adverb and the different-root physiological. The meaning group contrasts mental, emotional and cognitive descriptions.","cn":"形近组区分形容词与 psychology、副词，以及词根不同的 physiological；词义组比较 mental、emotional 与 cognitive 三类描述。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"psychology","ipa":"/saɪˈkɒlədʒi/","tag":"noun","definition":"the study of the mind, or a person's mental make-up. It names the field, while psychological describes what belongs to it.","definitionCN":"对心智的研究，或某人的心理构成。它命名字科，而 psychological 描述属于该学科的东西。"},{"word":"psychologically","ipa":"/ˌsaɪkəˈlɒdʒɪkli/","tag":"adverb","definition":"in mental terms. It turns the adjective into a statement about how something affects the mind.","definitionCN":"在心理层面上。它把形容词转为关于如何影响心智的陈述。"},{"word":"physiological","ipa":"/ˌfɪziəˈlɒdʒɪkl/","tag":"adjective","definition":"relating to the body's functions. It looks parallel but comes from physis 'nature' plus logos, a different stem from psyche.","definitionCN":"与身体功能相关的。它看起来结构平行，却来自 physis“自然”加 logos，词干与 psychē 不同。"},{"word":"psychiatric","ipa":"/ˌpsaɪkiˈætrɪk/","tag":"adjective","definition":"relating to the medical treatment of mental illness. It comes from iatreia 'healing', not from logos 'study'.","definitionCN":"与精神疾病的医学治疗相关的。它来自 iatreia“治疗”，而非 logos“研究”。"}]},{"heading":"NEAR MEANING","entries":[{"word":"mental","ipa":"/ˈmentl/","tag":"adjective","definition":"relating to the mind. It is the plain everyday word and often pairs with health and illness, while psychological is more technical.","definitionCN":"与心智相关的。它是平实的日常词，常与健康、疾病搭配，而 psychological 更技术化。"},{"word":"emotional","ipa":"/ɪˈməʊʃənl/","tag":"adjective","definition":"relating to feelings. It covers one part of mental life, while psychological covers the whole inner system.","definitionCN":"与情感相关的。它覆盖心理生活的一部分，而 psychological 覆盖整个内在系统。"},{"word":"cognitive","ipa":"/ˈkɒɡnɪtɪv/","tag":"adjective","definition":"relating to thinking, memory and perception. It names the intellectual side rather than feeling or morale.","definitionCN":"与思维、记忆和知觉相关的。它指理智的一面，而非情绪或士气。"},{"word":"subjective","ipa":"/səbˈdʒektɪv/","tag":"adjective","definition":"existing in a person's own experience. It marks the private side of what psychological studies measure.","definitionCN":"存在于个人自身经验中的。它标记心理研究所测之物的私人一面。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks split the word into psyche and logos, then let the inner-life picture cover stress, science, novels, advantage, timing and warfare.","cn":"这些记忆钩把词拆成 psyche 与 logos，再用内在生活的画面覆盖压力、科学、小说、优势、时机与战争。"},"normal":[{"en":"Split it as psyche + log + ical: mind + study + adjective. Psychological means 'of the study of the mind'.","cn":"拆成 psyche + log + ical：心智、研究、形容词。psychological 意为“关于心智研究的”。"},{"en":"Picture a head opened like a room, with feelings drifting around instead of gears.","cn":"想象一个像房间一样打开的头，里面飘着情绪而不是齿轮。"},{"en":"Physical harm hits the body; psychological harm hits the same person through fear and shame.","cn":"物理伤害打身体；心理伤害通过恐惧与羞耻打同一个人。"},{"en":"A psychological novel stays inside that room, watching motives instead of events.","cn":"心理小说留在那个房间里，看动机而不是看事件。"},{"en":"Psychological warfare attacks morale, so the target is that room rather than any building.","cn":"心理战攻击士气，因此目标就是那个房间，而不是任何建筑。"}],"abstract":[{"en":"Keep the two Greek halves visible: psyche is the subject, logos is the way of studying it.","cn":"让两个希腊部分保持可见：psychē 是对象，logos 是研究方式。"},{"en":"Notice that the adjective can describe both a science and a trick: the same word covers journals and warfare.","cn":"注意这个形容词既能描述科学也能描述手段：同一个词覆盖期刊与战争。"},{"en":"Contrast it with physiological: one studies the mind, the other the body, even though the words look like twins.","cn":"与 physiological 对照：一个研究心智，一个研究身体，尽管两词看起来像双胞胎。"}]},"examples":[{"en":"Researchers measured the psychological effects of isolation on long voyages.","cn":"研究者测量了长期航行中隔离对心理的影响。"},{"en":"The coach said the early goal gave his players a psychological lift.","cn":"教练说那个早早的进球让球员们在心理上受到鼓舞。"},{"en":"The museum mounted a psychological warfare exhibition from the cold war.","cn":"博物馆举办了一场冷战心理战展览。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“赛可乐鸡扣”：赛场上喝口可乐，鸡血一扣，心理状态立刻不同。","word":"psychological"},"root":"希腊 psychē“气息、灵魂、心智”加 logos“言说、研究”构成 psychologia，加 -ical 为形容词；核心是“属于心智及其研究”。","sensesIntro":{"en":"All eight senses point to the inner life: a mind that suffers, a science that studies it, an effect that travels through feeling, a scale that measures it, an advantage that lives in confidence, a novel that stays inside it, a moment when it is ready, and a war that attacks it directly.","cn":"八个义项都指向内在生活：会受苦的心智、研究它的科学、经由情绪传导的影响、测量它的量表、存在于信心中的优势、留在它内部的小说、它准备好的时刻，以及直接攻击它的战争。"},"semanticMap":{"core":{"en":"The inner life of a person, and everything that acts on it or measures it.","cn":"一个人的内在生活，以及作用于它或测量它的一切。"},"chain":["MIND","FEELING","MEASURE","EFFECT","MOTIVE","MORALE"],"branches":[{"senses":"01 · 02","en":"SUBJECT: the mind itself and the discipline that studies it.","cn":"对象：心智本身以及研究它的学科。"},{"senses":"03 · 05","en":"EFFECT: harm or advantage arrives through feeling, not force.","cn":"影响：伤害或优势经由情绪而非力量到来。"},{"senses":"04","en":"MEASURE: scales and tests turn inner states into data.","cn":"测量：量表与测验把内在状态变成数据。"},{"senses":"06","en":"FICTION: a narrative stays inside motive rather than action.","cn":"虚构：叙事留在动机内部，而非外部动作。"},{"senses":"07 · 08","en":"TIMING AND WAR: the mind is either ready to yield or actively attacked.","cn":"时机与战争：心智要么准备好让步，要么正被主动攻击。"}]},"affixes":{"intro":{"en":"Psychological is psyche plus logos plus the adjective suffix -ical. The items below follow the Greek stems into nouns, adverbs and neighbouring disciplines.","cn":"psychological 由 psyche、logos 与形容词后缀 -ical 构成。下列条目沿着这两个希腊词干走到名词、副词与邻近学科。"},"latinIntro":{"en":"The Greek entries give the two stems. They explain why psychology, psychiatry and psychosomatic all begin with the same word for soul.","cn":"希腊语条目给出两个词干，解释了为什么 psychology、psychiatry 与 psychosomatic 都以同一个表示“灵魂”的词开头。"},"items":[{"word":"psychological","structure":"psyche + logos + -ical","meaning":"relating to the mind or its study","meaningCN":"心理的；心理学的","example":"The survey tracked psychological recovery.","exampleCN":"这项调查追踪心理康复情况。"},{"word":"psychology","structure":"psychologia, from psyche + logos","meaning":"the study of the mind","meaningCN":"心理学；心理","example":"She studied psychology at university.","exampleCN":"她在大学学习心理学。"},{"word":"psychologist","structure":"psychology + -ist (person)","meaning":"a person who studies the mind","meaningCN":"心理学家","example":"A psychologist assessed the child's anxiety.","exampleCN":"一位心理学家评估了孩子的焦虑。"},{"word":"psychologically","structure":"psychological + -ly","meaning":"in mental terms","meaningCN":"心理上地","example":"The workers were psychologically exhausted.","exampleCN":"工人们在心理上已精疲力竭。"},{"word":"psychic","structure":"psyche + -ic","meaning":"relating to the mind; also claiming extra-sensory powers","meaningCN":"心灵的；通灵的","example":"He claimed psychic experiences during the experiment.","exampleCN":"他声称在实验中有通灵体验。"},{"word":"psychiatry","structure":"psyche + iatreia (healing)","meaning":"the medical treatment of mental illness","meaningCN":"精神病学","example":"Psychiatry treated the trauma with therapy and drugs.","exampleCN":"精神病学用治疗与药物处理创伤。"},{"word":"psychosomatic","structure":"psyche + soma (body)","meaning":"of symptoms caused or worsened by mental factors","meaningCN":"心身的；由心理因素引起的","example":"The rash was judged psychosomatic.","exampleCN":"这皮疹被判断为心身性的。"},{"word":"psyche","structure":"Greek noun","meaning":"the soul or mind as a whole","meaningCN":"心灵；心智整体","example":"The myth describes the trials of Psyche.","exampleCN":"这个神话描述了普绪克的试炼。"}],"latinEntries":[{"word":"ψυχή","structure":"Greek noun, 'breath, soul'","meaning":"the breath of life; the mind","meaningCN":"生命的气息；心智"},{"word":"λόγος","structure":"Greek noun, 'word, reason'","meaning":"account, study, reasoning","meaningCN":"言说；道理；研究"},{"word":"-λογία","structure":"Greek noun suffix","meaning":"a field of study or discourse","meaningCN":"研究领域；论述体系"}]}},{"word":"psychologically","ipa_uk":"/ˌsaɪkəˈlɒdʒɪkli/","ipa_us":"/ˌsaɪkəˈlɑːdʒɪkli/","definition_zh":"心理上；在心理层面；从心理学角度；在心理上合适地；通过心理手段","definition_en":"in terms of the mind, or in a way that works through feelings and mental states","core_image":"一把尺子量不到的地方，改用观察情绪的刻度来量","scene":"Even after the flood water had gone, residents remained psychologically unsettled for months.","sceneCN":"这里 psychologically 是「在心理层面上」（第 1 个义项：就精神状态而言，而非物理处境）；句意：即使洪水退去数月，居民在心理上仍不安。图中可辨识物件：退去的洪水线、仍紧绷的坐姿、窗户上的水痕。","pos":[{"tag":"adv.","zh":"在心理上；从心理学角度；心理上地"}],"collocations":[{"phrase":"psychologically damaging","zh":"造成心理伤害的"},{"phrase":"psychologically prepared","zh":"做好心理准备的"},{"phrase":"psychologically dependent","zh":"心理上依赖的"},{"phrase":"psychologically safe","zh":"心理安全的"},{"phrase":"psychologically demanding","zh":"心理负担重的"},{"phrase":"psychologically speaking","zh":"从心理上说"}],"forms":[{"label":"原级","form":"psychologically"},{"label":"比较级","form":"more psychologically"},{"label":"最高级","form":"most psychologically"},{"label":"形容词","form":"psychological"},{"label":"名词","form":"psychology"}],"derivatives":[{"word":"psychological","pos":"adj.","zh":"心理的；心理学的"},{"word":"psychology","pos":"n.","zh":"心理学；心理"},{"word":"psychologist","pos":"n.","zh":"心理学家"},{"word":"psyche","pos":"n.","zh":"心灵；心智"}],"senses":[{"no":"01","title":"In terms of the mind","titleCN":"就心理状态而言","definition":"as far as a person's mental state is concerned rather than their physical situation","definitionCN":"就一个人的精神状态而言，而非其物理处境","example":"The refugees were psychologically exhausted even after reaching safety.","exampleCN":"难民们即使抵达安全之地，心理上仍已精疲力竭。","why":"The adverb turns the adjective into a viewpoint: look at the same situation through the mind rather than through the body.","whyCN":"这个副词把形容词变成一种视角：透过心智而非身体去看待同一处境。"},{"no":"02","title":"From the discipline's angle","titleCN":"从心理学角度","definition":"in the manner or framework of psychology as a field of study","definitionCN":"以心理学作为研究领域的方式或框架","example":"Psychologically speaking, the experiment tests memory rather than intelligence.","exampleCN":"从心理学角度看，这个实验测的是记忆而非智力。","why":"This use announces its frame: the speaker is not offering a medical or moral judgement but one drawn from psychological theory.","whyCN":"这种用法宣告了框架：说话者给出的不是医学或道德判断，而是取自心理学理论的判断。"},{"no":"03","title":"Acting through feeling","titleCN":"经由情绪产生作用","definition":"in a way that operates through emotions and mental states rather than through physical means","definitionCN":"以通过情绪与心理状态、而非物理手段的方式起作用","example":"The advertisement worked psychologically, making buyers feel excluded without saying so.","exampleCN":"这则广告在心理上起了作用，让买家不知不觉感到被排斥。","why":"Here the adverb describes a mechanism: influence travels through feelings, so nothing physical needs to happen.","whyCN":"这里的副词描述一种机制：影响经由情绪传导，因此无需任何物理事件发生。"},{"no":"04","title":"By mental measurement","titleCN":"以心理测量的方式","definition":"by means of mental tests, scales or self-report rather than physical instruments","definitionCN":"借助心理测验、量表或自述，而非物理仪器","example":"The two groups were psychologically assessed before and after the course.","exampleCN":"两组在课程前后都接受了心理评估。","why":"Research methods need the adverb to say how data were gathered: not with a thermometer but with a scale that records anxiety or motivation.","whyCN":"研究方法需要这个副词说明数据如何收集：不是用温度计，而是用记录焦虑或动机的量表。"},{"no":"05","title":"In the mind's timing","titleCN":"就心理时机而言","definition":"at the point judged right for people's readiness to accept something","definitionCN":"在人们最易于接受某事而被判断为恰当的时刻","example":"The announcement came psychologically at the worst possible time, just before the holiday.","exampleCN":"这项宣布在心理上来的时机最糟，恰在假期之前。","why":"Timing can be read mentally: the same date may be practically convenient and psychologically disastrous, depending on how people feel.","whyCN":"时机可以按心理来读：同一个日期在实务上可能方便，在心理上却可能灾难，取决于人的感受。"},{"no":"06","title":"Through morale and fear","titleCN":"通过士气与恐惧","definition":"by attacking beliefs, confidence or fear instead of physical targets","definitionCN":"通过攻击信念、信心或恐惧，而非物理目标","example":"The campaign aimed psychologically at the enemy's will to continue.","exampleCN":"这场战役在心理上瞄准敌军继续作战的意志。","why":"Military use of the adverb marks the target as mental: the operation is judged by broken morale rather than destroyed equipment.","whyCN":"军事上使用这个副词，把目标标记为心理性的：行动以士气崩溃而非装备被毁来衡量。"},{"no":"07","title":"Inside a character's mind","titleCN":"在人物内心层面","definition":"in a narrative manner that stays with inner motive and feeling","definitionCN":"以叙事方式留在内心动机与感受之中","example":"The film is psychologically rich but visually almost still.","exampleCN":"这部影片在心理层面很丰富，视觉上却几乎静止。","why":"Critics use the adverb for depth of inner portrayal: the story is judged by what happens inside a character, not by what happens on screen.","whyCN":"评论者用这个副词指内心刻画的深度：故事以人物内部发生的事来衡量，而不是屏幕上发生的事。"},{"no":"08","title":"In terms of mental advantage","titleCN":"就心理优势而言","definition":"in relation to confidence, fear or motivation as a source of advantage","definitionCN":"就作为优势来源的信心、恐惧或动机而言","example":"The home side was psychologically on top long before the first goal.","exampleCN":"早在第一个进球之前，主队就在心理上占了上风。","why":"Competitive talk uses the adverb to locate an edge that the scoreboard has not yet shown: one side already feels it is winning.","whyCN":"竞争话语用这个副词定位记分牌尚未显示的优势：一方已经感觉自己正在赢。"}],"etymology":{"intro":{"en":"Psychologically is psychological plus -ly. The base combines Greek psyche, 'breath, soul', with logos, 'word, reason', through the Latin-formed psychologia. The adverb simply says that something is being considered, caused or measured at the level of the mind.","cn":"psychologically 是 psychological 加 -ly。词基经由拉丁形式的 psychologia，把希腊语 psychē“气息、灵魂”与 logos“言说、理性”结合。这个副词只是说某事被放在心智层面上考虑、造成或测量。"},"items":[{"era":"GREEK ψυχή (source uncertain)","en":"Psyche meant 'breath, life, soul'. Its deeper origin is uncertain; a link with breathing is generally assumed but not proved.","cn":"psychē 意为“气息、生命、灵魂”。更深来源不确定，与呼吸的关联一般被假定，但未获证明。"},{"era":"GREEK λόγος","en":"Logos covered 'word, account, reason'. As a suffix, -logia named a field of study, and psychologia named the study of the soul.","cn":"logos 涵盖“言说、记述、理性”。作为后缀，-logia 命名研究领域，psychologia 即“对灵魂的研究”。"},{"era":"16C–17C. psychologia TO psychological","en":"Latin psychologia produced English psychology, and the adjective psychological followed with the suffix -ical.","cn":"拉丁 psychologia 产生英语 psychology，形容词 psychological 随后带 -ical 出现。"},{"era":"17C. ADVERB -LY","en":"English added -ly, from Old English -lice, to make an adverb of manner and viewpoint.","cn":"英语加上源自古英语 -lice 的 -ly，构成表示方式与视角的副词。"},{"era":"19C. EXPERIMENTAL PSYCHOLOGY","en":"As the field turned experimental, the adverb entered reports of mental measurement: assessed psychologically, affected psychologically.","cn":"随着该领域转向实验，这个副词进入心理测量的报告：接受心理评估、受心理影响。"},{"era":"20C. CLINICAL AND POPULAR USE","en":"Clinical writing, advertising analysis and film criticism spread the adverb to harm, safety, preparation and inner portrayal.","cn":"临床写作、广告分析与电影批评把这个副词扩散到伤害、安全感、准备与内心刻画。"}]},"similar":{"note":{"en":"The look-alike group separates the adverb from the adjective, the noun and the body-based physiological. The meaning group compares ways of describing mental effect.","cn":"形近组区分副词与形容词、名词，以及以身体为基础的 physiological；词义组比较描述心理影响的不同方式。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"psychological","ipa":"/ˌsaɪkəˈlɒdʒɪkl/","tag":"adjective","definition":"relating to the mind. It describes the thing, while psychologically describes the level or the manner.","definitionCN":"与心智相关的。它描述事物，而 psychologically 描述层面或方式。"},{"word":"psychology","ipa":"/saɪˈkɒlədʒi/","tag":"noun","definition":"the study of the mind. It names the field that the adverb can invoke as a frame.","definitionCN":"对心智的研究。它命名副词可以援引的框架。"},{"word":"physiologically","ipa":"/ˌfɪziəˈlɒdʒɪkli/","tag":"adverb","definition":"in terms of body function. It looks like a twin but comes from physis 'nature', not psyche 'soul'.","definitionCN":"就身体功能而言。它看起来像双胞胎，却来自 physis“自然”，而非 psychē“灵魂”。"},{"word":"psychically","ipa":"/ˈpsaɪkɪkli/","tag":"adverb","definition":"by means of the mind, often in claims about extra-sensory powers. It is narrower and more controversial than psychologically.","definitionCN":"借助心智，常用于关于超感官能力的说法。它比 psychologically 更窄，也更具争议。"}]},{"heading":"NEAR MEANING","entries":[{"word":"mentally","ipa":"/ˈmentli/","tag":"adverb","definition":"in the mind. It is the plain everyday choice for states and health, while psychologically often sounds clinical or academic.","definitionCN":"在心智上。它是描述状态与健康的日常平实选择，而 psychologically 常带临床或学术色彩。"},{"word":"emotionally","ipa":"/ɪˈməʊʃənəli/","tag":"adverb","definition":"in terms of feelings. It names one part of mental life, while psychologically covers the whole system.","definitionCN":"就情感而言。它命名心理生活的一部分，而 psychologically 覆盖整个系统。"},{"word":"subjectively","ipa":"/səbˈdʒektɪvli/","tag":"adverb","definition":"according to personal experience. It stresses the private viewpoint rather than the mind as a system.","definitionCN":"依据个人经验。它强调私人视角，而非作为系统的心智。"},{"word":"behaviorally","ipa":"/bɪˈheɪvjərəli/","tag":"adverb","definition":"in terms of observable conduct. It marks the outside of a person, while psychologically marks the inside.","definitionCN":"就可观察的行为而言。它标记人的外部，而 psychologically 标记内部。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks turn the word into a viewpoint: put on mind-glasses and the same event looks different.","cn":"这些记忆钩把词变成一种视角：戴上“心智眼镜”，同一件事看起来就不一样。"},"normal":[{"en":"Split it as psyche + log + ical + ly: mind, study, adjective, how. It means 'viewed at the level of the mind'.","cn":"拆成 psyche + log + ical + ly：心智、研究、形容词、方式。它意为“从心智层面看”。"},{"en":"Picture a ruler that measures everything except fear, then a second scale that measures only fear.","cn":"想象一把什么都能量、却量不到恐惧的尺子，再想象一把只量恐惧的秤。"},{"en":"A flood line on a wall shows where water stopped; a person still tense months later shows where it did not.","cn":"墙上的洪水线显示水退到哪里；数月后仍紧绷的人显示它没退到哪里。"},{"en":"Advertising that never touches you still works psychologically, because it aims at how you feel about yourself.","cn":"从不触碰你的广告仍能在心理上起作用，因为它瞄准的是你对自己的感受。"},{"en":"Winning before the first goal is a psychological lead: the scoreboard is silent but the players are not.","cn":"在第一个进球前就领先，是心理上的领先：记分牌沉默，球员却不沉默。"}],"abstract":[{"en":"Ask which layer is being described: body, behaviour or mind. The word always answers 'mind'.","cn":"问清描述的是哪一层：身体、行为还是心智。这个词总是回答“心智”。"},{"en":"Notice that the adverb can describe both damage and defence: psychologically harmed, psychologically prepared.","cn":"注意这个副词既能描述伤害也能描述防御：受到心理伤害、做好心理准备。"},{"en":"Keep the -logical tail visible: the word does not mean 'by magic', it means 'as the mind works or as the field studies it'.","cn":"让 -logical 词尾保持可见：这个词不是“靠魔法”，而是“按心智运作方式”或“按该学科研究方式”。"}]},"examples":[{"en":"Witnesses were psychologically unprepared for the details they were shown.","cn":"证人对被展示的细节在心理上没有准备。"},{"en":"The training aims to make staff psychologically safe enough to report errors.","cn":"这项培训旨在让员工在心理上足够安全，敢于报告错误。"},{"en":"Psychologically, the second rejection hurt more than the first.","cn":"从心理上说，第二次被拒比第一次更伤人。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“赛可乐鸡扣哩”：赛前喝口可乐、打点鸡血，心理上立刻不一样。","word":"psychologically"},"root":"希腊 psychē“气息、灵魂、心智”加 logos“研究”成 psychologia，形容词 psychological 加 -ly 成副词；核心是“放在心智层面来看”。","sensesIntro":{"en":"The adverb always marks a layer: not the body, not the wallet, but the mind. People can be exhausted, harmed, prepared, assessed, timed, targeted, portrayed or led psychologically, and in each case the effect runs through feeling and mental state.","cn":"这个副词总在标记一个层面：不是身体，不是钱包，而是心智。人可以在心理上疲惫、受伤、准备、被评估、被安排时机、被瞄准、被刻画、被领先，每一种情况下影响都经由情绪与心理状态传导。"},"semanticMap":{"core":{"en":"An event or action is considered at the level of the mind rather than the body or the world.","cn":"某事件或行动被放在心智层面而非身体或外部世界来考虑。"},"chain":["LEVEL","MIND","FEELING","EFFECT","ASSESS","TIMING"],"branches":[{"senses":"01 · 03","en":"INWARD EFFECT: something lands on a person's state rather than their body.","cn":"向内的影响：某物落在人的状态上，而非身体上。"},{"senses":"02","en":"FRAME: the statement is made from within the discipline of psychology.","cn":"框架：这一陈述是在心理学学科内部作出的。"},{"senses":"04","en":"MEASURE: scales and tests gather the evidence.","cn":"测量：量表与测验收集证据。"},{"senses":"05 · 06","en":"CONTROL: timing, morale and fear are the handles that get pushed.","cn":"控制：时机、士气与恐惧是被推动的把手。"},{"senses":"07 · 08","en":"READING: inner portrayal and mental advantage are what observers report.","cn":"解读：内心刻画与心理优势是观察者所报告的内容。"}]},"affixes":{"intro":{"en":"Psychologically is a Greek compound with a Latin adjective ending and an English adverb ending. The items below follow the same stems into noun, person, discipline and the body-rooted contrast.","cn":"psychologically 是希腊复合词加拉丁形容词词尾与英语副词词尾。下列条目沿着同一词干走到名词、人称、学科以及与身体词根的对照。"},"latinIntro":{"en":"The Greek entries give the soul word and the study word. They explain why the whole family starts from breath and ends in measurement.","cn":"希腊语条目给出“灵魂”与“研究”两个词，解释为什么整个词族从“气息”开始、以“测量”收尾。"},"items":[{"word":"psychologically","structure":"psychological + -ly (adverb)","meaning":"at the level of the mind","meaningCN":"在心理层面上","example":"The team was psychologically ready for setbacks.","exampleCN":"团队在心理上已为挫折做好准备。"},{"word":"psychological","structure":"psyche + logos + -ical","meaning":"relating to the mind","meaningCN":"心理的","example":"The report noted psychological damage.","exampleCN":"报告指出了心理伤害。"},{"word":"psychology","structure":"psychologia","meaning":"the study of the mind","meaningCN":"心理学","example":"Modern psychology relies on controlled trials.","exampleCN":"现代心理学依赖对照试验。"},{"word":"psychologist","structure":"psychology + -ist","meaning":"one who practises psychology","meaningCN":"心理学家","example":"The psychologist tested recall after sleep.","exampleCN":"这位心理学家测试了睡眠后的回忆。"},{"word":"psychometric","structure":"psyche + metron (measure)","meaning":"relating to mental measurement","meaningCN":"心理测量的","example":"The firm uses psychometric tests in hiring.","exampleCN":"这家公司在招聘中使用心理测量。"},{"word":"psychosomatic","structure":"psyche + soma (body)","meaning":"bodily symptoms driven by mental factors","meaningCN":"心身的","example":"Doctors found no organ damage, only psychosomatic pain.","exampleCN":"医生没发现器官损伤，只有心身性疼痛。"},{"word":"physiologically","structure":"physis + logos + -ically","meaning":"in terms of body function","meaningCN":"生理上地","example":"The drug acts physiologically, not mentally.","exampleCN":"这种药作用于生理，而非心理。"},{"word":"mentally","structure":"mental + -ly","meaning":"in the mind","meaningCN":"在精神上","example":"He remained mentally sharp at ninety.","exampleCN":"他九十岁时头脑依然敏锐。"}],"latinEntries":[{"word":"ψυχή","structure":"Greek noun","meaning":"breath, soul, mind","meaningCN":"气息；灵魂；心智"},{"word":"λόγος","structure":"Greek noun","meaning":"word, reason, study","meaningCN":"言说；理性；研究"},{"word":"μέτρον","structure":"Greek noun, 'measure'","meaning":"a measure or scale","meaningCN":"尺度；量度"}]}},{"word":"quantitatively","ipa_uk":"/ˌkwɒntɪˈteɪtɪvli/","ipa_us":"/ˌkwɑːntəˈteɪtɪvli/","definition_zh":"在数量上；从数量上；定量地；以数值方式；按数量计算地","definition_en":"in terms of amount or number, especially by measuring and expressing things numerically","core_image":"把一堆模糊的感觉装进量杯，读出具体刻度","scene":"The two lakes differ quantitatively in depth but not in water quality.","sceneCN":"这里 quantitatively 是「在数量上」（第 1 个义项：就深度这一可计量的量而言）；句意：这两个湖在深度上数量不同，但水质并无差别。图中可辨识物件：两支带刻度的量筒、标着数字的深度尺。","pos":[{"tag":"adv.","zh":"在数量上；定量地；以数值方式"}],"collocations":[{"phrase":"differ quantitatively","zh":"在数量上不同"},{"phrase":"measure quantitatively","zh":"定量测量"},{"phrase":"quantitatively assessed","zh":"定量评估的"},{"phrase":"quantitatively larger","zh":"在数量上更大的"},{"phrase":"quantitatively based","zh":"以数量为依据的"},{"phrase":"quantitatively significant","zh":"在数量上显著的"}],"forms":[{"label":"原级","form":"quantitatively"},{"label":"比较级","form":"more quantitatively"},{"label":"最高级","form":"most quantitatively"},{"label":"形容词","form":"quantitative"},{"label":"名词","form":"quantity"}],"derivatives":[{"word":"quantitative","pos":"adj.","zh":"数量的；定量的"},{"word":"quantity","pos":"n.","zh":"数量；量"},{"word":"quantify","pos":"v.","zh":"量化；用数量表示"},{"word":"qualitatively","pos":"adv.","zh":"定性地；从性质上"}],"senses":[{"no":"01","title":"In terms of amount","titleCN":"就数量而言","definition":"as far as amount, size or number is concerned rather than quality","definitionCN":"就数量、规模或数目而言，而非性质","example":"The two proposals differ quantitatively but not in principle.","exampleCN":"这两项提案在数量上不同，但原则上一致。","why":"Quantus meant 'how much'. The adverb sets the comparison on the scale of amount: it asks how much there is, not what kind it is.","whyCN":"quantus 意为“多少”。这个副词把比较放到数量尺度上：它问的是有多少，而不是什么性质。"},{"no":"02","title":"By measurement, not impression","titleCN":"以测量而非印象的方式","definition":"by counting or measuring rather than by description or judgement","definitionCN":"通过计数或测量，而非描述或判断","example":"The damage was assessed quantitatively with satellite images and ground counts.","exampleCN":"损害通过卫星影像与地面计数作了定量评估。","why":"Here the adverb names a method: instead of saying 'severe', the researcher produces a number that others can check.","whyCN":"这里的副词命名一种方法：研究者不说“严重”，而是给出别人可以核查的数字。"},{"no":"03","title":"Expressed as numbers","titleCN":"以数值表达","definition":"in a form that can be written as figures and compared arithmetically","definitionCN":"以可以写成数字并进行算术比较的形式","example":"The report described the shortage quantitatively as a gap of four hundred units.","exampleCN":"报告把短缺定量描述为四百个单位的缺口。","why":"Expression is the point here: an observation becomes numerical so that it can enter tables, ratios and models.","whyCN":"这里的要点是表达：观察变成数值，从而能进入表格、比值与模型。"},{"no":"04","title":"In experimental practice","titleCN":"在实验操作中","definition":"as a laboratory or field procedure that produces measurable values","definitionCN":"作为产生可测数值的实验室或现场程序","example":"The team studied the reaction quantitatively by tracking mass at every minute.","exampleCN":"团队每分钟记录质量，从而定量研究这一反应。","why":"Experimental science uses the adverb for procedure: the apparatus is arranged so that the outcome comes out as a reading, not an opinion.","whyCN":"实验科学用这个副词指操作程序：仪器被安排得使结果呈现为读数，而不是意见。"},{"no":"05","title":"By counts and rates","titleCN":"用计数与比率","definition":"through counts, frequencies or rates that can be added and compared","definitionCN":"通过可相加、可比较的计数、频次或比率","example":"The survey compared the two districts quantitatively using hospital admissions.","exampleCN":"该调查用住院人数对两个区作了定量比较。","why":"Statistics speaks of what can be counted: admissions, frequencies, rates. The adverb marks that those counts, not stories, carry the comparison.","whyCN":"统计学谈可计数之物：住院人数、频次、比率。这个副词标记承载比较的是这些计数，而非故事。"},{"no":"06","title":"In a measurable degree","titleCN":"达到可度量的程度","definition":"to a degree that can be measured and stated as an amount","definitionCN":"达到可被测量并表述为一个数量的程度","example":"Performance improved quantitatively, though reviewers still found the writing weak.","exampleCN":"表现在数量上有提升，不过评审仍认为文字薄弱。","why":"Sometimes the adverb limits a claim: whatever improved did so in measurable amount, while quality may have stayed the same.","whyCN":"有时这个副词限定主张：提升发生在可度量的数量上，而质量可能没变。"},{"no":"07","title":"On the scale of quantity","titleCN":"在量的标尺上","definition":"judged on a scale of more or less rather than better or worse","definitionCN":"按多与少的标尺判断，而非按好与坏","example":"The two cities are quantitatively similar in size but qualitatively very different.","exampleCN":"这两座城市在规模上数量相近，性质上却大不相同。","why":"The adverb names the axis of comparison: one city may be bigger while the other is livelier, and only size belongs to this axis.","whyCN":"这个副词命名比较的轴：一座城市可能更大，另一座更有活力，而只有规模属于这条轴。"},{"no":"08","title":"By numerical standard","titleCN":"按数值标准","definition":"according to a numerical threshold or target rather than a general impression","definitionCN":"依据数值门槛或目标，而非整体印象","example":"Applicants were ranked quantitatively against a published scoring grid.","exampleCN":"申请人依照公布的评分表按数值排序。","why":"Institutions use the adverb when a number decides: a grid, a threshold or a score replaces the feeling that something is good enough.","whyCN":"机构在由数字决定时使用这个副词：评分表、门槛或分数取代了“够好”的感觉。"}],"etymology":{"intro":{"en":"Quantitatively is quantitative plus -ly. Quantitative comes from Medieval Latin quantitativus, built on quantitas, 'quantity', from quantus, 'how much or how many'. The Roman interrogative about size became the modern word for numerical measurement.","cn":"quantitatively 是 quantitative 加 -ly。quantitative 来自中古拉丁 quantitativus，建于 quantitas“数量”之上，而后者出自 quantus“多少”。罗马人问大小的疑问词，成了现代表示数值测量的词。"},"items":[{"era":"LATIN quantus","en":"Quantus was the interrogative and relative word for 'how much, how many'. It asked about amount rather than kind; its partner qualis asked about kind.","cn":"quantus 是表示“多少”的疑问与关系词，问的是数量而非种类；与之配对的 qualis 问的是种类。"},{"era":"LATIN quantitas","en":"Quantitas turned the question into a noun: 'amount, quantity, magnitude'. It let speakers talk about size as a thing in itself.","cn":"quantitas 把疑问变成名词：“数量、量、大小”，使说话者能把规模当作一种事物来谈。"},{"era":"MEDIEVAL LATIN quantitativus","en":"Scholars formed quantitativus for what belongs to quantity, in contrast with qualitativus for what belongs to quality.","cn":"学者造出 quantitativus 指属于数量的东西，与指属于性质的 qualitativus 相对。"},{"era":"16C–17C. ENGLISH quantitative","en":"English adopted quantitative through French and used it first in philosophy and mathematics, where the quantity/quality pair was already standard.","cn":"英语经法语借入 quantitative，最初用于哲学与数学，那里“量/质”的配对已是标准。"},{"era":"19C. MEASUREMENT IN SCIENCE","en":"As chemistry and physics demanded numbers, quantitative became the label for methods that count, weigh and calibrate.","cn":"随着化学与物理要求数字，quantitative 成为计数、称重与校准方法的标签。"},{"era":"20C. SOCIAL SCIENCES AND FINANCE","en":"Economics and social research spread the adverb to surveys, scoring grids and quantitative easing in monetary policy.","cn":"经济学与社会科学把这个副词扩散到调查、评分表，以及货币政策中的量化宽松。"}]},"similar":{"note":{"en":"The look-alike group separates the adverb from the adjective, the noun and the different-root qualitative. The meaning group contrasts numerical, measurable and statistical description.","cn":"形近组区分副词与形容词、名词，以及词根不同的 qualitative；词义组比较数值、可测与统计三类描述。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"quantitative","ipa":"/ˈkwɒntɪteɪtɪv/","tag":"adjective","definition":"relating to amount. It describes the kind of data, while quantitatively describes how something is expressed or compared.","definitionCN":"与数量相关的。它描述数据种类，而 quantitatively 描述表达或比较的方式。"},{"word":"quantity","ipa":"/ˈkwɒntəti/","tag":"noun","definition":"an amount or number. It is the base noun behind the whole family.","definitionCN":"数量或数目。它是整个词族背后的基础名词。"},{"word":"qualitatively","ipa":"/ˌkwɒlɪˈteɪtɪvli/","tag":"adverb","definition":"in terms of quality. It looks parallel but comes from qualis 'of what kind', not quantus 'how much'.","definitionCN":"就性质而言。它看起来结构平行，却来自 qualis“何种”，而非 quantus“多少”。"},{"word":"quantifiably","ipa":"/ˌkwɒntɪˈfaɪəbli/","tag":"adverb","definition":"in a way that can be expressed as a quantity. It stresses possibility, while quantitatively stresses the mode of treatment.","definitionCN":"以可以表示为数量的方式。它强调可能性，而 quantitatively 强调处理方式。"}]},{"heading":"NEAR MEANING","entries":[{"word":"numerically","ipa":"/njuːˈmerɪkli/","tag":"adverb","definition":"by means of numbers. It is close to sense 03 but says nothing about measuring method.","definitionCN":"借助数字地。它接近第 3 义项，但不涉及测量方法。"},{"word":"measurably","ipa":"/ˈmeʒərəbli/","tag":"adverb","definition":"to a degree that can be measured. It often modifies improvement or change, as in sense 06.","definitionCN":"达到可测量的程度。它常修饰改进或变化，如第 6 义项。"},{"word":"statistically","ipa":"/stəˈtɪstɪkli/","tag":"adverb","definition":"according to statistical methods. It adds probability and sampling, which quantitatively alone does not.","definitionCN":"按统计方法地。它增加概率与抽样，而单说 quantitatively 没有这些。"},{"word":"arithmetically","ipa":"/ˌærɪθˈmetɪkli/","tag":"adverb","definition":"by calculation with numbers. It points to the operation rather than the measurement.","definitionCN":"用数字计算地。它指向运算，而非测量。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks fix the word to the question 'how much?', then let the answer become measurement, expression, counting, degree and standard.","cn":"这些记忆钩把词固定在“多少”这一问句上，再让答案变成测量、表达、计数、程度与标准。"},"normal":[{"en":"Split it as quant + itative + ly: how much + adjective + how. It answers 'how?' with numbers.","cn":"拆成 quant + itative + ly：多少、形容词、方式。它用数字回答“如何”。"},{"en":"Picture pouring a vague complaint into a measuring jug and reading a scale.","cn":"想象把一句模糊的抱怨倒进量杯，读出刻度。"},{"en":"Two lakes can be quantitatively different in depth while qualitatively identical in taste.","cn":"两个湖在深度上可以有数量差异，在味道上却性质相同。"},{"en":"A survey that counts admissions works quantitatively; one that records interviews works qualitatively.","cn":"统计住院人数的调查按定量工作；记录访谈的调查按定性工作。"},{"en":"When a scoring grid decides the ranking, the decision was made quantitatively.","cn":"当评分表决定排名时，这个决定就是按数量作出的。"}],"abstract":[{"en":"Keep the pair quantus/qualis in mind: one asks how much, the other asks of what kind.","cn":"心里记住 quantus 与 qualis 的配对：一个问多少，一个问何种。"},{"en":"The adverb can limit praise: quantitatively better means bigger or more, not necessarily finer.","cn":"这个副词可以限制赞美：数量上更好意味着更大或更多，未必更精细。"},{"en":"Notice the two directions: it can describe how something is measured, or how it is described. Both roads lead to numbers.","cn":"注意两个方向：它既可描述如何测量，也可描述如何表述。两条路都通向数字。"}]},"examples":[{"en":"The two economies differ quantitatively in output but share similar institutions.","cn":"这两个经济体在产出数量上不同，但制度相似。"},{"en":"The lab measured the pollution quantitatively rather than describing it in general terms.","cn":"实验室对污染作了定量测量，而不是笼统描述。"},{"en":"The reviewers asked whether the improvement could be shown quantitatively.","cn":"评审要求证明这项改进能以数量方式呈现。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“宽提特提夫利”：把宽窄大小都提出来，逐条量成数字。","word":"quantitatively"},"root":"拉丁 quantus“多少”派生 quantitas“数量”，中古拉丁 quantitativus 加英语 -ly 成副词；核心是“按多少、用数字来谈”。","sensesIntro":{"en":"Each sense answers with a number: how much they differ, how the damage was measured, how the shortage is expressed, how the experiment was run, how the districts were counted, how far performance improved, which axis is being compared, and which threshold decided the ranking.","cn":"每个义项都用数字回答：差多少、损害如何测量、短缺如何表述、实验如何操作、各区如何计数、表现改进到什么程度、在比哪条轴、由哪个门槛决定排序。"},"semanticMap":{"core":{"en":"Everything is pushed onto the axis of amount, where 'more' and 'less' are the only directions.","cn":"一切都被推到“数量”这条轴上，那里只有“更多”与“更少”两个方向。"},"chain":["AMOUNT","MEASURE","NUMBER","COMPARE","DEGREE","STANDARD"],"branches":[{"senses":"01 · 07","en":"AXIS: the comparison is set on size, not on character.","cn":"轴：比较建立在规模上，而非性质上。"},{"senses":"02 · 04","en":"METHOD: counting and apparatus replace impression.","cn":"方法：计数与仪器取代印象。"},{"senses":"03","en":"EXPRESSION: the finding is written as a figure.","cn":"表达：发现被写成数字。"},{"senses":"05","en":"COUNTING: frequencies and rates carry the conclusion.","cn":"计数：频次与比率承载结论。"},{"senses":"06 · 08","en":"DEGREE: improvement and ranking are decided by a measurable threshold.","cn":"程度：改进与排序由可测量的门槛决定。"}]},"affixes":{"intro":{"en":"Quantitatively is quantus plus the quantity noun plus an adjective and an adverb ending. The items below follow the how-much stem and contrast it with the how-kind stem.","cn":"quantitatively 由 quantus、数量名词、形容词词尾与副词词尾构成。下列条目沿着“多少”词干，并与“何种”词干对照。"},"latinIntro":{"en":"The Latin entries give the interrogative and the noun. They explain why quantity, quantify and quantitative all begin with a question about size.","cn":"拉丁语条目给出疑问词与名词，解释为什么 quantity、quantify 与 quantitative 都以一个关于大小的疑问开头。"},"items":[{"word":"quantitatively","structure":"quantitative + -ly","meaning":"in terms of amount or number","meaningCN":"在数量上；定量地","example":"The risks were compared quantitatively.","exampleCN":"这些风险作了定量比较。"},{"word":"quantitative","structure":"quantitas + -ive","meaning":"relating to quantity","meaningCN":"数量的；定量的","example":"Quantitative data filled the appendix.","exampleCN":"附录里满是定量数据。"},{"word":"quantity","structure":"quantitas, from quantus","meaning":"an amount or number","meaningCN":"数量","example":"A large quantity of sand was moved.","exampleCN":"大量沙子被运走。"},{"word":"quantify","structure":"quantus + facere (make)","meaning":"to express as a quantity","meaningCN":"量化","example":"It is hard to quantify the loss of trust.","exampleCN":"信任的损失难以量化。"},{"word":"quantification","structure":"quantify + -ication","meaning":"the act of expressing as a quantity","meaningCN":"量化","example":"The quantification of risk took months.","exampleCN":"风险的量化花了数月。"},{"word":"qualitatively","structure":"qualis + -tative + -ly","meaning":"in terms of quality","meaningCN":"定性地","example":"The interviews were analysed qualitatively.","exampleCN":"这些访谈作了定性分析。"},{"word":"qualitative","structure":"qualitas + -ive","meaning":"relating to quality","meaningCN":"性质的；定性的","example":"Qualitative evidence came from diaries.","exampleCN":"定性证据来自日记。"},{"word":"quantum","structure":"quantus used as a noun","meaning":"a fixed amount; a unit of energy","meaningCN":"定量；量子","example":"The theory treats light as quanta.","exampleCN":"该理论把光当作量子。"}],"latinEntries":[{"word":"quantus","structure":"interrogative adjective","meaning":"how much, how many","meaningCN":"多少"},{"word":"quantitas","structure":"noun, 3rd declension","meaning":"amount, quantity, magnitude","meaningCN":"数量；量；大小"},{"word":"quantitativus","structure":"Medieval Latin adjective","meaning":"relating to quantity","meaningCN":"与数量相关的"}]}},{"word":"quantitative","ipa_uk":"/ˈkwɒntɪteɪtɪv/","ipa_us":"/ˈkwɑːntəteɪtɪv/","definition_zh":"数量的；定量的；可量化的；以数字表示的；按量计的；（经济）数量型的","definition_en":"relating to amount or number, especially when data are measured and expressed as figures","core_image":"一架天平把两堆东西换成两排数字","scene":"The paper combined quantitative data from weather stations with interviews from farmers.","sceneCN":"这里 quantitative 是「定量的」（第 2 个义项：可计数、可统计的数值资料）；句意：这篇论文把气象站的定量数据与农民的访谈结合起来。图中可辨识物件：一排排读数、温度曲线、访谈记录本。","pos":[{"tag":"adj.","zh":"数量的；定量的；可量化的"}],"collocations":[{"phrase":"quantitative data","zh":"定量数据"},{"phrase":"quantitative analysis","zh":"定量分析"},{"phrase":"quantitative research","zh":"定量研究"},{"phrase":"quantitative easing","zh":"量化宽松"},{"phrase":"quantitative measure","zh":"数量指标"},{"phrase":"quantitative change","zh":"数量变化"}],"forms":[{"label":"原级","form":"quantitative"},{"label":"比较级","form":"more quantitative"},{"label":"最高级","form":"most quantitative"},{"label":"副词","form":"quantitatively"},{"label":"名词","form":"quantity"}],"derivatives":[{"word":"quantity","pos":"n.","zh":"数量；量"},{"word":"quantify","pos":"v.","zh":"量化；用数量表示"},{"word":"quantitatively","pos":"adv.","zh":"定量地；在数量上"},{"word":"qualitative","pos":"adj.","zh":"定性的；性质上的"}],"senses":[{"no":"01","title":"About amount","titleCN":"关于数量的","definition":"concerned with amount, size or number rather than kind","definitionCN":"关心数量、规模或数目，而非种类","example":"The report offers a quantitative picture of how many households lack clean water.","exampleCN":"报告用数量呈现了有多少家庭缺乏清洁用水。","why":"Quantus asked 'how much'. Quantitative marks whatever deals with that question instead of the question 'what kind'.","whyCN":"quantus 问的是“多少”。quantitative 标记处理这个问题的东西，而不是处理“何种”问题的东西。"},{"no":"02","title":"Measured and counted","titleCN":"测量与计数的","definition":"based on measurement, counting and numerical records","definitionCN":"以测量、计数与数值记录为基础","example":"Quantitative evidence showed a steady fall in soil moisture.","exampleCN":"定量证据显示土壤含水量持续下降。","why":"Data become quantitative when they can be counted or measured, so that another researcher could repeat the count and get the same figure.","whyCN":"数据在可被计数或测量时才算定量，因为另一位研究者可以重复计数并得到同一数字。"},{"no":"03","title":"Expressible as a number","titleCN":"可表示为数字的","definition":"able to be stated as a figure, rate or percentage","definitionCN":"可以表述为数字、比率或百分比的","example":"Speed is quantitative because it can be given a number and a unit.","exampleCN":"速度是定量的，因为它可以用一个数字加单位给出。","why":"The property itself is not a number, but it accepts one: give it a unit and a scale and it can be written as a figure.","whyCN":"这种属性本身不是一个数字，但它接受数字：给它一个单位与一把尺，它就能写成一个数值。"},{"no":"04","title":"The style of a study","titleCN":"研究类型的","definition":"of research: using statistical samples and numerical analysis rather than interviews or interpretation","definitionCN":"指研究使用统计样本与数值分析，而非访谈或解释","example":"The team ran a quantitative study of sleep and exam performance.","exampleCN":"团队开展了一项关于睡眠与考试成绩的定量研究。","why":"A quantitative study is one whose design turns behaviour into variables. Interviews may accompany it, but the spine is the number.","whyCN":"定量研究是设计把行为变成变量的研究。访谈可以并存，但骨架是数字。"},{"no":"05","title":"Amount-based policy","titleCN":"以数量为手段的政策","definition":"of economic policy: working by expanding the amount of money or credit rather than by setting interest rates","definitionCN":"指经济政策通过扩大货币或信贷数量、而非设定利率来运作","example":"The central bank turned to quantitative easing when rates were already near zero.","exampleCN":"利率已接近零时，央行转向量化宽松。","why":"Economics uses the adjective for policy that changes quantities directly: the lever is the amount of money created, not its price.","whyCN":"经济学用这个形容词指直接改变数量的政策：杠杆是创造出来的货币量，而不是货币的价格。"},{"no":"06","title":"Written as figures","titleCN":"写成数字的","definition":"presented in numerical form, as tables, charts or scores","definitionCN":"以表格、图表或分数等数字形式呈现","example":"The results section is largely quantitative, with four tables and two graphs.","exampleCN":"结果部分主要是数字呈现，有四张表与两幅图。","why":"Presentation is the visible half of the word: even before anyone counts, the material has been arranged as figures so that patterns can be read at a glance.","whyCN":"呈现是这个词可见的一半：甚至在计数之前，材料已被排成数字，让模式一眼可读。"},{"no":"07","title":"On the more-or-less axis","titleCN":"处在多与少的轴上","definition":"judged by more or less rather than better or worse","definitionCN":"按多与少判断，而不是按好与坏","example":"There was a quantitative gain in sales but no qualitative change in the product.","exampleCN":"销售有数量上的增长，但产品没有性质上的改变。","why":"The word names the axis itself. A quantitative gain can be counted, even when nothing about the thing has become better in kind.","whyCN":"这个词命名的是轴本身。数量上的增长可以被计数，即使事物在性质上并未变好。"},{"no":"08","title":"The numerical side of science","titleCN":"科学中的数值一面","definition":"belonging to the branch of a science that deals with measurable magnitudes and their relations","definitionCN":"属于科学中处理可测大小及其关系的部分","example":"Quantitative chemistry asks how much of each substance reacts.","exampleCN":"定量化学研究每种物质反应多少。","why":"Every science splits into a qualitative and a quantitative side. The quantitative side asks for magnitudes and laws that connect them.","whyCN":"每门科学都分为定性与定量两面。定量的一面追问大小以及连接大小的规律。"}],"etymology":{"intro":{"en":"Quantitative is Medieval Latin quantitativus, from quantitas 'quantity', from quantus 'how much'. It was coined as the partner of qualitativus, the adjective for quality, and entered English through French in the 16th century.","cn":"quantitative 来自中古拉丁 quantitativus，出自 quantitas“数量”，再出自 quantus“多少”。它是作为 qualitativus（性质的形容词）的配对词被造出的，16 世纪经法语进入英语。"},"items":[{"era":"LATIN quantus","en":"Quantus asked 'how much, how many'. It belongs to the same interrogative family as qualis 'of what kind', and the pair still shapes scientific vocabulary.","cn":"quantus 问“多少”。它与 qualis“何种”同属疑问词族，这对搭配至今塑造着科学词汇。"},{"era":"LATIN quantitas","en":"Quantitas named amount as a thing in itself. Roman writers used it for size, magnitude and number.","cn":"quantitas 把数量当作一种事物来命名。罗马作者用它指大小、量值与数目。"},{"era":"MEDIEVAL LATIN quantitativus","en":"Schoolmen built quantitativus for what belongs to quantity. The category was standard in philosophy before any modern science used it.","cn":"经院学者造出 quantitativus 指属于数量的东西。在现代科学使用它之前，这个范畴在哲学中已是标准。"},{"era":"16C. FRENCH quantitatif","en":"French passed the adjective to English as quantitative, first in philosophy and mathematics.","cn":"法语把形容词 quantitatif 传给英语作 quantitative，最初用于哲学与数学。"},{"era":"19C. MEASURING SCIENCES","en":"Chemistry, physics and economics made quantitative the mark of reliable work: if it could be counted, it could be trusted.","cn":"化学、物理与经济学使 quantitative 成为可靠工作的标记：能计数就可信。"},{"era":"20C. CENTRAL BANKING AND SOCIAL SCIENCE","en":"Quantitative easing named a monetary policy of the 2000s, while survey research made quantitative methods a standard phrase.","cn":"量化宽松命名了 2000 年代的货币政策，调查研究中“定量方法”也成为标准说法。"}]},"similar":{"note":{"en":"The look-alike group separates the adjective from its noun, verb and the different-root qualitative. The meaning group contrasts numerical, measurable and statistical description.","cn":"形近组区分形容词与名词、动词，以及词根不同的 qualitative；词义组比较数值、可测与统计三类描述。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"quantity","ipa":"/ˈkwɒntəti/","tag":"noun","definition":"an amount or number. It is the noun that the adjective describes.","definitionCN":"数量或数目。它是这个形容词所描述的名词。"},{"word":"quantify","ipa":"/ˈkwɒntɪfaɪ/","tag":"verb","definition":"to express something as a quantity. It is the action of making data quantitative.","definitionCN":"把某物表示为数量。它就是把数据变成定量的动作。"},{"word":"quantitatively","ipa":"/ˌkwɒntɪˈteɪtɪvli/","tag":"adverb","definition":"in terms of amount. It tells how a comparison or measurement is made.","definitionCN":"在数量上。它说明比较或测量如何进行。"},{"word":"qualitative","ipa":"/ˌkwɒlɪˈteɪtɪv/","tag":"adjective","definition":"relating to quality. It looks parallel but comes from qualis 'of what kind', not quantus 'how much'.","definitionCN":"与性质相关的。它看起来结构平行，却来自 qualis“何种”，而非 quantus“多少”。"}]},{"heading":"NEAR MEANING","entries":[{"word":"numerical","ipa":"/njuːˈmerɪkl/","tag":"adjective","definition":"given in numbers. It says the form is numeric, while quantitative also implies measurement and amount.","definitionCN":"以数字给出的。它说形式是数字的，而 quantitative 还隐含测量与数量。"},{"word":"measurable","ipa":"/ˈmeʒərəbl/","tag":"adjective","definition":"able to be measured. It describes a property, while quantitative describes an approach or a body of data.","definitionCN":"可测量的。它描述一种属性，而 quantitative 描述一种做法或一批数据。"},{"word":"statistical","ipa":"/stəˈtɪstɪkl/","tag":"adjective","definition":"based on statistics. It adds sampling and probability to the plain idea of counting.","definitionCN":"基于统计的。它在单纯计数之上加上了抽样与概率。"},{"word":"metric","ipa":"/ˈmetrɪk/","tag":"adjective","definition":"relating to measurement, especially in a system of units. It is narrower than quantitative.","definitionCN":"与测量相关的，尤指单位制。它比 quantitative 更窄。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks put the word on the how-much axis, then let it cover data, studies, policies, tables and the numerical side of every science.","cn":"这些记忆钩把词放到“多少”这条轴上，再让它覆盖数据、研究、政策、表格与每门科学的数值一面。"},"normal":[{"en":"Split it as quant + itative: how much + adjective. It labels anything that answers with a number.","cn":"拆成 quant + itative：多少、形容词。它标记任何用数字回答问题的事物。"},{"en":"Picture a balance that converts two piles into two rows of figures.","cn":"想象一架天平把两堆东西换算成两排数字。"},{"en":"If the report counts households, it is quantitative; if it describes their lives, it is qualitative.","cn":"如果报告统计户数，它是定量的；如果描述他们的生活，它是定性的。"},{"en":"Quantitative easing changes the amount of money, not the price of borrowing.","cn":"量化宽松改变货币的数量，而不是借贷的价格。"},{"en":"A quantitative gain is more of the same, not a better kind of thing.","cn":"数量上的增长是同类东西更多，而不是变成更好的种类。"}],"abstract":[{"en":"Keep the quantus/qualis pair: one question asks how much, the other asks of what kind.","cn":"记住 quantus 与 qualis 的配对：一个问题问多少，另一个问何种。"},{"en":"Notice that the word describes both the data and the attitude: count it, then trust it.","cn":"注意这个词既描述数据，也描述态度：先计数，再相信。"},{"en":"Whenever you meet it, look for the unit: quantitative talk always carries a hidden 'of what'.","cn":"每次遇到它，都去找单位：定量话语总藏着一个“什么的多少”。"}]},"examples":[{"en":"The two reviews reached the same conclusion using different quantitative methods.","cn":"这两篇综述用不同的定量方法得出了相同结论。"},{"en":"Researchers reported a quantitative difference of about twelve percent.","cn":"研究者报告了约百分之十二的数量差异。"},{"en":"The bank's quantitative easing programme ran for three years.","cn":"该银行的量化宽松计划持续了三年。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“宽提特提夫”：把宽窄高低都提出来，一条条变成数字。","word":"quantitative"},"root":"拉丁 quantus“多少”派生 quantitas“数量”，中古拉丁 quantitativus 作形容词；核心是“能数、能量、用数字回答”。","sensesIntro":{"en":"The eight senses all sit on the axis of amount: how many households, how much moisture, what speed, what study design, what money supply, what table, what gain, what magnitude. Qualitative asks what kind; quantitative asks how much.","cn":"八个义项都坐在“数量”这条轴上：多少户、多少水分、什么速度、什么研究设计、多少货币供给、哪张表、多少增长、多大数值。定性问“何种”，定量问“多少”。"},"semanticMap":{"core":{"en":"Data are counted or measured and then written as figures that other people can compare.","cn":"数据被计数或测量，然后写成别人可以比较的数字。"},"chain":["AMOUNT","COUNT","MEASURE","FIGURE","COMPARE","POLICY"],"branches":[{"senses":"01 · 06","en":"AXIS AND FORM: the subject is amount, and the form is numerical.","cn":"轴与形式：主题是数量，形式是数字。"},{"senses":"02 · 03","en":"DATA: counting and measurement make a value that can be repeated.","cn":"数据：计数与测量造出可重复的数值。"},{"senses":"04 · 07","en":"STUDY: a design turns behaviour into variables and gains into amounts.","cn":"研究：设计把行为变成变量，把增益变成数量。"},{"senses":"05","en":"POLICY: the lever is the quantity of money itself.","cn":"政策：杠杆就是货币的数量本身。"},{"senses":"08","en":"SCIENCE: the numerical branch asks for magnitudes and laws.","cn":"科学：数值分支追问大小与规律。"}]},"affixes":{"intro":{"en":"Quantitative is quantus plus quantitas plus the adjective suffix -ive. The items below follow the how-much stem and set it beside the how-kind stem.","cn":"quantitative 由 quantus、quantitas 与形容词后缀 -ive 构成。下列条目沿着“多少”词干，并与“何种”词干对照。"},"latinIntro":{"en":"The Latin entries give the question word and the noun. They show why quantity, quantify and quantitative all answer the same question.","cn":"拉丁语条目给出疑问词与名词，说明为什么 quantity、quantify 与 quantitative 都在回答同一个问题。"},"items":[{"word":"quantitative","structure":"quantitas + -ive","meaning":"relating to amount","meaningCN":"数量的；定量的","example":"Quantitative measures dominated the report.","exampleCN":"报告以定量指标为主。"},{"word":"quantity","structure":"quantitas, from quantus","meaning":"an amount","meaningCN":"数量","example":"A small quantity of mercury remained.","exampleCN":"还剩下少量水银。"},{"word":"quantify","structure":"quantus + facere","meaning":"to make into a quantity","meaningCN":"量化","example":"Scientists tried to quantify the damage.","exampleCN":"科学家试图量化损害。"},{"word":"quantitatively","structure":"quantitative + -ly","meaning":"in terms of amount","meaningCN":"定量地；在数量上","example":"The sites were compared quantitatively.","exampleCN":"这些地点作了定量比较。"},{"word":"quantification","structure":"quantify + -ication","meaning":"the act of quantifying","meaningCN":"量化","example":"Quantification made the claims testable.","exampleCN":"量化使这些主张可被检验。"},{"word":"qualitative","structure":"qualitas + -ive","meaning":"relating to quality","meaningCN":"定性的；性质的","example":"Qualitative interviews added context.","exampleCN":"定性访谈补充了背景。"},{"word":"quantity surveyor","structure":"quantity + surveyor","meaning":"a specialist who measures building costs","meaningCN":"工料测量师","example":"The quantity surveyor priced the steelwork.","exampleCN":"工料测量师为钢结构估价。"},{"word":"quantum","structure":"quantus as a noun","meaning":"a fixed amount; a discrete unit","meaningCN":"定量；量子","example":"Energy arrives in quanta, not in a smooth flow.","exampleCN":"能量以量子形式到来，而非平滑流动。"}],"latinEntries":[{"word":"quantus","structure":"interrogative adjective","meaning":"how much, how many","meaningCN":"多少"},{"word":"quantitas","structure":"noun, 3rd declension","meaning":"amount, magnitude","meaningCN":"数量；大小"},{"word":"quantitativus","structure":"Medieval Latin adjective","meaning":"belonging to quantity","meaningCN":"属于数量的"}]}},{"word":"qualification","ipa_uk":"/ˌkwɒlɪfɪˈkeɪʃn/","ipa_us":"/ˌkwɑːləfəˈkeɪʃn/","definition_zh":"资格；资历；证书；限定条件；保留意见；（语法）修饰；（体育）预选赛","definition_en":"a skill, certificate or condition that makes someone suitable, or a limitation added to a statement","core_image":"在一张表上逐格打钩，够格的人才被放进候选名单","scene":"The job requires a teaching qualification and at least two years of classroom experience.","sceneCN":"这里 qualification 是「资格证书」（第 2 个义项：证明具备任教资历的正式凭证）；句意：这份工作要求具备教师资格证书，以及至少两年的课堂经验。图中可辨识物件：盖章的证书、勾选过的条件清单。","pos":[{"tag":"n.","zh":"资格；资历；证书；限定条件；修饰；预选赛"}],"collocations":[{"phrase":"professional qualification","zh":"专业资格"},{"phrase":"teaching qualification","zh":"教师资格"},{"phrase":"without qualification","zh":"无条件地；毫无保留地"},{"phrase":"a qualification to a statement","zh":"对陈述的限定"},{"phrase":"entry qualification","zh":"入学资格"},{"phrase":"qualification round","zh":"预选赛轮"}],"forms":[{"label":"单数","form":"qualification"},{"label":"复数","form":"qualifications"},{"label":"动词","form":"qualify"},{"label":"形容词","form":"qualified"}],"derivatives":[{"word":"qualify","pos":"v.","zh":"取得资格；使合格；限定"},{"word":"qualified","pos":"adj.","zh":"合格的；有保留的"},{"word":"qualifier","pos":"n.","zh":"限定词；预选赛"},{"word":"qualitative","pos":"adj.","zh":"定性的；性质上的"}],"senses":[{"no":"01","title":"Being fit for a role","titleCN":"胜任某一角色的资格","definition":"the skills, knowledge or experience that make a person suitable for a job or role","definitionCN":"使人适合某项工作或角色的技能、知识或经验","example":"Her qualifications for the post include six years of field research.","exampleCN":"她胜任这一职位的资历包括六年实地研究经验。","why":"Qualis asked 'of what kind' and facere meant 'make'. To qualify is to make someone of the right kind for a role, and the noun names that fitness.","whyCN":"qualis 问“何种”，facere 意为“使”。qualify 就是使人变成适合某角色的那种类型，名词命名的正是这种适合。"},{"no":"02","title":"A certificate that proves it","titleCN":"证明资格的证书","definition":"an official certificate, degree or licence showing that a person has met a standard","definitionCN":"证明某人达到某项标准的正式证书、学位或执照","example":"The clinic hires only nurses with a recognised qualification.","exampleCN":"这家诊所只聘用持有认可资格证书的护士。","why":"The abstract fitness became a paper object: the certificate stands in for the training so an employer can check it quickly.","whyCN":"抽象的适合变成一张纸：证书代替培训过程，让雇主能快速核查。"},{"no":"03","title":"A limit on a claim","titleCN":"对说法的限定","definition":"a condition or limitation attached to a statement, making it narrower or less absolute","definitionCN":"附加在陈述上的条件或限制，使其范围更窄或不再绝对","example":"He accepted the plan with one qualification: the budget must not exceed ten million.","exampleCN":"他接受这项计划，但有一个限定条件：预算不得超过一千万。","why":"Qualis asks 'of what kind'. Here the kind is narrowed: the acceptance is not absolute but of one specific, limited kind, and the clause states the limit.","whyCN":"qualis 问“何种”。这里种类被收窄：接受不是绝对的，而是某个特定、有限的种类，而那个从句说明了限度。"},{"no":"04","title":"The act of becoming fit","titleCN":"取得资格的过程","definition":"the process of training or being certified as suitable for a profession","definitionCN":"为胜任某一职业而接受培训或被认证的过程","example":"Qualification as a midwife takes three years in that country.","exampleCN":"在那个国家，取得助产士资格需要三年。","why":"The noun also names the journey rather than the endpoint: the training, examinations and supervised practice that produce a qualified person.","whyCN":"这个名词也命名过程而非终点：产生合格者的培训、考试与督导实习。"},{"no":"05","title":"Grammar: narrowing a noun","titleCN":"语法上的修饰限定","definition":"the act of a word or phrase limiting or describing another word","definitionCN":"词或短语限制、描述另一词的作用","example":"In 'the red door', 'red' performs a qualification of 'door'.","exampleCN":"在“那扇红门”中，“红”对“门”起限定修饰作用。","why":"Grammar borrowed the limiting sense: the modifier says what kind of door is meant, cutting the noun down from all doors to one described kind.","whyCN":"语法借用了限制义：修饰语说明指的是哪一种门，把名词从所有门收窄到被描述的那一种。"},{"no":"06","title":"A round before the main event","titleCN":"正式赛事前的预选","definition":"a preliminary stage in which competitors earn the right to enter the main competition","definitionCN":"参赛者争取进入正赛资格的预赛阶段","example":"She finished second in the qualification and reached the final.","exampleCN":"她在预选赛中名列第二，进入了决赛。","why":"Sport borrowed the fitness idea: a qualification round decides who is fit to enter the main draw.","whyCN":"体育借用了“适合”的观念：预选赛决定谁有资格进入正赛。"},{"no":"07","title":"Agreement with reservations","titleCN":"带保留意见的同意","definition":"approval given with stated doubts or conditions","definitionCN":"在说明疑虑或条件的前提下给予赞同","example":"The committee gave its qualification rather than outright support.","exampleCN":"委员会给出的是有保留的认可，而非无条件支持。","why":"Approval is granted, but as a qualified kind: the doubts are stated at the same time, so the support is real yet bounded.","whyCN":"认可被给予了，但属于带限定的一类：疑虑同时被说明，因此支持是真的，却有边界。"},{"no":"08","title":"A restricting clause in law","titleCN":"法律中的限制条款","definition":"a clause that limits the scope of a right, rule or agreement","definitionCN":"限制某项权利、规则或协议范围的条款","example":"The lease contains a qualification on subletting the premises.","exampleCN":"租约中有一条关于转租房屋的限制条款。","why":"Law states the limits explicitly: the clause makes the tenant's right a particular, restricted kind rather than an unrestricted one.","whyCN":"法律把限度明说出来：这条使租客的权利成为某种特定、受限的类型，而非不受限制的类型。"}],"etymology":{"intro":{"en":"Qualification comes from Medieval Latin qualificatio, built on qualificare, 'to make of a certain kind'. Qualis meant 'of what kind' and facere meant 'to make'. The word began in scholastic philosophy as the assigning of a quality and later became the everyday word for fitness, certificates and reservations.","cn":"qualification 来自中古拉丁 qualificatio，建于 qualificare“使成为某种”之上。qualis 意为“何种”，facere 意为“使”。这个词始于经院哲学中“赋予性质”的用法，后来成为表示适合、证书与保留意见的日常词。"},"items":[{"era":"LATIN qualis","en":"Qualis was the interrogative and relative word for 'of what kind'. It is the partner of quantus 'how much', and the pair still organizes scientific vocabulary.","cn":"qualis 是表示“何种”的疑问与关系词，与 quantus“多少”配对，这对搭配至今组织着科学词汇。"},{"era":"LATIN facere","en":"Facere meant 'to make, to do'. Added to a stem, -ficare built verbs of making, as in aedificare and modificare.","cn":"facere 意为“做、造”。加在词干后，-ficare 构成表示“使……”的动词，如 aedificare、modificare。"},{"era":"MEDIEVAL LATIN qualificare","en":"Scholastic Latin formed qualificare, 'to make of a certain quality or kind'. It was used for describing and for assigning properties.","cn":"经院拉丁语造出 qualificare“使具有某种性质或种类”，用于描述与赋予属性。"},{"era":"15C. qualificatio","en":"The noun qualificatio named the act of assigning a quality, and English took it up in the 15th century.","cn":"名词 qualificatio 命名赋予性质的行为，英语在 15 世纪吸收了它。"},{"era":"16C–17C. FITNESS AND LIMITS","en":"Legal and professional usage gave the word its two modern poles: being fit for an office, and adding a limiting condition to a claim.","cn":"法律与职业用法赋予这个词两个现代极点：适合某一职位，以及给陈述加上限制条件。"},{"era":"19C–20C. CERTIFICATES AND SPORT","en":"Public examinations made the certificate sense dominant, and sport adopted qualification for the preliminary round.","cn":"公共考试使证书义成为主流，体育则用 qualification 指预赛轮。"}]},"similar":{"note":{"en":"The look-alike group separates qualification from qualify, qualified and the quantity word quantification, which has a different root. The meaning group compares credentials, conditions and restrictions.","cn":"形近组区分 qualification 与 qualify、qualified，以及词根不同的 quantification；词义组比较资历凭证、条件与限制。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"qualify","ipa":"/ˈkwɒlɪfaɪ/","tag":"verb","definition":"to become fit, to make someone fit, or to limit a statement. It is the action behind every sense of the noun.","definitionCN":"取得资格、使合格，或限定陈述。它是名词各义项背后的动作。"},{"word":"qualified","ipa":"/ˈkwɒlɪfaɪd/","tag":"adjective","definition":"having the needed training, or stated with reservations. It describes the person or the approval.","definitionCN":"具备所需训练，或有保留地表述的。它描述人或认可。"},{"word":"qualifier","ipa":"/ˈkwɒlɪfaɪə/","tag":"noun","definition":"a word that limits another word, or a preliminary match. It names the limiter or the round, not the whole status.","definitionCN":"限定另一词的词，或预赛。它命名限定成分或轮次，而非整体资格。"},{"word":"quantification","ipa":"/ˌkwɒntɪfɪˈkeɪʃn/","tag":"noun","definition":"the act of measuring as a quantity. It looks similar but uses quantus 'how much', not qualis 'of what kind'.","definitionCN":"按数量测量的行为。它看起来相似，却用 quantus“多少”，而非 qualis“何种”。"}]},{"heading":"NEAR MEANING","entries":[{"word":"credential","ipa":"/kredˈenʃl/","tag":"noun","definition":"a qualification or document that proves trustworthiness. It is close to sense 02 but often implies proof of standing.","definitionCN":"证明可信度的资格或文件。它接近第 2 义项，但常暗含地位证明。"},{"word":"certification","ipa":"/ˌsɜːtɪfɪˈkeɪʃn/","tag":"noun","definition":"the process or document of official certification. It stresses the authority that grants it.","definitionCN":"官方认证的过程或文件。它强调授予认证的权威。"},{"word":"caveat","ipa":"/ˈkeɪviæt/","tag":"noun","definition":"a warning or condition attached to a statement. It is the sharp word for sense 03.","definitionCN":"附在陈述上的警告或条件。它是第 3 义项的锐利说法。"},{"word":"restriction","ipa":"/rɪˈstrɪkʃn/","tag":"noun","definition":"a rule that limits what may be done. It is the strongest word for sense 08.","definitionCN":"限制可做之事的规则。它是第 8 义项最强的说法。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks start from the checklist image, then let the same word cover a certificate, a doubt, a training path, a modifier, a prelim, a reservation and a clause.","cn":"这些记忆钩从勾选清单的画面出发，再让同一个词覆盖证书、疑虑、培训路径、修饰语、预赛、保留意见与条款。"},"normal":[{"en":"Split it as qual + i + fic + ation: what kind + make + noun. It names the making of a right kind of person.","cn":"拆成 qual + i + fic + ation：何种、使、名词。它命名把人变成合适类型的过程。"},{"en":"Picture a form with boxes to tick: only the person who fills every box enters the shortlist.","cn":"想象一张打钩的表：填满每一格的人才进候选名单。"},{"en":"The ticked form then becomes a certificate on the wall.","cn":"这张勾好的表后来变成挂在墙上的证书。"},{"en":"A qualification on a promise is a small box left unticked: agreement with one exception.","cn":"承诺上的限定就是留空的一小格：同意，但有一个例外。"},{"en":"A qualification round is the same shortlist, moved to a sports field.","cn":"预选赛就是同一份候选名单，被搬到了运动场。"}],"abstract":[{"en":"Hear the -fic- inside: the word is always about making someone or something fit a kind.","cn":"听见词里的 -fic-：这个词总是在讲使人或物适合某一类型。"},{"en":"Notice the two directions: outward proof (certificate) and inward limit (reservation).","cn":"注意两个方向：向外的证明（证书）与向内的限制（保留）。"},{"en":"Keep it away from quantification: one asks 'what kind', the other 'how much'.","cn":"把它与 quantification 分开：一个问“何种”，一个问“多少”。"}]},"examples":[{"en":"The fellowship lists a doctorate as a minimum qualification.","cn":"这项奖学金把博士学位列为最低资格。"},{"en":"She agreed to chair the panel, with the qualification that she could leave early.","cn":"她同意主持专家组，但附带一个条件：她可以提前离场。"},{"en":"Our team was eliminated in the qualification for the regional cup.","cn":"我们队在地区杯的预选赛中被淘汰。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“夸利非凯神”：夸你条件好、学历够，一张证书就神气起来。","word":"qualification"},"root":"中古拉丁 qualificare“使成为某种”（qualis 何种 + facere 使）的名词 qualificatio；核心是“把人或物变成合适的类型”。","sensesIntro":{"en":"The eight senses all concern fitness: the skills that fit a role, the paper that proves it, the training that produces it, the doubt that limits an agreement, the modifier that narrows a noun, the round that decides who may compete, the reservation on approval, and the clause that limits a right.","cn":"八个义项都关乎“适合”：适合某一角色的技能、证明它的纸、产生它的训练、限制协议的疑虑、收窄名词的修饰语、决定谁可参赛的轮次、认可上的保留，以及限制权利的条款。"},"semanticMap":{"core":{"en":"A person or statement is narrowed to fit a standard, and the fit is then certified or limited.","cn":"人或陈述被收窄到符合某一标准，随后这种符合被认证或被限制。"},"chain":["KIND","FIT","PROVE","LIMIT","COMPETE","CERTIFY"],"branches":[{"senses":"01 · 02","en":"FITNESS: skills and a certificate show that a person suits a role.","cn":"适合：技能与证书表明一个人适合某角色。"},{"senses":"03 · 07","en":"LIMIT: agreement is narrowed by a stated condition.","cn":"限制：同意被明说的条件收窄。"},{"senses":"04","en":"PROCESS: training and examination produce the fit kind of person.","cn":"过程：培训与考试产生合适类型的人。"},{"senses":"05 · 08","en":"SCOPE: a modifier or a legal clause cuts down what the words cover.","cn":"范围：修饰语或法律条款削减文字覆盖的范围。"},{"senses":"06","en":"COMPETITION: a preliminary round decides who is fit to enter.","cn":"竞争：预赛决定谁有资格进入。"}]},"affixes":{"intro":{"en":"Qualification is qualis plus facere plus the noun suffix -atio. The items below follow the same making verb through verb, adjective, agent and the parallel quantity family.","cn":"qualification 由 qualis、facere 与名词后缀 -atio 构成。下列条目沿着同一个“使”动词，走过动词、形容词、施动者，以及平行的数量词族。"},"latinIntro":{"en":"The Latin entries give the kind word and the making verb. They explain why qualification, quality and qualify all turn on 'what kind'.","cn":"拉丁语条目给出“何种”与“使”两个词，解释为什么 qualification、quality 与 qualify 都围绕“何种”。"},"items":[{"word":"qualification","structure":"qualificare + -atio (noun of action)","meaning":"fitness, certificate or limiting condition","meaningCN":"资格、证书或限定条件","example":"The certificate is a formal qualification.","exampleCN":"这张证书是正式资格证明。"},{"word":"qualify","structure":"qualificare","meaning":"to make or become fit; to limit","meaningCN":"使合格；取得资格；限定","example":"Two years of practice qualify her for the licence.","exampleCN":"两年实践使她符合执照要求。"},{"word":"qualified","structure":"qualify + -ed (participle)","meaning":"having met a standard; limited","meaningCN":"合格的；有保留的","example":"The panel gave qualified support.","exampleCN":"专家组给予了有保留的支持。"},{"word":"qualifier","structure":"qualify + -er (agent or instrument)","meaning":"a limiting word; a preliminary round","meaningCN":"限定词；预选赛","example":"In the phrase, the adjective is a qualifier.","exampleCN":"在该短语中，形容词是限定成分。"},{"word":"quality","structure":"qualitas, from qualis","meaning":"the kind or character of something","meaningCN":"性质；品质","example":"The quality of the soil improved.","exampleCN":"土壤的品质改善了。"},{"word":"qualitative","structure":"qualitas + -ive","meaning":"relating to quality","meaningCN":"定性的；性质的","example":"The study relied on qualitative evidence.","exampleCN":"这项研究依靠定性证据。"},{"word":"disqualification","structure":"dis- (not) + qualification","meaning":"the loss of fitness or the act of removing it","meaningCN":"取消资格","example":"The foul led to disqualification.","exampleCN":"这次犯规导致取消资格。"},{"word":"requalification","structure":"re- (again) + qualification","meaning":"the act of qualifying again","meaningCN":"重新取得资格","example":"Nurses complete requalification every three years.","exampleCN":"护士每三年完成一次资格复审。"}],"latinEntries":[{"word":"qualis","structure":"interrogative adjective","meaning":"of what kind","meaningCN":"何种的"},{"word":"facere","structure":"3rd conjugation verb","meaning":"to make, to do","meaningCN":"做；造"},{"word":"qualificatio","structure":"Medieval Latin noun","meaning":"a making of a certain kind","meaningCN":"使成为某种；资格"}]}},{"word":"qualified","ipa_uk":"/ˈkwɒlɪfaɪd/","ipa_us":"/ˈkwɑːləfaɪd/","definition_zh":"有资格的；合格的；持证的；有保留的；有条件的；有限的；（法律）受限的；（体育）通过预选赛的","definition_en":"having the training or right to do something, or stated with a limitation rather than absolutely","core_image":"名单上被打了勾的人，旁边却写着一个小小但书","scene":"The hospital appointed a qualified nurse to lead the infection control team.","sceneCN":"这里 qualified 是「具备执业资格的」（第 6 个义项：持有专业资格、可合法执业）；句意：医院任命了一位具备执业资格的护士来领导感染控制团队。图中可辨识物件：护士证、勾选过的任命文件。","pos":[{"tag":"adj.","zh":"有资格的；合格的；有保留的；有条件的"}],"collocations":[{"phrase":"highly qualified","zh":"资质很高的"},{"phrase":"qualified teacher","zh":"合格教师"},{"phrase":"qualified support","zh":"有保留的支持"},{"phrase":"qualified approval","zh":"有条件的批准"},{"phrase":"qualified for the final","zh":"获得决赛资格"},{"phrase":"fully qualified","zh":"完全合格的"}],"forms":[{"label":"原级","form":"qualified"},{"label":"比较级","form":"more qualified"},{"label":"最高级","form":"most qualified"},{"label":"动词","form":"qualify"},{"label":"名词","form":"qualification"}],"derivatives":[{"word":"qualify","pos":"v.","zh":"取得资格；使合格；限定"},{"word":"qualification","pos":"n.","zh":"资格；限定条件"},{"word":"unqualified","pos":"adj.","zh":"不合格的；无保留的"},{"word":"disqualified","pos":"adj.","zh":"被取消资格的"}],"senses":[{"no":"01","title":"Fit for the role","titleCN":"胜任该角色的","definition":"having the skills, knowledge or experience needed for a particular role","definitionCN":"具备某一角色所需的技能、知识或经验","example":"She is the best qualified candidate for the chair.","exampleCN":"她是该教席最合适的候选人。","why":"Qualified is the participle of qualify: the person has been made of the right kind for the job, so the role can be entrusted to them.","whyCN":"qualified 是 qualify 的分词：这个人已被塑造成适合这份工作的类型，因此可以把角色托付给他。"},{"no":"02","title":"Holding a certificate","titleCN":"持有证书的","definition":"possessing an official certificate, degree or licence","definitionCN":"持有正式证书、学位或执照的","example":"Only qualified electricians may work on the main supply.","exampleCN":"只有持证电工才能接触主电源。","why":"The paper sense follows the training sense: the certificate is the visible proof that the fitting has actually happened.","whyCN":"纸质义追随训练义：证书是“适合”确实发生过的可见证明。"},{"no":"03","title":"Said with a condition","titleCN":"附带条件的","definition":"expressed with a limitation or reservation rather than fully","definitionCN":"以带有限制或保留的方式表达，而非完全地","example":"The board offered qualified approval of the merger.","exampleCN":"董事会提出了有条件的合并批准。","why":"The participle that once meant 'made fit' now also means 'made smaller': approval has been given only of a limited kind, with a condition attached.","whyCN":"这个分词曾经表示“被塑造得合适”，现在也表示“被削小”：批准只以有限的种类给出，并附带条件。"},{"no":"04","title":"Not complete","titleCN":"不完全的","definition":"only partial, falling short of a full result","definitionCN":"仅部分的，未达到完整结果","example":"The campaign was a qualified success: membership rose, donations fell.","exampleCN":"这场运动算是有限的成功：会员增加，捐款下降。","why":"Here the limitation is on the result itself. A qualified success carries a silent 'but' behind the noun.","whyCN":"这里的限制落在结果本身。qualified success 在名词背后带着一个不说话的“但是”。"},{"no":"05","title":"Legally restricted","titleCN":"法律上受限的","definition":"of a right or power: limited by law or by a stated condition","definitionCN":"指权利或权力受法律或明定条件限制","example":"The estate passed to him as a qualified ownership, not outright.","exampleCN":"这份产业以受限所有权而非完全所有权转给他。","why":"Law narrows the right itself: the owner holds a particular kind of ownership, with conditions that an outright owner would not face.","whyCN":"法律把权利本身收窄：所有者持有的是一种特定所有权，附带完全所有者不会面对的条件。"},{"no":"06","title":"Licensed to practise","titleCN":"获准执业的","definition":"officially entitled to practise a profession after meeting its standards","definitionCN":"达到行业标准后正式获得执业权利","example":"No qualified pharmacist was on duty that night.","exampleCN":"那天夜里没有持证药师值班。","why":"Licensing turns fitness into a legal status: the pharmacist has met the professional standard, so the law allows the dispensing that an untrained person may not do.","whyCN":"执照把“适合”变成法律身份：药师达到了行业标准，因此法律允许其配药，而未受训者不能从事。"},{"no":"07","title":"Through the preliminaries","titleCN":"通过预选赛的","definition":"having won the right to enter the main competition","definitionCN":"已获得进入正赛的权利","example":"The qualified swimmers trained again before the final.","exampleCN":"通过预选赛的游泳选手在决赛前再次训练。","why":"Sport uses the same 'made fit' sense: the preliminaries certify that a competitor is of the right kind to enter the main field.","whyCN":"体育使用同一个“被塑造得合适”的义：预赛证明参赛者属于可以进入正赛的那一类。"},{"no":"08","title":"Grammatically limiting","titleCN":"语法上起限定作用的","definition":"of a word or phrase: serving to restrict or describe another element","definitionCN":"指词或短语起限制或描述另一成分的作用","example":"In 'a qualified offer', the adjective functions as a qualified modifier of the noun.","exampleCN":"在“a qualified offer”中，这个形容词对名词起限定修饰作用。","why":"Grammar keeps the limiting sense visible: a modifier qualifies a noun by saying which kind is meant.","whyCN":"语法让限制义保持可见：修饰语通过说明指的是哪一种，来限定名词。"}],"etymology":{"intro":{"en":"Qualified is the past participle of qualify, which comes from Medieval Latin qualificare, 'to make of a certain kind', from qualis 'of what kind' and facere 'to make'. The participle split into two careers: fit for a task, and limited by a condition.","cn":"qualified 是 qualify 的过去分词。qualify 来自中古拉丁 qualificare“使成为某种”，由 qualis“何种”与 facere“使”构成。这个分词后来分成两条路：适合某项任务，以及受条件限制。"},"items":[{"era":"LATIN qualis","en":"Qualis meant 'of what kind'. It underlies quality, qualify and all their relatives.","cn":"qualis 意为“何种”，是 quality、qualify 及其全部亲属词的根基。"},{"era":"LATIN facere","en":"Facere, 'to make', formed the second half of qualificare. The verb therefore means 'to make someone of a certain kind'.","cn":"facere“造、使”构成 qualificare 的后半。因此整个动词意为“使人成为某种类型”。"},{"era":"MEDIEVAL LATIN qualificare","en":"Scholastic writers used qualificare for assigning a quality to something or describing it under a head.","cn":"经院作者用 qualificare 指赋予某物一种性质，或在某一范畴下描述它。"},{"era":"15C–16C. ENGLISH qualify / qualified","en":"English borrowed qualify in the 15th century; the participle qualified soon became an adjective for people fit for an office.","cn":"英语在 15 世纪借入 qualify；分词 qualified 很快成为形容人适合某职位的形容词。"},{"era":"17C. THE LIMITING SENSE","en":"Legal and diplomatic writing added the limiting sense: a qualified statement is one whose force is cut back.","cn":"法律与外交写作增加了限制义：qualified 的陈述就是力度被削弱的陈述。"},{"era":"19C–20C. PROFESSIONS AND SPORT","en":"Licensing laws made 'qualified practitioner' standard, and sport made 'qualified for the final' a familiar phrase.","cn":"执照法使“持证从业者”成为标准，体育使“获得决赛资格”成为常见说法。"}]},"similar":{"note":{"en":"The look-alike group separates qualified from qualify, qualification and its negative forms. The meaning group contrasts being certified, being capable and being conditional.","cn":"形近组区分 qualified 与 qualify、qualification 及其否定形式；词义组比较“持证”“有能力”与“有条件”。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"qualify","ipa":"/ˈkwɒlɪfaɪ/","tag":"verb","definition":"to become or make fit; to limit. It is the action, while qualified is the resulting state.","definitionCN":"取得或使合格；限定。它是动作，而 qualified 是结果状态。"},{"word":"qualification","ipa":"/ˌkwɒlɪfɪˈkeɪʃn/","tag":"noun","definition":"the fitness, the certificate or the limiting condition. It names what the adjective implies.","definitionCN":"资格、证书或限定条件。它命名形容词所隐含的东西。"},{"word":"unqualified","ipa":"/ˌʌnˈkwɒlɪfaɪd/","tag":"adjective","definition":"lacking the training, or stated without any reservation. The prefix can negate either sense.","definitionCN":"缺乏训练的，或毫无保留地表述的。这个前缀能否定两种义项。"},{"word":"disqualified","ipa":"/dɪsˈkwɒlɪfaɪd/","tag":"adjective","definition":"declared no longer entitled, usually after a breach of rules.","definitionCN":"被宣布不再具备资格的，通常因违规。"}]},{"heading":"NEAR MEANING","entries":[{"word":"certified","ipa":"/ˈsɜːtɪfaɪd/","tag":"adjective","definition":"officially attested, often by a body. It stresses the stamp of authority, while qualified stresses meeting a standard.","definitionCN":"经官方证明的，常由某机构证明。它强调权威印章，而 qualified 强调达到标准。"},{"word":"competent","ipa":"/ˈkɒmpɪtənt/","tag":"adjective","definition":"having enough ability to do something well. It judges skill, not paper or conditions.","definitionCN":"具备足够能力做好某事。它判断技能，而不涉证书或条件。"},{"word":"conditional","ipa":"/kənˈdɪʃənl/","tag":"adjective","definition":"depending on a condition. It is the clear word for senses 03 and 05.","definitionCN":"取决于条件的。它是第 3 与第 5 义项的清晰说法。"},{"word":"limited","ipa":"/ˈlɪmɪtɪd/","tag":"adjective","definition":"restricted in extent. It is the plain word for sense 04.","definitionCN":"范围受限的。它是第 4 义项的平实说法。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks start from the ticked name with a small note beside it, then let the word cover jobs, licences, doubts, partial results, legal limits, practice, prelims and grammar.","cn":"这些记忆钩从“打了勾的名字旁边带一条小注”出发，再让这个词覆盖职位、执照、疑虑、部分结果、法律限制、执业、预赛与语法。"},"normal":[{"en":"Split it as qual + i + fied: what kind + made + adjective. The person has been made the right kind.","cn":"拆成 qual + i + fied：何种、被使成、形容词。这个人已被塑造成合适的类型。"},{"en":"Picture a shortlist where your name has a tick and a tiny asterisk.","cn":"想象一份候选名单，你的名字旁有一个勾和一个小小的星号。"},{"en":"The tick alone means 'fit for the job'; the asterisk alone means 'yes, but'.","cn":"只有勾表示“胜任工作”；只有星号表示“是的，但是……”。"},{"en":"A qualified success is the asterisk without the tick: it worked, partly.","cn":"有限的成功就是没有勾的星号：它奏效了，但只是一部分。"},{"en":"A qualified swimmer is a tick earned in the preliminaries.","cn":"通过预选赛的游泳选手，是在预赛里挣到的一个勾。"}],"abstract":[{"en":"Watch the two families: qualified by training and qualified by doubt share one word but opposite moods.","cn":"留意两个家族：因训练而合格与因疑虑而限定，共享一个词却情绪相反。"},{"en":"Keep the participle in view: qualified is what has already happened to the person or the statement.","cn":"让分词保持可见：qualified 是人或陈述身上已经发生的事。"},{"en":"Remember that unqualified can mean 'untrained' or 'without any but' - context decides.","cn":"记住 unqualified 既可指“未受训”，也可指“毫无保留”，由语境决定。"}]},"examples":[{"en":"Only a qualified surveyor can sign off the structural report.","cn":"只有持证测量师才能签署结构报告。"},{"en":"The minister gave the plan qualified backing while asking for cost checks.","cn":"部长对该计划给予有保留的支持，同时要求核查成本。"},{"en":"The team finished the season as qualified entrants to the continental cup.","cn":"这支球队以通过预选赛的身份结束了本赛季，进入洲际杯。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“夸利非的”：被夸条件够、学历到位，名字旁边就打了个勾。","word":"qualified"},"root":"中古拉丁 qualificare“使成为某种”的过去分词；核心是“已被塑造成合适类型”，引申出“打了勾”与“带但书”两种状态。","sensesIntro":{"en":"The eight senses split into two moods. In the first, someone has been made fit: for a role, by a certificate, by a licence, through a prelim. In the second, something has been cut back: approval with a condition, a partial success, a restricted right, a limiting modifier.","cn":"八个义项分成两种语气。第一种是人被塑造成合适：适合角色、有证书、有执照、通过预赛。第二种是被削减：带条件的批准、部分的成功、受限的权利、起限定的修饰语。"},"semanticMap":{"core":{"en":"A fit is made, then either certified as complete or marked with a but.","cn":"一种适合被造成，随后要么被认证为完整，要么被加上一个“但是”。"},"chain":["KIND","FIT","CERTIFY","LICENSE","LIMIT","PARTIAL"],"branches":[{"senses":"01 · 02","en":"FITNESS: training and a certificate show a person suits a role.","cn":"适合：训练与证书表明一个人适合某角色。"},{"senses":"03 · 04","en":"BUT: approval or success is real but carries a stated limit.","cn":"但是：批准或成功是真的，但带着明说的限度。"},{"senses":"05","en":"LAW: a right is granted with restricted scope.","cn":"法律：权利被授予，但范围受限。"},{"senses":"06 · 07","en":"ENTITLEMENT: a licence or a prelim result grants the right to act.","cn":"授权：执照或预赛结果授予行动权。"},{"senses":"08","en":"GRAMMAR: a modifier narrows what another word covers.","cn":"语法：修饰语收窄另一词的覆盖范围。"}]},"affixes":{"intro":{"en":"Qualified is qualificare plus the English participle ending -ed. The items below follow the same kind-making verb, including its negative and re-formed relatives.","cn":"qualified 是 qualificare 加英语分词词尾 -ed。下列条目沿着同一个“使成某种”动词，包括其否定与重构亲属词。"},"latinIntro":{"en":"The Latin entries give the kind word and the making verb. They explain why unqualified can mean both 'untrained' and 'without reserve'.","cn":"拉丁语条目给出“何种”与“使”两个词，解释了为什么 unqualified 既能指“未受训”，也能指“毫无保留”。"},"items":[{"word":"qualified","structure":"qualify + -ed (past participle)","meaning":"fit; certified; limited","meaningCN":"合格的；持证的；有保留的","example":"A qualified doctor signed the form.","exampleCN":"一位持证医生签署了表格。"},{"word":"qualify","structure":"qualificare","meaning":"to make fit; to limit","meaningCN":"使合格；限定","example":"The course qualifies you for the exam.","exampleCN":"这门课使你具备参加考试的资格。"},{"word":"qualification","structure":"qualify + -ication","meaning":"fitness, certificate or condition","meaningCN":"资格；证书；条件","example":"Her qualifications were verified.","exampleCN":"她的资格得到核实。"},{"word":"unqualified","structure":"un- (not) + qualified","meaning":"not trained, or without any reservation","meaningCN":"不合格的；无保留的","example":"They gave unqualified support.","exampleCN":"他们给予无保留的支持。"},{"word":"disqualified","structure":"dis- (away) + qualified","meaning":"stripped of the right to compete or act","meaningCN":"被取消资格的","example":"The runner was disqualified for a false start.","exampleCN":"这名跑者因抢跑被取消资格。"},{"word":"requalified","structure":"re- (again) + qualified","meaning":"certified again after review","meaningCN":"重新取得资格的","example":"She requalified as an instructor last spring.","exampleCN":"她去年春天重新取得了教练资格。"},{"word":"qualifier","structure":"qualify + -er","meaning":"a limiting word; a preliminary event","meaningCN":"限定词；预选赛","example":"The qualifier narrowed the meaning of the noun.","exampleCN":"这个限定词收窄了名词的含义。"},{"word":"quality","structure":"qualitas, from qualis","meaning":"the kind or character of a thing","meaningCN":"性质；品质","example":"The wood is of excellent quality.","exampleCN":"这种木材品质极佳。"}],"latinEntries":[{"word":"qualis","structure":"interrogative adjective","meaning":"of what kind","meaningCN":"何种的"},{"word":"facere","structure":"3rd conjugation verb","meaning":"to make","meaningCN":"造；使"},{"word":"qualificatus","structure":"Medieval Latin participle","meaning":"made of a certain kind","meaningCN":"被塑造成某种的"}]}},{"word":"quantification","ipa_uk":"/ˌkwɒntɪfɪˈkeɪʃn/","ipa_us":"/ˌkwɑːntəfəˈkeɪʃn/","definition_zh":"量化；定量化；以数量表示；（逻辑）量化；（统计）数值化处理","definition_en":"the act or result of expressing something as an amount, or the logical operation of stating how many things a claim covers","core_image":"把一整片模糊的灰色地带切成可计数的方格","scene":"The quantification of habitat loss allowed the two regions to be compared on one scale.","sceneCN":"这里 quantification 是「量化」（第 1 个义项：把栖地丧失换算成可比的数量）；句意：对栖息地丧失的量化使两个地区能在同一标尺上比较。图中可辨识物件：被切成方格的地图、标着面积数值的表格。","pos":[{"tag":"n.","zh":"量化；定量化；以数量表示；逻辑量化"}],"collocations":[{"phrase":"the quantification of risk","zh":"风险的量化"},{"phrase":"precise quantification","zh":"精确量化"},{"phrase":"quantification of uncertainty","zh":"不确定性的量化"},{"phrase":"logical quantification","zh":"逻辑量化"},{"phrase":"difficult of quantification","zh":"难以量化的"},{"phrase":"quantification methods","zh":"量化方法"}],"forms":[{"label":"单数","form":"quantification"},{"label":"复数","form":"quantifications"},{"label":"动词","form":"quantify"},{"label":"形容词","form":"quantitative"}],"derivatives":[{"word":"quantify","pos":"v.","zh":"量化；用数量表示"},{"word":"quantitative","pos":"adj.","zh":"定量的；数量的"},{"word":"quantifier","pos":"n.","zh":"量词；数量词"},{"word":"quantifiable","pos":"adj.","zh":"可量化的"}],"senses":[{"no":"01","title":"Turning something into amount","titleCN":"把某物换算成数量","definition":"the act of expressing a quality, feeling or process as a measurable amount","definitionCN":"把性质、感受或过程表达为可测量数量的行为","example":"The quantification of air quality made the health debate concrete.","exampleCN":"对空气质量的量化让健康争论变得具体。","why":"Before the conversion, air quality was a vague worry; afterwards it is an amount that can be compared, and the noun names that conversion.","whyCN":"在转换之前，空气质量只是一种模糊的担忧；转换之后它成了可比的数量，而这个名词命名的正是那次转换。"},{"no":"02","title":"The result of that act","titleCN":"量化后的结果","definition":"a statement or figure that gives the size of something previously unmeasured","definitionCN":"对先前未被测量之物给出大小的陈述或数字","example":"Their quantification puts the annual loss at about forty billion dollars.","exampleCN":"他们的量化结果把年度损失定在约四百亿美元。","why":"The noun can name either the act or its product. Here the figure itself is the quantification, a number standing for what used to be a worry or a guess.","whyCN":"这个名词既可指行为也可指产物。这里的数字本身就是量化结果，用一个数字代表过去的担忧或猜测。"},{"no":"03","title":"Scientific measurement","titleCN":"科学上的定量测量","definition":"the procedure of measuring a phenomenon in standard units so results can be repeated","definitionCN":"用标准单位测量现象、使结果可被重复的程序","example":"Accurate quantification of rainfall required a dense network of gauges.","exampleCN":"准确测量降雨需要密集的雨量计网络。","why":"Science insists on units: the phenomenon is converted into millimetres per station, so that another team can repeat the reading.","whyCN":"科学坚持单位：现象被换算成每站多少毫米，好让另一个团队可以重复读数。"},{"no":"04","title":"Logic: how many things","titleCN":"逻辑上指涉及多少对象","definition":"the logical operation that specifies how many members of a class a statement applies to","definitionCN":"指明一个陈述适用于某类中多少成员逻辑运算","example":"Modern logic expresses 'all' and 'some' as forms of quantification.","exampleCN":"现代逻辑把“所有”与“有些”表达为量化的形式。","why":"Logic borrowed the word from measurement: instead of measuring, it specifies the size of the set a claim applies to, whether all, some or none.","whyCN":"逻辑学从测量借来这个词：它不测量，而是规定主张所适用集合的大小，无论全部、部分还是没有。"},{"no":"05","title":"Statistics: making data countable","titleCN":"统计学上把数据变成可计数","definition":"the conversion of observations into countable values for analysis","definitionCN":"把观察转换为可计数数值以供分析","example":"The quantification of survey answers turned opinions into percentages.","exampleCN":"对问卷回答的量化把意见变成了百分比。","why":"Coding is the practical bridge: once each answer carries a number, frequencies and cross-tables become possible, and the noun names that coding.","whyCN":"编码是实际的桥：每个回答一旦带有数字，频次与交叉表就成为可能，而这个名词命名的正是这次编码。"},{"no":"06","title":"How much has been measured","titleCN":"量化的程度","definition":"the extent to which something has been reduced to measurable terms","definitionCN":"某物被化约为可测量术语的程度","example":"Critics questioned the quantification of well-being, since some losses never show up in the index.","exampleCN":"批评者质疑对幸福感的量化，因为有些损失永远不会出现在指数里。","why":"Here the noun names the extent of the reduction: something has been turned into terms, but not everything in it survives the conversion.","whyCN":"这里的名词命名化约的程度：某物已被变成术语，但它内部并非一切都经受住了转换。"},{"no":"07","title":"Language: how many","titleCN":"语言学上的数量表达","definition":"the grammatical or lexical expression of quantity, as in words like all, many or few","definitionCN":"语法或词汇上的数量表达，如 all、many、few 这类词","example":"Languages provide quantification through determiners, number words and prefixes.","exampleCN":"语言通过限定词、数词与词头提供数量表达。","why":"Grammar also needs a way to say 'how many': words like all and few are the linguistic counterpart of a counting operation.","whyCN":"语法也需要说出“多少”的方式：all 与 few 这类词就是计数操作在语言上的对应物。"},{"no":"08","title":"Converting results into numbers","titleCN":"把结果写成数值","definition":"the presentation of findings as numerical values rather than descriptions","definitionCN":"以数值而非描述呈现研究结果","example":"The final stage of the study was the quantification of every interview into coded scores.","exampleCN":"研究的最后阶段是把每份访谈量化成编码分数。","why":"Reporting closes the loop: the interviews are reduced to scores, and the noun names the last conversion that lets a table stand in for pages of speech.","whyCN":"报告闭合了循环：访谈被化约为分数，这个名词命名最后一次转换，让一张表可以代替数页言语。"}],"etymology":{"intro":{"en":"Quantification is quantus, 'how much', plus facere, 'to make', plus the noun suffix -atio. Medieval Latin quantificare meant 'to make into a quantity', and the noun quantificatio named that act. Logic and statistics gave the word its two technical homes.","cn":"quantification 由 quantus“多少”、facere“使”与名词后缀 -atio 构成。中古拉丁 quantificare 意为“使成数量”，名词 quantificatio 命名这一行为。逻辑学与统计学给了这个词两个技术归宿。"},"items":[{"era":"LATIN quantus","en":"Quantus was the word for 'how much, how many'. It supplies the first half of every quantity word in English.","cn":"quantus 是表示“多少”的词，为英语中每个数量词提供前半部分。"},{"era":"LATIN facere","en":"Facere meant 'to make'. The -ficare suffix built verbs of making, and -ficatio built their abstract nouns.","cn":"facere 意为“使”。-ficare 后缀构成使役动词，-ficatio 构成相应的抽象名词。"},{"era":"MEDIEVAL LATIN quantificare","en":"School Latin formed quantificare for 'to make into a quantity'. It described the process of assigning amount to a subject.","cn":"经院拉丁语造出 quantificare，意为“使成为数量”，描述给主体赋予大小的过程。"},{"era":"15C–17C. quantificatio IN ENGLISH","en":"English took quantification from the Latin noun, first in philosophical writing about quantity and quality.","cn":"英语从拉丁名词借入 quantification，最初出现在讨论量与质的哲学写作中。"},{"era":"19C. LOGIC AND MEASUREMENT","en":"De Morgan and later Frege made quantification a technical term for statements about all or some, while physical science made it a term for measurement.","cn":"德摩根与后来的弗雷格把 quantification 变成关于“所有”或“有些”的技术术语，物理科学则把它变成测量的术语。"},{"era":"20C. STATISTICS AND SOCIAL SCIENCE","en":"Survey research and economics spread quantification to coding, scoring and index-building.","cn":"调查研究与经济学把 quantification 扩散到编码、评分与指数构建。"}]},"similar":{"note":{"en":"The look-alike group separates quantification from quantify, quantitative and the kind-rooted qualification. The meaning group compares measurement, coding and logical counting.","cn":"形近组区分 quantification 与 quantify、quantitative，以及词根为“何种”的 qualification；词义组比较测量、编码与逻辑计数。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"quantify","ipa":"/ˈkwɒntɪfaɪ/","tag":"verb","definition":"to express as a quantity. It is the action that quantification names.","definitionCN":"表示为数量。它正是 quantification 所命名的动作。"},{"word":"quantitative","ipa":"/ˈkwɒntɪteɪtɪv/","tag":"adjective","definition":"relating to amount. It describes the data or method, not the act of converting.","definitionCN":"与数量相关的。它描述数据或方法，而非转换行为。"},{"word":"quantifier","ipa":"/ˈkwɒntɪfaɪə/","tag":"noun","definition":"a word such as all or some, or a symbol in logic. It is the instrument, not the whole process.","definitionCN":"诸如 all 或 some 的词，或逻辑符号。它是工具，而非整个流程。"},{"word":"qualification","ipa":"/ˌkwɒlɪfɪˈkeɪʃn/","tag":"noun","definition":"fitness, a certificate or a limiting condition. It looks parallel but uses qualis 'of what kind', not quantus 'how much'.","definitionCN":"资格、证书或限定条件。它看起来结构平行，却用 qualis“何种”，而非 quantus“多少”。"}]},{"heading":"NEAR MEANING","entries":[{"word":"measurement","ipa":"/ˈmeʒəmənt/","tag":"noun","definition":"the act of measuring with an instrument. It is the concrete procedure behind sense 03.","definitionCN":"用仪器测量的行为。它是第 3 义项背后的具体程序。"},{"word":"coding","ipa":"/ˈkəʊdɪŋ/","tag":"noun","definition":"assigning labels or numbers to observations. It is the practical step in sense 05.","definitionCN":"给观察分配标签或数字。它是第 5 义项中的实际步骤。"},{"word":"enumeration","ipa":"/ˌiːnjuːməˈreɪʃn/","tag":"noun","definition":"counting items one by one. It is narrower than quantification, which also assigns magnitudes.","definitionCN":"逐项计数。它比 quantification 窄，后者还赋予大小。"},{"word":"calibration","ipa":"/ˌkælɪˈbreɪʃn/","tag":"noun","definition":"adjusting an instrument to a standard. It makes measurement trustworthy but is not measurement itself.","definitionCN":"按标准调整仪器。它使测量可信，但本身不是测量。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks hold the picture of a grey stretch cut into countable squares, then let the word cover acts, results, science, logic, data, degree, language and reporting.","cn":"这些记忆钩保留“把灰色地带切成可数方格”的画面，再让这个词覆盖行为、结果、科学、逻辑、数据、程度、语言与报告。"},"normal":[{"en":"Split it as quant + i + fic + ation: how much + make + noun. It names the making of a quantity.","cn":"拆成 quant + i + fic + ation：多少、使、名词。它命名把某物变成数量的过程。"},{"en":"Picture a fog bank ruled into squares, each square given a number.","cn":"想象一片雾被划成方格，每个方格都标上数字。"},{"en":"The act of ruling is the process sense; the numbers written in the squares are the result sense.","cn":"划格的动作是过程义；写在方格里的数字是结果义。"},{"en":"In logic the squares are sets: 'all' and 'some' say how many squares a claim covers.","cn":"在逻辑中，方格是集合：“所有”与“有些”说明主张覆盖多少格。"},{"en":"In surveys the same ruling turns answers into percentages.","cn":"在调查中，同样的划格把回答变成百分比。"}],"abstract":[{"en":"Ask which half is meant: the making of numbers or the numbers made.","cn":"问清指的是哪一半：制造数字的过程，还是造出的数字。"},{"en":"Keep the qualis family separate: qualification asks what kind, quantification asks how much.","cn":"让 qualis 词族保持独立：qualification 问何种，quantification 问多少。"},{"en":"Notice that the word always involves loss: something rich is replaced by a thinner but countable stand-in.","cn":"注意这个词总伴随损失：丰富之物被一个更薄但可计数的替身取代。"}]},"examples":[{"en":"The quantification of coral loss relied on satellite images taken over a decade.","cn":"对珊瑚损失的量化依据是十年间拍摄的卫星影像。"},{"en":"In formal logic, quantification turns an open sentence into a definite claim.","cn":"在形式逻辑中，量化把开放语句变成确定主张。"},{"en":"Some critics doubt that the quantification of happiness can capture what matters.","cn":"一些批评者怀疑对幸福感的量化能否捕捉真正重要的东西。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“宽提非凯神”：把宽窄大小都提出来，非要用数字说清才神气。","word":"quantification"},"root":"中古拉丁 quantificare“使成数量”（quantus 多少 + facere 使）的名词 quantificatio；核心是“把不可数之物切成可数的方格”。","sensesIntro":{"en":"The eight senses follow one operation: make something countable. It can be an act or its figure, a measurement or a logic rule, a coding step, a degree, a word class, or the final numeric report. Something is always gained in comparison and lost in richness.","cn":"八个义项追随同一个操作：让某物可计数。它可以是行为或其数字，可以是测量或逻辑规则，可以是编码步骤、程度、词类，或最终的数字报告。总有比较上的所得，也总有丰富性的所失。"},"semanticMap":{"core":{"en":"A rich or vague thing is cut into countable units, and those units then carry the claim.","cn":"丰富或模糊之物被切成可计数单位，随后由这些单位承载主张。"},"chain":["VAGUE","CUT","COUNT","FIGURE","COMPARE","CLAIM"],"branches":[{"senses":"01 · 02","en":"ACT AND RESULT: the conversion happens, and then a figure stands for it.","cn":"行为与结果：转换发生，随后一个数字代表它。"},{"senses":"03 · 05","en":"METHOD: instruments and coding produce repeatable values.","cn":"方法：仪器与编码产生可重复的数值。"},{"senses":"04 · 07","en":"LOGIC AND LANGUAGE: 'all' and 'some' count the set a claim covers.","cn":"逻辑与语言：“所有”与“有些”计算主张覆盖的集合。"},{"senses":"06","en":"DEGREE: some things resist being reduced, and the word marks how far it went.","cn":"程度：有些事物抗拒化约，这个词标记化约走到了多远。"},{"senses":"08","en":"REPORT: findings appear as scores and indexes.","cn":"报告：研究结果以分数与指数出现。"}]},"affixes":{"intro":{"en":"Quantification is quantus plus -ficare plus -ficatio. The items below follow the making verb through quantifier, quantifiable and the parallel kind-rooted family.","cn":"quantification 由 quantus、-ficare 与 -ficatio 构成。下列条目沿着“使”动词，走过量词、可量化，以及平行的“何种”词族。"},"latinIntro":{"en":"The Latin entries give the amount word and the making verb. They show why quantify, quantification and quantitative all point to one conversion.","cn":"拉丁语条目给出“多少”与“使”两个词，说明为什么 quantify、quantification 与 quantitative 都指向同一次转换。"},"items":[{"word":"quantification","structure":"quantificare + -atio","meaning":"the act or result of making countable","meaningCN":"量化；量化结果","example":"Quantification of the loss took a full season.","exampleCN":"损失的量化花了一整季。"},{"word":"quantify","structure":"quantus + facere","meaning":"to make into a quantity","meaningCN":"量化","example":"The team could not quantify the damage.","exampleCN":"团队无法量化损害。"},{"word":"quantitative","structure":"quantitas + -ive","meaning":"relating to amount","meaningCN":"定量的；数量的","example":"The report is mostly quantitative.","exampleCN":"报告以定量内容为主。"},{"word":"quantifier","structure":"quantify + -er","meaning":"a word or symbol expressing quantity","meaningCN":"量词；量化符号","example":"'Every' is a universal quantifier.","exampleCN":"“每个”是全称量词。"},{"word":"quantifiable","structure":"quantify + -able","meaning":"able to be expressed as a quantity","meaningCN":"可量化的","example":"The benefits were real but not quantifiable.","exampleCN":"收益真实却无法量化。"},{"word":"quantitatively","structure":"quantitative + -ly","meaning":"in terms of amount","meaningCN":"定量地","example":"The two options differ quantitatively.","exampleCN":"这两个选项在数量上不同。"},{"word":"qualification","structure":"qualis + facere + -atio","meaning":"fitness or a limiting condition","meaningCN":"资格；限定条件","example":"The panel added a qualification to its report.","exampleCN":"专家组在报告中加了限定。"},{"word":"quality","structure":"qualitas, from qualis","meaning":"the kind or character of something","meaningCN":"性质；品质","example":"Quality cannot be counted the same way.","exampleCN":"性质无法以同样方式计数。"}],"latinEntries":[{"word":"quantus","structure":"interrogative adjective","meaning":"how much","meaningCN":"多少"},{"word":"facere","structure":"3rd conjugation verb","meaning":"to make","meaningCN":"造；使"},{"word":"quantificatio","structure":"Medieval Latin noun","meaning":"a making into quantity","meaningCN":"使成数量；量化"}]}},{"word":"questionnaire","ipa_uk":"/ˌkwestʃəˈneə/","ipa_us":"/ˌkwestʃəˈner/","definition_zh":"问卷；调查表；问题清单；（研究用的）问卷工具","definition_en":"a printed or digital set of questions used to collect information from a group of people","core_image":"一叠同样的问题发给很多人，回来的纸上写满勾选","scene":"Only half of the patients returned the follow-up questionnaire on sleep quality.","sceneCN":"这里 questionnaire 是「问卷」（第 1 个义项：一组书面问题构成的调查表）；句意：只有一半病人交回了关于睡眠质量的随访问卷。图中可辨识物件：同一叠表格、勾选方框、回邮信封。","pos":[{"tag":"n.","zh":"问卷；调查表；问题清单"}],"collocations":[{"phrase":"fill in a questionnaire","zh":"填写问卷"},{"phrase":"self-report questionnaire","zh":"自评问卷"},{"phrase":"questionnaire survey","zh":"问卷调查"},{"phrase":"return a questionnaire","zh":"交回问卷"},{"phrase":"online questionnaire","zh":"在线问卷"},{"phrase":"design a questionnaire","zh":"设计问卷"}],"forms":[{"label":"单数","form":"questionnaire"},{"label":"复数","form":"questionnaires"},{"label":"动词","form":"question"},{"label":"名词（单个问题）","form":"question"}],"derivatives":[{"word":"question","pos":"n./v.","zh":"问题；询问；质疑"},{"word":"questionable","pos":"adj.","zh":"可疑的；有问题的"},{"word":"questioner","pos":"n.","zh":"提问者；调查员"},{"word":"questioning","pos":"n./adj.","zh":"提问；质疑的"}],"senses":[{"no":"01","title":"A set of written questions","titleCN":"一组书面问题","definition":"a printed or digital form containing a series of questions for many respondents","definitionCN":"含一系列问题、供众多受访者使用的印刷或电子表格","example":"The clinic hands every new patient a short health questionnaire.","exampleCN":"诊所给每位新病人一份简短的健康问卷。","why":"The defining feature is sameness: one set of questions is given to many people, so the answers can later be lined up side by side.","whyCN":"决定性特征是相同：同一组问题给许多人，好让回答后来可以并排对齐。"},{"no":"02","title":"A research instrument","titleCN":"研究工具","definition":"a standardised tool used by researchers to collect comparable answers across a sample","definitionCN":"研究者用来在样本中收集可比回答的标准化工具","example":"The team validated the questionnaire before sending it to two thousand households.","exampleCN":"团队在对两千户发放前先验证了这份问卷。","why":"Research turned the form into an instrument: the same wording is given to everyone so that answers can be counted and compared.","whyCN":"研究把表格变成工具：同一套措辞给所有人，好让回答能被计数与比较。"},{"no":"03","title":"A clinical self-report","titleCN":"临床自评表","definition":"a standard set of questions on which a patient reports symptoms, mood or function","definitionCN":"由病人自报症状、情绪或功能的一套标准问题","example":"The depression questionnaire asks about the past two weeks only.","exampleCN":"这份抑郁自评问卷只询问过去两周的情况。","why":"Clinical use narrows the set to symptoms and a fixed time window, so that scores from different patients mean the same thing.","whyCN":"临床用法把问题集合收窄到症状与固定时间窗，使不同病人的分数含义相同。"},{"no":"04","title":"A survey by post or link","titleCN":"通过邮寄或链接进行的调查","definition":"the whole exercise of distributing forms and collecting completed answers","definitionCN":"分发表格并收集已填回答的整个活动","example":"Response rates to the postal questionnaire were lower than expected.","exampleCN":"邮寄问卷的回收率低于预期。","why":"The word can name the operation, not just the paper: a questionnaire is also the round of asking and collecting that the form makes possible.","whyCN":"这个词也能指整个操作而非仅指纸张：问卷也是这张表所促成的询问与回收轮次。"},{"no":"05","title":"A hiring or admissions form","titleCN":"招聘或入学的问题清单","definition":"a list of questions used by an employer or school to screen applicants","definitionCN":"雇主或学校用来筛选申请者的问题清单","example":"The application questionnaire asked candidates to describe a difficult decision.","exampleCN":"申请问卷要求候选人描述一次艰难的决定。","why":"Screening is a different purpose for the same instrument: identical questions let a hundred applicants be judged against one standard.","whyCN":"筛选是同一工具的另一种用途：相同的问题让上百名申请者按同一标准被评判。"},{"no":"06","title":"An online form","titleCN":"线上问卷","definition":"a digital questionnaire delivered by web link or app, often with automatic scoring","definitionCN":"通过网络链接或应用发放、常带自动计分的电子问卷","example":"The online questionnaire closed automatically after five hundred replies.","exampleCN":"在线问卷在收到五百份回复后自动关闭。","why":"The delivery method changed, the instrument did not: the same questions travel by link and return already encoded as data.","whyCN":"投递方式变了，工具没变：同样的问题通过链接发送，回来时已编码成数据。"},{"no":"07","title":"A structured interview schedule","titleCN":"结构化的访谈问题表","definition":"a fixed list of questions read aloud in the same order to every interviewee","definitionCN":"按同一顺序向每位受访者念出的固定问题清单","example":"Interviewers read the questionnaire aloud and recorded answers verbatim.","exampleCN":"访谈员朗读问卷并逐字记录回答。","why":"Reading aloud keeps the wording identical from one respondent to the next, which is what makes the answers comparable at all.","whyCN":"朗读使措辞在每位受访者之间保持完全一致，这正是回答得以比较的前提。"},{"no":"08","title":"A statistical data source","titleCN":"统计数据的来源","definition":"the instrument whose answers become variables in a statistical analysis","definitionCN":"其回答将成为统计分析变量的工具","example":"Income data in the study came from a household questionnaire.","exampleCN":"研究中的收入数据来自一份家庭问卷。","why":"Once answers are coded, the sheet becomes a column in a data set: that is how a paper instrument turns into statistical evidence.","whyCN":"回答一经编码，表格就成为数据集中的一列：纸质工具正是这样变成统计证据。"}],"etymology":{"intro":{"en":"Questionnaire is a French word, built from question plus the suffix -aire, which comes from Latin -arius. Question itself goes back to Latin quaestio and quaerere, 'to seek or ask'. English borrowed the French form in the 19th century, when social surveys began to need a name for the printed list.","cn":"questionnaire 是法语词，由 question 加后缀 -aire 构成，后者来自拉丁 -arius。question 本身可回溯到拉丁 quaestio 与 quaerere“寻求、询问”。英语在 19 世纪借入法语形式，当时社会调查开始需要为印刷问题清单起名。"},"items":[{"era":"LATIN quaerere","en":"Quaerere meant 'to seek, to ask, to inquire'. It is the verb behind question, query, inquiry, require and acquire.","cn":"quaerere 意为“寻求、询问、探究”，是 question、query、inquiry、require、acquire 背后的动词。"},{"era":"LATIN quaestio","en":"Quaestio named a seeking or an inquiry, and in legal use an investigation. French turned it into question.","cn":"quaestio 命名寻求或探究，法律上指调查。法语把它变成 question。"},{"era":"FRENCH question","en":"French question kept both the asking and the doubting senses, and English borrowed it in the Middle Ages.","cn":"法语 question 同时保留“询问”与“质疑”两义，英语在中世纪借入。"},{"era":"FRENCH -aire","en":"The French suffix -aire, from Latin -arius, marks a person or thing connected with something, as in bibliothécaire or questionnaire.","cn":"法语后缀 -aire 来自拉丁 -arius，标记与某物相关的人或物，如 bibliothécaire 与 questionnaire。"},{"era":"19C. FRENCH questionnaire","en":"French formed questionnaire in the 19th century for a set of questions used in an inquiry. English adopted the spelling unchanged.","cn":"法语在 19 世纪造出 questionnaire，指调查中使用的一组问题。英语原样采用了这个拼写。"},{"era":"20C. SURVEY SOCIETY","en":"Sample surveys, market research and clinical scales made the questionnaire a standard instrument with rules for design and validation.","cn":"抽样调查、市场研究与临床量表使问卷成为有设计与验证规范的标准工具。"}]},"similar":{"note":{"en":"The look-alike group separates questionnaire from question, questioner and the similar-looking but different-root quest. The meaning group compares surveys, polls and forms.","cn":"形近组区分 questionnaire 与 question、questioner，以及拼写相近但词根不同的 quest；词义组比较调查、民意测验与表格。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"question","ipa":"/ˈkwestʃən/","tag":"noun / verb","definition":"a single inquiry, or to ask. It is the base word, while questionnaire names a whole set.","definitionCN":"单个问题，或询问。它是基础词，而 questionnaire 命名整套问题。"},{"word":"questioner","ipa":"/ˈkwestʃənə/","tag":"noun","definition":"a person who asks questions. It names the asker, not the paper.","definitionCN":"提出问题的人。它命名提问者，而不是纸张。"},{"word":"questionable","ipa":"/ˈkwestʃənəbl/","tag":"adjective","definition":"doubtful or open to suspicion. It shares the root but moves toward doubt rather than inquiry.","definitionCN":"可疑的、有问题的。它共享词根，但转向怀疑而非询问。"},{"word":"quest","ipa":"/kwest/","tag":"noun","definition":"a long search or journey. It comes from the same seeking verb but names a search, not a form.","definitionCN":"漫长的寻找或旅程。它来自同一个“寻求”动词，却命名寻找，而非表格。"}]},{"heading":"NEAR MEANING","entries":[{"word":"survey","ipa":"/ˈsɜːveɪ/","tag":"noun / verb","definition":"the whole research exercise of collecting data from a sample. The questionnaire is only its instrument.","definitionCN":"从样本收集数据的整个研究活动。问卷只是它的工具。"},{"word":"poll","ipa":"/pəʊl/","tag":"noun","definition":"a count of opinions, usually political. It is a short survey, often with one or two questions.","definitionCN":"意见计数，通常指政治民调。它是简短调查，常只有一两个问题。"},{"word":"form","ipa":"/fɔːm/","tag":"noun","definition":"a document with blanks to complete. It collects facts, while a questionnaire collects answers to questions.","definitionCN":"留有空白待填的文件。它收集事实，而问卷收集对问题的回答。"},{"word":"inventory","ipa":"/ɪnˈventəri/","tag":"noun","definition":"a standard list of items or symptoms to be checked. In clinical use it is close to a questionnaire.","definitionCN":"供勾选的标准条目或症状清单。在临床用法中接近问卷。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks keep the picture of one stack of identical questions, then let it cover research, clinics, post, hiring, online forms, interviews and statistics.","cn":"这些记忆钩保留“一叠完全相同的问题”的画面，再让它覆盖研究、诊所、邮寄、招聘、线上表格、访谈与统计。"},"normal":[{"en":"Split it as question + aire: question + French noun ending. It is a set of questions wearing a French coat.","cn":"拆成 question + aire：问题、法语名词词尾。它是一组问题披着法语的衣裳。"},{"en":"Picture one stack of identical sheets handed to a whole room.","cn":"想象一叠完全相同的表格发给整个房间的人。"},{"en":"The returned sheets are what makes it research: same questions, comparable answers.","cn":"收回的表格才使它成为研究：同样的问题，可比的回答。"},{"en":"Tear one sheet off the stack and you have a form; keep the stack and you have a survey.","cn":"从一叠里撕下一张，你得到表格；保留整叠，你得到调查。"},{"en":"In a clinic the stack asks about symptoms; in an office it asks about decisions.","cn":"在诊所，这一叠问症状；在办公室，这一叠问决策。"}],"abstract":[{"en":"Notice that the noun names the instrument, not the finding: the results belong to the survey, not to the paper.","cn":"注意这个名词命名工具，而非发现：结果属于调查，而不属于纸张。"},{"en":"Keep the -aire ending visible: it is a French borrowing, so the spelling has no English -er.","cn":"让 -aire 词尾保持可见：它是法语借词，因此拼写里没有英语的 -er。"},{"en":"Remember the pair: a questionnaire is answered by respondents, an interview schedule is read by an interviewer.","cn":"记住配对：问卷由受访者填写，访谈问题表由访谈员朗读。"}]},"examples":[{"en":"Every participant completed a questionnaire on diet and exercise.","cn":"每位参与者都填写了一份饮食与运动问卷。"},{"en":"The questionnaire was translated into three languages before the survey began.","cn":"调查开始前，问卷被译成三种语言。"},{"en":"Researchers piloted the questionnaire on forty students to catch unclear wording.","cn":"研究者先在四十名学生中试用问卷，以发现含糊的措辞。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“快身耐儿”：快把身上耐性勾一勾，一张问卷问到底。","word":"questionnaire"},"root":"法语 questionnaire（19 世纪），由 question 加 -aire（源自拉丁 -arius）构成；question 出自拉丁 quaestio、quaerere“寻求、询问”。","sensesIntro":{"en":"Every sense is a set of identical questions: printed for a clinic, standardised for research, self-reported in medicine, mailed or linked, used to screen applicants, read aloud in interviews, and coded into statistical variables. The paper changes form; the sameness of the questions does not.","cn":"每个义项都是一组完全相同的问题：为诊所印制、为研究标准化、在医学中自评、通过邮寄或链接发放、用来筛选申请者、在访谈中朗读，并被编码成统计变量。纸张的形式在变，问题的同一性不变。"},"semanticMap":{"core":{"en":"One set of questions is repeated for many people so that the answers can be compared.","cn":"同一组问题被重复给许多人，好让回答可以比较。"},"chain":["QUESTION","SET","RESPONDENT","COLLECT","COMPARE","VARIABLE"],"branches":[{"senses":"01 · 02","en":"INSTRUMENT: a standard set of questions serves research.","cn":"工具：一套标准问题服务研究。"},{"senses":"03 · 08","en":"DATA: clinical reports and coded answers become variables.","cn":"数据：临床报告与被编码的回答变成变量。"},{"senses":"04 · 06","en":"DELIVERY: post and web links carry the same sheets outward.","cn":"发放：邮寄与网络链接把同样的表格送出去。"},{"senses":"05","en":"SCREENING: employers and schools use the list to judge applicants.","cn":"筛选：雇主与学校用这份清单判断申请者。"},{"senses":"07","en":"INTERVIEW: an interviewer reads the fixed list aloud in order.","cn":"访谈：访谈员按顺序朗读固定清单。"}]},"affixes":{"intro":{"en":"Questionnaire is question plus the French suffix -aire. The items below follow the asking verb through its person, adjective and the seeking relatives.","cn":"questionnaire 由 question 与法语后缀 -aire 构成。下列条目沿着“询问”动词，走过人称、形容词以及“寻求”亲属词。"},"latinIntro":{"en":"The Latin entries give the seeking verb and the inquiry noun. They explain why question, query, require and acquire all belong to one family.","cn":"拉丁语条目给出“寻求”动词与“探究”名词，解释为什么 question、query、require 与 acquire 同属一个词族。"},"items":[{"word":"questionnaire","structure":"question + -aire (French)","meaning":"a set of questions for many respondents","meaningCN":"问卷；调查表","example":"The questionnaire had twenty items.","exampleCN":"这份问卷有二十个题目。"},{"word":"question","structure":"quaestio, from quaerere","meaning":"an inquiry; to ask or doubt","meaningCN":"问题；询问；质疑","example":"One question remained unanswered.","exampleCN":"有一个问题仍未得到回答。"},{"word":"questioner","structure":"question + -er","meaning":"a person who asks","meaningCN":"提问者","example":"The questioner raised her hand again.","exampleCN":"提问者再次举手。"},{"word":"questioning","structure":"question + -ing","meaning":"the act of asking; showing doubt","meaningCN":"提问；质疑的","example":"The questioning lasted two hours.","exampleCN":"提问持续了两小时。"},{"word":"questionable","structure":"question + -able","meaning":"open to doubt","meaningCN":"可疑的","example":"The methods were questionable.","exampleCN":"这些方法值得怀疑。"},{"word":"query","structure":"quaere, 'ask!'","meaning":"a question or doubt raised","meaningCN":"疑问；询问","example":"She sent a query about the invoice.","exampleCN":"她就发票提出了疑问。"},{"word":"require","structure":"re- + quaerere","meaning":"to seek again, hence to demand","meaningCN":"要求；需要","example":"The job requires a licence.","exampleCN":"这份工作需要执照。"},{"word":"acquire","structure":"ad- + quaerere","meaning":"to seek toward oneself, hence to obtain","meaningCN":"获得；获取","example":"The museum acquired the painting in 1960.","exampleCN":"博物馆于 1960 年获得这幅画。"}],"latinEntries":[{"word":"quaerere","structure":"3rd conjugation verb","meaning":"to seek, to ask","meaningCN":"寻求；询问"},{"word":"quaestio","structure":"noun, 3rd declension","meaning":"a seeking; an inquiry","meaningCN":"探究；询问"},{"word":"-arius","structure":"Latin adjective and noun suffix","meaning":"connected with, belonging to","meaningCN":"与……相关的"}]}}]);
